var e=[{"id":"a1-pronomen","titleAr":"الضمائر الشخصية (A1)","titleDe":"Personalpronomen","summaryAr":"الضمائر الشخصية هي أساس بناء الجملة.","arabicContrast":"في العربية نتصل الضمائر بالأفعال أحياناً، لكن في الألمانية ��كون منفصلة دائماً وتأتي كفاعل.","whenToUseAr":"نستخدمها للإشارة للأشخاص أو الأشياء كفاعل في الجملة.","rules":["ich = أنا","du = أنتَ/أنتِ","er/sie/es = هو/هي/للمحايد","wir = نحن","ihr = أنتم","sie/Sie = هم/حضرتك"],"commonMistakes":[],"tipsAr":"الضمير Sie بحرف كبير يُستخدم للاحترام (حضرتك) للمفرد والجمع.","exercises":[]},{"id":"a2-modalverben","titleAr":"الأفعال المساعدة (A2)","titleDe":"Modalverben","summaryAr":"الأفعال المساعدة تغيّر معنى الفعل الأساسي في الجملة.","arabicContrast":"في العربية نقول (أستطيع أن ألعب)، في الألمانية الفعل الأساسي (ألعب) يذهب لآخر الجملة.","whenToUseAr":"للتعبير عن الاستطاعة، الإرادة، الوجوب، السماح.","rules":["können = يستطيع","müssen = يجب","wollen = يريد","dürfen = يُسمح له","sollen = ينبغي"],"commonMistakes":[],"tipsAr":"الفعل المساعد يأتي في المركز الثاني ويُصرّف، والفعل الأساسي يذهب لآخر الجملة بصيغة المصدر.","exercises":[]},{id:`perfekt`,titleAr:`الماضي – Perfekt (haben/sein + Partizip II)`,titleDe:`Perfekt`,summaryAr:`زمن الماضي الأكثر استعمالاً في الكلام اليومي. يتكون من فعل مساعد (haben أو sein) في المضارع + اسم المفعول (Partizip II) في نهاية الجملة.`,arabicContrast:`في العربية نقول "أكلتُ البيتزا" (فعل واحد). في الألمانية نحتاج كلمتين: فعل مساعد (haben/sein) يُصرَّف حسب الفاعل، و Partizip II يبقى ثابتاً في آخر الجملة. القاعدة: الفعل المساعد في المرتبة الثانية، و Partizip II في نهاية الجملة (قاعدة "الإطار" Satzklammer).`,whenToUseAr:`استخدم Perfekt:
• في الكلام اليومي عن أي حدث ماضٍ (99% من المحادثات).
• في الرسائل غير الرسمية والمنتديات وبريد الأصدقاء.
• لا تستخدمه في القصص والأخبار المكتوبة (هناك استخدم Präteritum).`,rules:[{title:`متى نستخدم haben ومتى sein؟`,contentAr:`نستخدم **sein** مع أفعال الحركة والتغيير (gehen, fahren, kommen, laufen, fliegen, bleiben, sein, werden, passieren). مع كل الأفعال الأخرى نستخدم **haben**.`,examples:[{de:`Ich habe gestern Pizza gegessen.`,ar:`أكلت بيتزا أمس.`},{de:`Ich bin nach Berlin gefahren.`,ar:`سافرت إلى برلين.`},{de:`Er ist ins Kino gegangen.`,ar:`ذهب إلى السينما.`},{de:`Wir haben viel gelernt.`,ar:`تعلمنا الكثير.`}]},{title:`تصريف Partizip II`,contentAr:`الأفعال القوية (غير منتظمة): ge- + جذر متغير + -en (مثل gegessen, gefahren, geschrieben). الأفعال الضعيفة (منتظمة): ge- + جذر + -t (مثل gemacht, gelernt). الأفعال المنتهية بـ -ieren لا تأخذ ge- (studiert, telefoniert). الأفعال القابلة للفصل: be-/ver-/ent-... لا تأخذ ge- (besucht, verstanden).`,examples:[{de:`machen → gemacht`,ar:`فعل → تم فعله`},{de:`gehen → gegangen`,ar:`يذهب → ذهب`},{de:`studieren → studiert`,ar:`يدرس → درس`},{de:`einkaufen → eingekauft`,ar:`يتسوق → تسوق`}]}],commonMistakes:[{wrong:`Ich habe nach Berlin gefahren.`,right:`Ich bin nach Berlin gefahren.`,explanationAr:`fahren فعل حركة → يأخذ sein وليس haben.`},{wrong:`Ich habe Pizza geessen.`,right:`Ich habe Pizza gegessen.`,explanationAr:`Partizip II لفعل essen هو gegessen (مع ge + g).`},{wrong:`Ich habe Medizin gestudiert.`,right:`Ich habe Medizin studiert.`,explanationAr:`الأفعال المنتهية بـ -ieren لا تأخذ ge- في Partizip II.`},{wrong:`Ich habe gegessen Pizza.`,right:`Ich habe Pizza gegessen.`,explanationAr:`Partizip II يأتي دائماً في نهاية الجملة (قاعدة الإطار).`}],tipsAr:[`احفظ قائمة الأفعال غير المنتظمة (starke Verben) — هي الأكثر استعمالاً: gehen→gegangen، sein→gewesen، essen→gegessen، trinken→getrunken، fahren→gefahren.`,`طريقة سهلة: أفعال الحركة (A→B) تأخذ sein، الباقي haben.`,`sein و bleiben و werden تأخذ sein حتى لو ليست حركة (استثناء).`,`عند الشك من Partizip II لفعل جديد، راجع قاموس Pons أو Duden.`],exercises:[{id:`p-ex-1`,promptAr:`اختر الفعل المساعد الصحيح:`,promptDe:`Ich ____ gestern ins Kino gegangen.`,options:[{id:`a`,de:`habe`},{id:`b`,de:`bin`},{id:`c`,de:`war`}],correct:`b`,explanationAr:`gehen = حركة → sein → ich bin gegangen.`},{id:`p-ex-2`,promptAr:`اختر Partizip II الصحيح لـ sprechen:`,promptDe:`Ich habe mit meinem Chef ____.`,options:[{id:`a`,de:`gesprecht`},{id:`b`,de:`gespracht`},{id:`c`,de:`gesprochen`}],correct:`c`,explanationAr:`sprechen فعل قوي: gesprochen.`},{id:`p-ex-3`,promptAr:`أين يقع Partizip II في الجملة؟`,promptDe:`Gestern ____ ich einen Film ____.`,options:[{id:`a`,de:`habe / gesehen`},{id:`b`,de:`gesehen / habe`},{id:`c`,de:`bin / gesehen`}],correct:`a`,explanationAr:`haben في المرتبة الثانية، gesehen في النهاية.`}]},{id:`praeteritum`,titleAr:`الماضي البسيط – Präteritum`,titleDe:`Präteritum`,summaryAr:`يُستخدم في النصوص المكتوبة (كالقصص والأخبار) ومع بعض الأفعال (sein, haben, werden والأفعال الشرطية – modal verbs) حتى في الكلام.`,rules:[{title:`الأفعال الأكثر شيوعاً في Präteritum`,contentAr:`احفظها بسرعة:`,examples:[{de:`ich war – du warst – er war – wir waren`,ar:`كنت – كنتَ – كان – كنا`},{de:`ich hatte – du hattest – er hatte – wir hatten`,ar:`كان لدي... إلخ`},{de:`ich konnte / musste / wollte / durfte / sollte`,ar:`الأفعال الشرطية في الماضي`},{de:`Ich wollte gestern kommen, aber ich konnte nicht.`,ar:`أردت أن آتي أمس لكن لم أستطع.`}]}]},{id:`akk-dat`,titleAr:`حالتَا النصب (Akkusativ) والجر (Dativ)`,titleDe:`Akkusativ und Dativ`,summaryAr:`أكثر نقطة قواعد تُربك الناطقين بالعربية. تعتمد على الفعل وعلى حروف الجر.`,arabicContrast:`في العربية تتغيّر حركة الحرف الأخير (الضمّة/الفتحة/الكسرة) لتُميّز الفاعل والمفعول. في الألمانية تتغيّر الأداة نفسها (der → den → dem → des). النجمة هنا: ألمانيا تعتمد على **الأداة** لا على تغيير أخر الكلمة. فكّر في Akk/Dat كـ"إعراب الأداة".`,whenToUseAr:`• Akkusativ = المفعول به المباشر (أفعل الشيء نفسه): Ich sehe den Mann.
• Dativ = المفعول به غير المباشر (أفعل لمصلحة شخص): Ich helfe dem Mann.
• القاعدة الذهبية: **Akkusativ يُجيب على "من/ماذا" (Wen/Was)، و Dativ يُجيب على "لمن" (Wem).**`,rules:[{title:`جدول أدوات التعريف والتنكير في كل الحالات`,contentAr:`هذا الجدول هو **أهم جدول في القواعد الألمانية**. احفظه جيداً.`,table:{caption:`الأدوات في الحالات الأربع (مع der/die/das/die-Plural و ein)`,headers:[`الحالة`,`مذكر (m)`,`مؤنث (f)`,`محايد (n)`,`جمع (Pl.)`],rows:[[`Nominativ (الفاعل)`,`der / ein`,`die / eine`,`das / ein`,`die / —`],[`Akkusativ (المفعول به)`,`den / einen`,`die / eine`,`das / ein`,`die / —`],[`Dativ (الجر)`,`dem / einem`,`der / einer`,`dem / einem`,`den / — (+n)`],[`Genitiv (المضاف إليه)`,`des / eines (+s)`,`der / einer`,`des / eines (+s)`,`der / —`]]}},{title:`Akkusativ – من/ماذا؟ (Wen? / Was?)`,contentAr:`يأتي بعد حروف الجر: **durch, für, gegen, ohne, um**. وبعد الأفعال: **haben, sehen, lesen, kaufen, essen, trinken, nehmen, suchen, brauchen…**`,examples:[{de:`Ich kaufe einen Apfel / eine Banane / ein Brot.`,ar:`أشتري تفاحة/موزة/خبزاً.`},{de:`Ich suche den Schlüssel.`,ar:`أبحث عن المفتاح.`},{de:`Für meinen Bruder.`,ar:`لأخي.`},{de:`Ohne meine Brille kann ich nichts lesen.`,ar:`بدون نظّارتي لا أستطيع القراءة.`},{de:`Ich gehe um den See.`,ar:`أمشي حول البحيرة.`}]},{title:`Dativ – لمن؟ (Wem?)`,contentAr:`يأتي بعد حروف الجر: **aus, bei, mit, nach, seit, von, zu, gegenüber**. وبعد الأفعال: **helfen, gefallen, schmecken, danken, antworten, gehören…**`,examples:[{de:`Ich helfe meinem Vater.`,ar:`أساعد والدي.`},{de:`Das Auto gehört meiner Schwester.`,ar:`السيارة ملك أختي.`},{de:`Ich wohne bei einer Freundin.`,ar:`أسكن عند صديقة.`}]},{title:`حروف الجر التي تأخذ الاثنين (Wechselpräpositionen)`,contentAr:`**an, auf, hinter, in, neben, über, unter, vor, zwischen**. مع حركة (Wohin?) = Akkusativ، مع مكان ثابت (Wo?) = Dativ.`,examples:[{de:`Ich gehe in die Schule. (Wohin? Akk.)`,ar:`أذهب إلى المدرسة.`},{de:`Ich bin in der Schule. (Wo? Dat.)`,ar:`أنا في المدرسة.`},{de:`Das Buch liegt auf dem Tisch. (Dat.)`,ar:`الكتاب على الطاولة.`},{de:`Ich lege das Buch auf den Tisch. (Akk.)`,ar:`أضع الكتاب على الطاولة.`}]}],commonMistakes:[{wrong:`Ich helfe meinen Freund.`,right:`Ich helfe meinem Freund.`,explanationAr:`فعل helfen يأخذ Dativ دائماً. المذكّر في Dativ يصبح meinem.`},{wrong:`Ich habe ein Hund.`,right:`Ich habe einen Hund.`,explanationAr:`haben يأخذ Akkusativ. der Hund → einen Hund.`},{wrong:`Ich gehe mit mein Bruder.`,right:`Ich gehe mit meinem Bruder.`,explanationAr:`mit + Dativ دائماً. mein → meinem (مذكّر Dativ).`},{wrong:`Ich danke meinen Lehrer.`,right:`Ich danke meinem Lehrer.`,explanationAr:`danken يأخذ Dativ وليس Akkusativ.`}],tipsAr:[`احفظ قائمة الأفعال التي تأخذ Dativ: helfen, danken, gehören, gefallen, schmecken, antworten, folgen, passen — ست أو سبع أفعال تكفي لـ90% من الحالات.`,`حروف الجر الثابتة مع Akk: **durch-für-gegen-ohne-um** — احفظها كلمة واحدة "DuFüGegOhUm".`,`حروف الجر الثابتة مع Dat: **aus-bei-mit-nach-seit-von-zu** ��� احفظها كجملة "Aus bei mit nach seit von zu".`,`لتحديد Akk أم Dat مع Wechselpräposition: اسأل "Wohin? (إلى أين؟ حركة)" أو "Wo? (أين؟ ثبات)".`],exercises:[{id:`ak-ex-1`,promptAr:`اختر الأداة الصحيحة (Akkusativ):`,promptDe:`Ich kaufe ____ neuen Computer.`,options:[{id:`a`,de:`ein`},{id:`b`,de:`einen`},{id:`c`,de:`einem`}],correct:`b`,explanationAr:`kaufen → Akk. der Computer (مذكّر Akk) → einen.`},{id:`ak-ex-2`,promptAr:`helfen + Dativ. اختر الصحيح:`,promptDe:`Kannst du ____ Mutter helfen?`,options:[{id:`a`,de:`meine`},{id:`b`,de:`meiner`},{id:`c`,de:`meinen`}],correct:`b`,explanationAr:`helfen = Dativ. die Mutter (مؤنث Dat) → meiner Mutter.`},{id:`ak-ex-3`,promptAr:`Wohin vs Wo:`,promptDe:`Das Kind spielt ____ Garten. (wo?)`,options:[{id:`a`,de:`in den`},{id:`b`,de:`in dem`},{id:`c`,de:`im`}],correct:`c`,explanationAr:`Wo? → Dativ. in + dem = im (اندماج).`},{id:`ak-ex-4`,promptAr:`mit + Dativ:`,promptDe:`Ich fahre mit ____ Auto zur Arbeit.`,options:[{id:`a`,de:`das`},{id:`b`,de:`dem`},{id:`c`,de:`den`}],correct:`b`,explanationAr:`mit + Dat، das Auto (محايد Dat) → dem Auto.`}]},{id:`nebensatz`,titleAr:`الجمل الجانبية – Nebensätze (weil, dass, wenn, obwohl)`,titleDe:`Nebensätze`,summaryAr:`في الجمل الجانبية يأتي الفعل المصرّف في النهاية. هذه نقطة أساسية في B1.`,arabicContrast:`في العربية نقول "أتعلّم الألمانية لأنني أعيش هنا" — ترتيب عادي. في الألمانية بعد أداة الربط (weil/dass/wenn/obwohl) ينتقل الفعل المصرّف إلى **آخر الجملة**. السبب: الألمانية تضع الفعل في الأواخر للدلالة على أن الجملة تابعة (subordinate).`,whenToUseAr:`استخدم الجمل الجانبية للربط بين فكرتين:
• **weil** = لأن (سبب). Ich komme nicht, **weil** ich krank **bin**.
• **dass** = بأنّ (نقل كلام). Ich denke, **dass** du recht **hast**.
• **wenn** = إذا/عندما (شرط). **Wenn** du Zeit **hast**, ruf an.
• **obwohl** = رغم أن. **Obwohl** es regnet, **gehe** ich raus.
• **damit** = لكي (هدف). Ich lerne, **damit** ich eine Arbeit **finde**.`,rules:[{title:`أدوات الربط الشائعة`,contentAr:`**weil** (لأن)، **dass** (بأنّ)، **wenn** (إذا/عندما)، **obwohl** (رغم أن)، **damit** (لكي)، **ob** (هل...؟)، **als** (عندما – ماضي)، **bevor / nachdem** (قبل/بعد).`,examples:[{de:`Ich lerne Deutsch, weil ich in Deutschland lebe.`,ar:`أتعلم الألمانية لأني أع��ش في ألمانيا.`},{de:`Ich weiß, dass du müde bist.`,ar:`أعرف أنك متعب.`},{de:`Wenn ich Zeit habe, besuche ich dich.`,ar:`إذا كان لدي وقت، أزورك.`},{de:`Obwohl es regnet, gehe ich spazieren.`,ar:`رغم أنها تمطر، سأذهب للمشي.`}]},{title:`الفعل في النهاية`,contentAr:`إذا كان الفعل مركّباً (Perfekt أو Modalverb + Infinitiv)، يأتي الفعل المساعد في النهاية جداً بعد الفعل الثاني.`,examples:[{de:`Ich sage, dass ich Deutsch gelernt habe.`,ar:`أقول إنني تعلمت الألمانية.`},{de:`Er sagt, dass er morgen kommen kann.`,ar:`يقول إنه يستطيع القدوم غداً.`}]}],commonMistakes:[{wrong:`Ich komme nicht, weil ich bin krank.`,right:`Ich komme nicht, weil ich krank bin.`,explanationAr:`بعد weil يجب أن يذهب الفعل (bin) إلى النهاية.`},{wrong:`Ich denke, dass er hat Recht.`,right:`Ich denke, dass er Recht hat.`,explanationAr:`hat في النهاية بعد dass.`},{wrong:`Wenn ich habe Zeit, komme ich.`,right:`Wenn ich Zeit habe, komme ich.`,explanationAr:`habe → النهاية بعد wenn. ثم في الجملة الرئيسية الفعل في المرتبة الثانية.`},{wrong:`Ich sage, dass ich Deutsch habe gelernt.`,right:`Ich sage, dass ich Deutsch gelernt habe.`,explanationAr:`في Perfekt داخل جملة جانبية: Partizip II قبل الفعل المساعد، والمساعد في النهاية.`}],tipsAr:[`قاعدة ذهبية: **بعد weil/dass/wenn/obwohl = الفعل في النهاية** (حفظها مرة واحدة يكفي).`,`عند الاستخدام الشفهي يسمح بعض الألمان بترتيب عادي بعد weil، لكن في الامتحان اتبع القاعدة الرسمية.`,`لاحظ الفاصلة (Komma) قبل أداة الربط — إلزامية.`,`إذا بدأت الجملة بالجملة الجانبية، الجملة الرئيسية تبدأ بالفعل مباشرة: *Weil ich krank bin, komme ich nicht.*`],exercises:[{id:`n-ex-1`,promptAr:`ضع الفعل في المكان الصحيح:`,promptDe:`Ich lerne Deutsch, weil ich in Deutschland ____.`,options:[{id:`a`,de:`lebe`},{id:`b`,de:`ich lebe`},{id:`c`,de:`wohne leben`}],correct:`a`,explanationAr:`لا نكرّر الفاعل، والفعل lebe في النهاية.`},{id:`n-ex-2`,promptAr:`Perfekt داخل جملة جانبية:`,promptDe:`Ich weiß, dass er gestern nach Berlin ____.`,options:[{id:`a`,de:`ist gefahren`},{id:`b`,de:`gefahren ist`},{id:`c`,de:`gefahren hat`}],correct:`b`,explanationAr:`Partizip II (gefahren) قبل الفعل المساعد (ist) في النهاية.`},{id:`n-ex-3`,promptAr:`اختر أداة الربط المناسبة:`,promptDe:`____ es regnet, nehme ich einen Regenschirm mit.`,options:[{id:`a`,de:`Weil`},{id:`b`,de:`Wenn`},{id:`c`,de:`Dass`}],correct:`b`,explanationAr:`Wenn = إذا/عندما (شرط عام).`}]},{id:`konjunktiv-2`,titleAr:`الـ Konjunktiv II (التمني والأدب)`,titleDe:`Konjunktiv II`,summaryAr:`يُستخدم لطلب شيء بأدب، للأمنيات، والشروط غير الواقعية. يُلزم حفظ بعض الأشكال.`,arabicContrast:`في العربية نستخدم "لو" للشرط غير الواقعي ("لو كنت غنياً") ونستخدم صيغة المضارع للطلب المهذّب ("هل يمكنك مساعدتي؟"). في الألمانية هناك شكل خاص ومتميّز للفعل يُسمّى Konjunktiv II لنقل نفس المعنيين. Konjunktiv II = "لو" + الأدب.`,whenToUseAr:`• **الطلب المهذّب**: Könnten Sie mir helfen? = هل تستطيع��ن مساعدتي؟
• **الرغبة المهذّبة**: Ich hätte gern einen Tee. = أود شاياً.
• **الشرط غير الواقعي**: Wenn ich Zeit hätte, würde ich reisen. = لو كان لديّ وقت، لسافرت.
• **النصيحة**: An deiner Stelle würde ich … = لو كنت مكانك...
• **الأمنيات**: Ich wünschte, ich wäre reich. = أتمنى لو كنت غنياً.`,rules:[{title:`أشكال أساسية`,contentAr:`نستخدم كثيراً **würde + Infinitiv** لأي فعل. هناك أشكال خاصة لبعض الأفعال المهمة:`,examples:[{de:`ich hätte / du hättest / er hätte`,ar:`لو كان عندي... (من haben)`},{de:`ich wäre / du wärst / er wäre`,ar:`لو كنت... (من sein)`},{de:`ich könnte / du könntest / er könnte`,ar:`أستطيع (بأدب)`},{de:`Ich würde gern ein Kaffee trinken.`,ar:`أحب أن أشرب قهوة.`}]},{title:`استخدامات شائعة`,contentAr:`عبارات أدب، وأمنيات، وشروط غير واقعية.`,examples:[{de:`Könnten Sie mir bitte helfen?`,ar:`هل تستطيعون مساعدتي من فضلكم؟`},{de:`Ich hätte gern einen Tee.`,ar:`أريد شاياً من فضلك.`},{de:`Wenn ich reich wäre, würde ich viel reisen.`,ar:`لو كنت غنياً، لسافرت كثيراً.`},{de:`An deiner Stelle würde ich zum Arzt gehen.`,ar:`لو كنت مكانك، لذهبت إلى الطبيب.`}]}],commonMistakes:[{wrong:`Kannst du mir helfen bitte?`,right:`Könntest du mir bitte helfen?`,explanationAr:`في الطلب المهذّب استخدم Konjunktiv II (könntest) بدل Präsens (kannst).`},{wrong:`Ich will einen Kaffee.`,right:`Ich hätte gern einen Kaffee. / Ich möchte einen Kaffee.`,explanationAr:`في المطاعم والمحلات، "Ich will" فظّ. استخدم hätte gern أو möchte.`},{wrong:`Wenn ich Zeit habe, würde ich reisen.`,right:`Wenn ich Zeit hätte, würde ich reisen.`,explanationAr:`للشرط غير الواقعي: Konjunktiv II في الجزأين (hätte + würde).`}],tipsAr:[`للسهولة: استخدم **würde + Infinitiv** مع أي فعل (ich würde gehen، du würdest essen).`,`استثناءات مهمة: haben → hätte، sein → wäre، werden → würde. الأفعال الشرطية: könnte, müsste, wollte, dürfte, sollte.`,`في المطعم دائماً: "Ich hätte gern …" أو "Ich möchte …".`,`في الرسائل الرسمية: "Könnten Sie bitte …", "Ich würde mich freuen, wenn …".`],exercises:[{id:`k-ex-1`,promptAr:`طلب مهذّب:`,promptDe:`____ Sie mir bitte das Salz reichen?`,options:[{id:`a`,de:`Können`},{id:`b`,de:`Könnten`},{id:`c`,de:`Konnten`}],correct:`b`,explanationAr:`Könnten = Konjunktiv II، الأكثر تهذيباً.`},{id:`k-ex-2`,promptAr:`شرط غير واقعي:`,promptDe:`Wenn ich mehr Geld ____, würde ich ein Auto kaufen.`,options:[{id:`a`,de:`habe`},{id:`b`,de:`hätte`},{id:`c`,de:`hatte`}],correct:`b`,explanationAr:`hätte = Konjunktiv II (لأن الشرط خيالي).`},{id:`k-ex-3`,promptAr:`رغبة مهذّبة في المقهى:`,promptDe:`Ich ____ gern einen Cappuccino.`,options:[{id:`a`,de:`habe`},{id:`b`,de:`hätte`},{id:`c`,de:`hatte`}],correct:`b`,explanationAr:`Ich hätte gern … = الصيغة الأكثر تهذيباً للطلب.`}]},{id:`passiv`,titleAr:`المبني للمجهول – Passiv (werden + Partizip II)`,titleDe:`Passiv`,summaryAr:`يُستخدم للتركيز على الحدث بدل الفاعل. كثير في النصوص الرسمية والأخبار.`,rules:[{title:`التكوين`,contentAr:`werden (مصرّف) + Partizip II في نهاية الجملة.`,examples:[{de:`Das Auto wird repariert.`,ar:`يتم إصلاح السيارة.`},{de:`Der Brief wurde gestern geschrieben.`,ar:`كُتبت الرسالة أمس.`},{de:`In Deutschland wird Deutsch gesprochen.`,ar:`تُتَكلم الألمانية في ألمانيا.`}]}]},{id:`adjektive`,titleAr:`تصريف الصفات – Adjektivdeklination`,titleDe:`Adjektivdeklination`,summaryAr:`عندما تكون الصفة قبل الاسم، تأخذ نهاية. تعتمد على أداة التعريف/التنكير والجنس والحالة.`,rules:[{title:`بعد أداة التعريف der/die/das (النوع الضعيف)`,contentAr:`النهاية غالباً -e في الرفع وصيغة المؤنث والحيادي، و-en في باقي الحالات والجمع.`,examples:[{de:`der neue Mann, die neue Frau, das neue Kind`,ar:`الرجل الجديد...`},{de:`Ich sehe den neuen Mann.`,ar:`(Akk.) أرى الرجل الجديد.`},{de:`mit dem neuen Auto`,ar:`(Dat.) بالسيارة الجديدة.`}]},{title:`بعد أداة النكرة ein/eine (النوع المختلط)`,contentAr:`النهاية تظهر الجنس والحالة بوضوح لأن أداة النكرة لا تبيّنها.`,examples:[{de:`ein neuer Mann, eine neue Frau, ein neues Kind`,ar:`رجل جديد...`},{de:`mit einem neuen Auto`,ar:`(Dat.) بسيارة جديدة.`}]}]},{id:`trennbare`,titleAr:`الأفعال القابلة للفصل – Trennbare Verben`,titleDe:`Trennbare Verben`,summaryAr:`أفعال تحتوي على بادئة قابلة للفصل مثل: **auf-**, **an-**, **aus-**, **ein-**, **mit-**, **zu-**، يتم فصلها في المضارع والأمر، وتبقى مع بعضها في الجملة الجانبية والمصدر.`,rules:[{title:`في الجملة الرئيسية`,contentAr:`البادئة تذهب إلى نهاية الجملة.`,examples:[{de:`aufstehen → Ich stehe um 7 Uhr auf.`,ar:`أنهض الساعة 7.`},{de:`einkaufen → Sie kauft heute ein.`,ar:`تتسوق اليوم.`},{de:`anrufen → Ich rufe dich an.`,ar:`سأتصل بك.`}]},{title:`في Perfekt و Nebensatz`,contentAr:`في Partizip II: ge- بين البادئة والجذر. في Nebensatz: البادئة ملصقة.`,examples:[{de:`Ich habe ihn angerufen.`,ar:`اتصلت به.`},{de:`…, weil ich früh aufstehe.`,ar:`لأني أنهض مبكراً.`}]}]},{id:`relativsatz`,titleAr:`جملة الصلة – Relativsatz (der/die/das)`,titleDe:`Relativsätze`,summaryAr:`تُعرِّف اسماً بمعلومة إضافية. ضمير الصلة يتفق مع جنس الاسم السابق، وحالته تعتمد على دور الاسم في جملة الصلة.`,rules:[{title:`أساسيات`,contentAr:`الضمير يأتي في بداية جملة الصلة، والفعل المصرّف في النهاية.`,examples:[{de:`Der Mann, der neben mir wohnt, ist Lehrer.`,ar:`الرجل الذي يسكن بجانبي مدرّس.`},{de:`Die Frau, die ich gestern gesehen habe, kommt aus Syrien.`,ar:`المرأة التي رأيتها بالأمس من سوريا.`},{de:`Das Buch, das auf dem Tisch liegt, ist meins.`,ar:`الكتاب الذي على الطاولة لي.`},{de:`Die Leute, mit denen ich spreche, sind nett.`,ar:`(Dat./Pl.) الناس الذين أتحدث معهم لطفاء.`}]}]},{id:`modalverben`,titleAr:`الأفعال الشرطية – Modalverben`,titleDe:`Modalverben`,summaryAr:`**können** (يستطيع)، **müssen** (يجب)، **sollen** (ينبغي)، **wollen** (يريد)، **dürfen** (يُسمح)، **möchten** (يودّ). يأتي الفعل الرئيسي في نهاية الجملة بصيغة المصدر (Infinitiv).`,arabicContrast:`في العربية نقول "يجب أن أذهب" — فعلان منفصلان. في الألمانية يكون الفعل الشرطي في المرتبة الثانية، والفعل الرئيسي (Infinitiv) في نهاية الجملة. لا نستخدم "zu" بينهما (بعكس الإنجليزية I have to go).`,whenToUseAr:`• **können** = القدرة/الاستطاعة. Ich kann schwimmen.
• **müssen** = الواجب/الضرورة. Ich muss arbeiten.
• **dürfen** = الإذن. Darf ich rauchen?
• **sollen** = نقل توجيه/نصيحة. Du sollst mehr Wasser trinken.
• **wollen** = الإرادة القوية. Ich will Arzt werden.
• **möchten** = رغبة مهذّبة (أكثر أدباً من wollen). Ich möchte einen Kaffee.`,rules:[{title:`تصريف Modalverben في المضارع`,contentAr:`الأفعال الشرطية غير منتظمة في الضمائر المفرد (ich/du/er). تذكر: ich و er لهما نفس الشكل!`,table:{caption:`جدول تصريف Modalverben`,headers:[`الضمير`,`können`,`müssen`,`wollen`,`dürfen`,`sollen`,`möchten`],rows:[[`ich`,`kann`,`muss`,`will`,`darf`,`soll`,`möchte`],[`du`,`kannst`,`musst`,`willst`,`darfst`,`sollst`,`möchtest`],[`er/sie/es`,`kann`,`muss`,`will`,`darf`,`soll`,`möchte`],[`wir`,`können`,`müssen`,`wollen`,`dürfen`,`sollen`,`möchten`],[`ihr`,`könnt`,`müsst`,`wollt`,`dürft`,`sollt`,`möchtet`],[`sie/Sie`,`können`,`müssen`,`wollen`,`dürfen`,`sollen`,`möchten`]]}},{title:`موقع الفعل الرئيسي (Infinitiv)`,contentAr:`الفعل الشرطي في المرتبة الثانية، والفعل الرئيسي في صيغة المصدر يأتي في **نهاية الجملة**. هذا ما يسمى Satzklammer.`,examples:[{de:`Ich kann sehr gut Arabisch sprechen.`,ar:`أستطيع التحدث بالعربية جيداً.`},{de:`Du musst um 9 Uhr zur Arbeit gehen.`,ar:`يجب أن تذهب إلى العمل الساعة 9.`},{de:`Darf ich ein Glas Wasser haben?`,ar:`هل يمكنني شرب كأس ماء؟`},{de:`Ich möchte nach Hause gehen.`,ar:`أود الذهاب إلى البيت.`}]},{title:`Modalverben في الماضي (Präteritum)`,contentAr:`نستخدم Präteritum مع Modalverben حتى في الكلام الشفهي (لا نستخدم Perfekt).`,table:{caption:`Modalverben في Präteritum`,headers:[`Infinitiv`,`ich-form (Präteritum)`],rows:[[`können`,`konnte`],[`müssen`,`musste`],[`wollen`,`wollte`],[`dürfen`,`durfte`],[`sollen`,`sollte`],[`mögen`,`mochte`]]}}],commonMistakes:[{wrong:`Ich muss zu arbeiten gehen.`,right:`Ich muss arbeiten gehen.`,explanationAr:`لا نستخدم "zu" مع Modalverben.`},{wrong:`Ich kann sprechen gut Deutsch.`,right:`Ich kann gut Deutsch sprechen.`,explanationAr:`sprechen (Infinitiv) دائماً في نهاية الجملة.`},{wrong:`Er kannt nicht kommen.`,right:`Er kann nicht kommen.`,explanationAr:`er يستخدم نفس صيغة ich: "er kann" (بدون -t).`},{wrong:`Ich habe gestern arbeiten müssen.`,right:`Ich musste gestern arbeiten.`,explanationAr:`Modalverben تستخدم Präteritum في الكلام اليومي، ليس Perfekt.`}],tipsAr:[`القاعدة الذهبية: "Modalverb في المرتبة 2 + Infinitiv في النهاية".`,`möchten هو شكل Konjunktiv II من mögen، لذلك صرفه مختلف قليلاً (möchte/möchtest).`,`في الطلبات المهذّبة استخدم **möchten** أو **könnten** بدل wollen/können.`,`في الماضي استخدم Präteritum (ich konnte, ich musste) لا Perfekt.`],exercises:[{id:`m-ex-1`,promptAr:`اختر التصريف الصحيح:`,promptDe:`Er ____ heute nicht kommen, er ist krank.`,options:[{id:`a`,de:`kann`},{id:`b`,de:`kannt`},{id:`c`,de:`können`}],correct:`a`,explanationAr:`er kann (بدون -t).`},{id:`m-ex-2`,promptAr:`أين يقع Infinitiv؟`,promptDe:`Ich muss morgen früh ____.`,options:[{id:`a`,de:`aufstehen`},{id:`b`,de:`aufstehe`},{id:`c`,de:`aufgestanden`}],correct:`a`,explanationAr:`بعد Modalverb نحتاج Infinitiv في النهاية.`},{id:`m-ex-3`,promptAr:`في الماضي:`,promptDe:`Gestern ____ ich lange arbeiten.`,options:[{id:`a`,de:`habe müssen`},{id:`b`,de:`musste`},{id:`c`,de:`bin gemusst`}],correct:`b`,explanationAr:`Präteritum: musste (أفضل من Perfekt مع Modalverben).`}]},{id:`wechselpraepositionen`,titleAr:`حروف الجر المتغيّرة (Wechselpräpositionen)`,titleDe:`Wechselpräpositionen`,summaryAr:`تسعة حروف جر تأخذ Akkusativ مع الحركة (Wohin?) وتأخذ Dativ مع المكان الثابت (Wo?).`,rules:[{title:`القاعدة الأساسية`,contentAr:`**Wohin? (إلى أين؟)** = حركة → **Akkusativ**.
**Wo? (أين؟)** = مكان ثابت → **Dativ**.`,table:{caption:`تسعة حروف الجر المتغيّرة`,headers:[`الحرف`,`المعنى`,`مثال Akk. (Wohin?)`,`مثال Dat. (Wo?)`],rows:[[`an`,`على/عند (سطح عمودي)`,`Ich hänge das Bild an die Wand.`,`Das Bild hängt an der Wand.`],[`auf`,`على (سطح أفقي)`,`Ich lege das Buch auf den Tisch.`,`Das Buch liegt auf dem Tisch.`],[`hinter`,`خلف`,`Ich gehe hinter das Haus.`,`Ich stehe hinter dem Haus.`],[`in`,`داخل`,`Ich gehe in die Schule.`,`Ich bin in der Schule.`],[`neben`,`بجانب`,`Setz dich neben mich!`,`Er sitzt neben mir.`],[`über`,`فوق`,`Die Lampe geht über den Tisch.`,`Die Lampe hängt über dem Tisch.`],[`unter`,`تحت`,`Die Katze geht unter das Bett.`,`Die Katze ist unter dem Bett.`],[`vor`,`أمام`,`Stell dich vor die Tür!`,`Ich stehe vor der Tür.`],[`zwischen`,`بين`,`Setz dich zwischen Anna und mich.`,`Ich sitze zwischen Anna und dir.`]]}},{title:`الفعل يدلّك على الحالة`,contentAr:`**أفعال الحركة (legen, stellen, setzen, hängen-trans, gehen, fahren)** → Akkusativ.
**أفعال الموضع (liegen, stehen, sitzen, hängen-intrans, sein, bleiben)** → Dativ.`,examples:[{de:`Ich stelle die Vase auf den Tisch. (Akk.)`,ar:`أضع الفازة على الطاولة (حركة).`},{de:`Die Vase steht auf dem Tisch. (Dat.)`,ar:`الفازة على الطاولة (مكان).`},{de:`Hänge die Jacke an den Haken!`,ar:`علّق المعطف على الخطّاف.`},{de:`Die Jacke hängt an dem Haken.`,ar:`المعطف معلّق على الخطّاف.`}]}]},{id:`komparativ`,titleAr:`المقارنة والتفضيل – Komparativ & Superlativ`,titleDe:`Steigerung der Adjektive`,summaryAr:`كيف نقول "أطول" و"الأطول" بالألمانية.`,rules:[{title:`القاعدة`,contentAr:`**Komparativ (المقارنة)** = الصفة + **er** → schnell → schneller.
**Superlativ (التفضيل)** = am + الصفة + **sten** → schnell → am schnellsten.`,table:{caption:`أمثلة الصرف`,headers:[`Positiv`,`Komparativ`,`Superlativ`,`الأمثلة`],rows:[[`schnell`,`schneller`,`am schnellsten`,`سريع / أسرع / الأسرع`],[`klein`,`kleiner`,`am kleinsten`,`صغير / أصغر / الأصغر`],[`alt`,`älter`,`am ältesten`,`عجوز (مع Umlaut)`],[`groß`,`größer`,`am größten`,`كبير`],[`gut`,`besser`,`am besten`,`جيد (شاذ)`],[`viel`,`mehr`,`am meisten`,`كثير (شاذ)`],[`gern`,`lieber`,`am liebsten`,`يحب → يفضّل (شاذ)`],[`hoch`,`höher`,`am höchsten`,`عالٍ`]]}},{title:`استخدامات`,contentAr:`**als** للمقارنة بين شيئين، **wie** للمساواة (so … wie).`,examples:[{de:`Berlin ist größer als Damaskus.`,ar:`برلين أكبر من دمشق.`},{de:`Mein Bruder ist so alt wie ich.`,ar:`أخي بعمري.`},{de:`Der Sommer ist heißer als der Winter.`,ar:`الصيف أحرّ من الشتاء.`},{de:`Das ist das beste Restaurant der Stadt.`,ar:`هذا أفضل مطعم في المدينة.`},{de:`Ich trinke am liebsten Tee.`,ar:`أحب الشاي أكثر شيء.`}]}]},{id:`genitiv`,titleAr:`حالة المضاف إليه – Genitiv`,titleDe:`Genitiv`,summaryAr:`تستخدم في الكتابة الرسمية وللتعبير عن الملكية. في الحياة اليومية يستعاض عنها بـ "von + Dativ".`,rules:[{title:`الأدوات`,contentAr:`مذكر/محايد: **des** + اسم +**(e)s**. مؤنث/جمع: **der**.`,table:{headers:[`الجنس`,`الأداة`,`مثال`,`الترجمة`],rows:[[`m`,`des …(e)s`,`das Auto des Vaters`,`سيارة الأب`],[`n`,`des …(e)s`,`das Spielzeug des Kindes`,`لعبة الطفل`],[`f`,`der`,`das Buch der Mutter`,`كتاب الأم`],[`Pl.`,`der`,`die Bücher der Studenten`,`كتب الطلاب`]]}},{title:`حروف جر مع Genitiv`,contentAr:`**während** (أثناء)، **wegen** (بسبب)، **trotz** (رغم)، **statt** (بدلاً من).`,examples:[{de:`Während des Unterrichts darf man nicht reden.`,ar:`أثناء الدرس ممنوع الكلام.`},{de:`Wegen des Wetters bleibe ich zu Hause.`,ar:`بسبب الطقس سأبقى في البيت.`},{de:`Trotz der Kälte gehen wir spazieren.`,ar:`رغم البرد نذهب للمشي.`},{de:`Statt eines Kaffees trinke ich Tee.`,ar:`بدلاً من القهوة أشرب الشاي.`}]},{title:`البديل في الحياة اليومية: von + Dativ`,contentAr:`في الكلام نقول غالباً **von** بدل Genitiv. في الكتابة الرسمية نستخدم Genitiv.`,examples:[{de:`Das ist das Auto von meinem Vater. (gesprochen)`,ar:`سيارة أبي.`},{de:`Das ist das Auto meines Vaters. (geschrieben)`,ar:`سيارة أبي (رسمي).`}]}]},{id:`imperativ`,titleAr:`صيغة الأمر – Imperativ`,titleDe:`Imperativ`,summaryAr:`تستخدم لإعطاء أوامر أو نصائح أو دعوات.`,rules:[{title:`الأشكال الثلاثة`,contentAr:`هناك ثلاثة أشكال للأمر بحسب من تخاطب: **du** (أنت)، **ihr** (أنتم)، **Sie** (حضرتك/حضرتكم).`,table:{headers:[`الفعل`,`du!`,`ihr!`,`Sie!`],rows:[[`gehen (يذهب)`,`Geh!`,`Geht!`,`Gehen Sie!`],[`kommen (يأتي)`,`Komm!`,`Kommt!`,`Kommen Sie!`],[`lesen (يقرأ)`,`Lies!`,`Lest!`,`Lesen Sie!`],[`nehmen (يأخذ)`,`Nimm!`,`Nehmt!`,`Nehmen Sie!`],[`fahren (يقود)`,`Fahr!`,`Fahrt!`,`Fahren Sie!`],[`sein (يكون)`,`Sei!`,`Seid!`,`Seien Sie!`],[`haben (يملك)`,`Hab!`,`Habt!`,`Haben Sie!`]]}},{title:`استخدامات`,contentAr:`مع **du** نستعمل جذع الفعل بدون نهاية. مع **ihr** نستعمل صيغة الفعل مثل المضارع. مع **Sie** نضع الفاعل بعد الفعل.`,examples:[{de:`Mach bitte die Tür zu!`,ar:`من فضلك أغلق الباب!`},{de:`Trinkt mehr Wasser!`,ar:`اشربوا المزيد من الماء!`},{de:`Sprechen Sie bitte langsamer!`,ar:`تكلم ببطء من فضلك!`},{de:`Sei vorsichtig!`,ar:`كن حذراً!`}]}]},{id:`reflexive`,titleAr:`الأفعال الانعكاسية – Reflexive Verben`,titleDe:`Reflexive Verben`,summaryAr:`أفعال يتعلق فعلها بالفاعل نفسه (يستحم، يلبس، يفرح…). تحتاج ضمير انعكاسي.`,rules:[{title:`الضمائر الانعكاسية`,contentAr:`مع Akkusativ:`,table:{headers:[`الضمير`,`Akkusativ`,`Dativ`],rows:[[`ich`,`mich`,`mir`],[`du`,`dich`,`dir`],[`er/sie/es`,`sich`,`sich`],[`wir`,`uns`,`uns`],[`ihr`,`euch`,`euch`],[`sie/Sie`,`sich`,`sich`]]}},{title:`أمثلة على الأفعال الشائعة`,contentAr:`**sich freuen** (يفرح)، **sich ärgern** (يغضب)، **sich entscheiden** (يقرر)، **sich anziehen** (يلبس)، **sich waschen** (يغتسل).`,examples:[{de:`Ich freue mich auf das Wochenende.`,ar:`أنا متحمس لعطلة الأسبوع.`},{de:`Wäschst du dich gerade?`,ar:`ه�� تغتسل الآن؟`},{de:`Wir treffen uns am Montag.`,ar:`سنلتقي يوم الإثنين.`},{de:`Setz dich bitte!`,ar:`اجلس من فضلك!`},{de:`Ich ziehe mir die Jacke an. (Dat.)`,ar:`ألبس المعطف.`}]}]},{id:`futur`,titleAr:`المستقبل – Futur I (werden + Infinitiv)`,titleDe:`Futur I`,summaryAr:`في الحياة اليومية يُعبَّر عن المستقبل غالباً بزمن المضارع + ظرف زمن. لكن في الوعود والتنبؤات نستعمل Futur I.`,rules:[{title:`البناء`,contentAr:`**werden** (تصريف بحسب الفاعل) + **مصدر الفعل في النهاية**.`,table:{headers:[`الفاعل`,`صيغة werden`],rows:[[`ich`,`werde`],[`du`,`wirst`],[`er/sie/es`,`wird`],[`wir`,`werden`],[`ihr`,`werdet`],[`sie/Sie`,`werden`]]}},{title:`متى نستخدمه`,contentAr:`**1. وعد:** Ich werde dich nicht vergessen.
**2. تنبؤ:** Es wird morgen regnen.
**3. قرار قوي:** Ich werde mehr Sport machen.
**4. توقع:** Sie wird wohl zu Hause sein.`,examples:[{de:`Ich werde dich nie vergessen.`,ar:`لن أنساك أبداً.`},{de:`Morgen wird es regnen.`,ar:`غداً ستمطر.`},{de:`Wir werden in fünf Jahren ein Haus kaufen.`,ar:`بعد خمس سنوات سنشتري بيتاً.`},{de:`Du wirst sehen, alles wird gut.`,ar:`سترى، كل شيء سيكون بخير.`}]}]},{id:`indirekte-rede`,titleAr:`الكلام غير المباشر – Indirekte Rede`,titleDe:`Indirekte Rede`,summaryAr:`كيف ننقل ما قاله شخص آخر. في B1 نستعمل صيغة المضارع البسيطة عادة. صيغة Konjunktiv I تظهر في الإعلام والصحف.`,rules:[{title:`في الحياة اليومية`,contentAr:`نستخدم **dass** في الجملة الجانبية:
**X sagt, dass …**`,examples:[{de:`Anna sagt, dass sie krank ist.`,ar:`تقول أنّا إنها مريضة.`},{de:`Mein Vater meint, dass das Essen lecker schmeckt.`,ar:`يقول أبي إن الأكل لذيذ.`},{de:`Die Lehrerin sagt, dass wir morgen einen Test haben.`,ar:`تقول المعلّمة إن لدينا اختباراً غداً.`}]},{title:`في الإعلام – Konjunktiv I`,contentAr:`يُستخدم في النشرات والصحف لنقل أقوال أشخاص بدون التزام الكاتب بصحتها. أهم الأشكال: **sei**، **habe**، **gehe**، **komme**.`,examples:[{de:`Der Politiker sagt, er sei unschuldig.`,ar:`يقول السياسي إنه بريء.`},{de:`Die Polizei meldet, sie habe den Täter gefunden.`,ar:`تعلن الشرطة أنها وجدت الجاني.`},{de:`Er sagte, er gehe morgen zur Arbeit.`,ar:`قال إنه سيذهب غداً إلى العمل.`}]}]},{id:`plural`,titleAr:`الجمع – Plural`,titleDe:`Pluralbildung`,summaryAr:`لا توجد قاعدة واحدة لتكوين الجمع. الأفضل أن تتعلّم الجمع مع كل اسم.`,rules:[{title:`النهايات الخمس الشائعة`,contentAr:`تستعمل واحدة من النهايات: **-e** ، **-er** (مع Umlaut)، **-(e)n** ، **-s** ، **بدون نهاية** (مع Umlaut أحياناً).`,table:{headers:[`النهاية`,`مثال`,`الجمع`],rows:[[`-e`,`der Tisch`,`die Tische`],[`-e + Umlaut`,`die Hand`,`die Hände`],[`-er + Umlaut`,`das Kind / das Buch`,`die Kinder / die Bücher`],[`-(e)n`,`die Frau / die Tasche`,`die Frauen / die Taschen`],[`-s (كلمات أجنبية)`,`das Auto / der Computer`,`die Autos / die Computer`],[`بدون نهاية`,`der Lehrer`,`die Lehrer`],[`بدون نهاية + Umlaut`,`der Bruder / die Mutter`,`die Brüder / die Mütter`]]}},{title:`قواعد عامة مفيدة`,contentAr:`الكلمات المنتهية بـ **-er, -el, -en** غالباً بلا تغيير. الكلمات الأنثوية المنتهية بـ **-e** تأخذ -n. الكلمات الأنثوية الكثيرة الأحرف تأخذ -en.`,examples:[{de:`der Computer → die Computer`,ar:`الكمبيوتر / الكمبيوترات`},{de:`die Lampe → die Lampen`,ar:`مصباح / مصابيح`},{de:`die Universität → die Universitäten`,ar:`جامعة / جامعات`},{de:`in Dativ Plural بنضيف -n: mit den Kindern`,ar:`مع الأطفال`}]}]},{id:`konnektoren`,titleAr:`روابط الجمل (Konnektoren)`,titleDe:`Konnektoren – Satzverbindungen`,summaryAr:`الكلمات التي تربط جملتين أو فكرتين معاً. مهمة جداً للكتابة وللمحادثة في B1.`,rules:[{title:`القسم الأول: روابط بدون تأثير على ترتيب الفعل`,contentAr:`**und (و) / aber (لكن) / oder (أو) / denn (لأن) / sondern (بل)** — هذه الروابط لا تؤثر على ترتيب الكلمات. الفعل يبقى في موقعه الثاني.`,examples:[{de:`Ich lerne Deutsch und mein Bruder lernt Englisch.`,ar:`أنا أتعلم الألمانية وأخي يتعلم الإنكليزية.`},{de:`Ich bin müde, aber ich gehe zur Arbeit.`,ar:`أنا متعب، لكن أذهب للعمل.`},{de:`Wir bleiben zu Hause, denn es regnet.`,ar:`نبقى في البيت، لأنها تمطر.`},{de:`Ich trinke keinen Kaffee, sondern Tee.`,ar:`لا أشرب قهوة، بل شاياً.`}]},{title:`القسم الثاني: روابط تنقل الفعل للنهاية (تابعة)`,contentAr:`**weil (لأن) / dass (أن) / wenn (إذا/متى) / obwohl (رغم أن) / damit (لكي) / bevor (قبل أن) / nachdem (بعد أن) / während (أثناء)** — هذه تنقل الفعل المصرّف إلى **نهاية** الجملة الجانبية.`,examples:[{de:`Ich bleibe zu Hause, weil ich krank bin.`,ar:`أبقى في البيت لأنني مريض.`},{de:`Ich denke, dass das Wetter schlecht wird.`,ar:`أعتقد أن الطقس سيسوء.`},{de:`Wenn ich Zeit habe, lese ich ein Buch.`,ar:`عندما يكون لدي وقت، أقرأ كتاباً.`},{de:`Obwohl es regnet, gehe ich joggen.`,ar:`رغم أنها تمطر، أذهب للجري.`},{de:`Ich lerne Deutsch, damit ich eine Arbeit finde.`,ar:`أتعلم الألمانية لكي أجد عملاً.`}]},{title:`القسم الثالث: روابط ترسل الفعل للموقع الأول (مع inversion)`,contentAr:`**deshalb / deswegen (لذلك) / trotzdem (مع ذلك) / dann (ثم) / danach (بعد ذلك) / außerdem (إضافة لذلك) / sonst (وإلا)** — بعد هذه الكلمات يأتي **الفعل أولاً ثم الفاعل**.`,examples:[{de:`Es regnet, deshalb bleibe ich zu Hause.`,ar:`إنها تمطر، لذلك أبقى في البيت.`},{de:`Ich war müde. Trotzdem habe ich gearbeitet.`,ar:`كنت متعباً، مع ذلك عملت.`},{de:`Ich frühstücke, dann gehe ich zur Arbeit.`,ar:`أتناول الفطور، ثم أذهب للعمل.`},{de:`Beeil dich, sonst kommen wir zu spät!`,ar:`أسرع، وإلا تأخّرنا!`}]},{title:`جدول الفروقات المهمّة`,contentAr:`هذه الكلمات تختلط على الكثيرين:`,table:{headers:[`الكلمة`,`المعنى`,`تأثيرها على ترتيب الفعل`,`مثال`],rows:[[`weil`,`لأن`,`الفعل في النهاية`,`Ich bleibe, weil ich krank bin.`],[`denn`,`لأن`,`لا يؤثر`,`Ich bleibe, denn ich bin krank.`],[`deshalb`,`لذلك`,`فعل ثم فاعل`,`Ich bin krank, deshalb bleibe ich.`],[`als`,`عندما (في الماضي مرة)`,`الفعل في النهاية`,`Als ich klein war, …`],[`wenn`,`عندما (متكرر/مستقبل)`,`الفعل في النهاية`,`Wenn ich Zeit habe, …`],[`ob`,`هل / إذا (سؤال)`,`الفعل في النهاية`,`Ich weiß nicht, ob er kommt.`],[`obwohl`,`رغم أن`,`الفعل في النهاية`,`Obwohl es regnet, gehe ich.`],[`trotzdem`,`مع ذلك`,`فعل ثم فاعل`,`Es regnet. Trotzdem gehe ich.`]]}}]},{id:`praepositionen-liste`,titleAr:`قائمة كاملة لحروف الجر (Akkusativ vs. Dativ)`,titleDe:`Präpositionen mit Akkusativ / Dativ`,summaryAr:`احفظ هذه القوائم! هي مفتاح اختيار الحالة الصحيحة (Akkusativ أو Dativ) في كل جملة.`,rules:[{title:`حروف الجر ��ع Akkusativ فقط`,contentAr:`احفظ بالعبارة الذهبية: **D – F – G – O – U** أو الجملة:
"durch, für, gegen, ohne, um".`,table:{headers:[`حرف الجر`,`المعنى`,`مثال`],rows:[[`durch`,`عبر / من خلال`,`Wir gehen durch den Park.`],[`für`,`من أجل / لـ`,`Das Geschenk ist für meinen Vater.`],[`gegen`,`ضد / حوالي (وقت)`,`Ich bin gegen die Idee. / gegen 8 Uhr`],[`ohne`,`بدون`,`Ich gehe ohne meinen Bruder.`],[`um`,`حول / في الساعة`,`Wir sitzen um den Tisch. / um 9 Uhr`],[`bis`,`حتى`,`bis nächsten Montag`],[`entlang`,`على طول`,`Wir gehen den Fluss entlang.`]]}},{title:`حروف الجر مع Dativ فقط`,contentAr:`العبارة الذهبية: **aus, bei, mit, nach, seit, von, zu, gegenüber** (أوصلها بأغنية!). كلها Dativ.`,table:{headers:[`حرف الجر`,`المعنى`,`مثال`],rows:[[`aus`,`من (أصل/داخل)`,`Ich komme aus Syrien. / aus dem Haus`],[`bei`,`عند`,`Ich wohne bei meiner Tante.`],[`mit`,`مع / بـ`,`Ich fahre mit dem Bus.`],[`nach`,`إلى (مدينة/بلد) / بعد`,`Ich fliege nach Berlin. / nach dem Essen`],[`seit`,`منذ`,`Ich lerne seit zwei Jahren Deutsch.`],[`von`,`من (شخص/مكان)`,`Das ist ein Brief von meiner Mutter.`],[`zu`,`إلى (شخص/مؤسسة)`,`Ich gehe zu meinem Arzt.`],[`gegenüber`,`مقابل`,`Die Bank ist dem Bahnhof gegenüber.`],[`außer`,`باستثناء`,`Außer mir kommen alle.`]]}},{title:`تنبيهات مهمّة (Daumenregel)`,contentAr:`**1. nach vs. zu:** nach مع أسماء المدن والبلدان (nach Berlin)، أما zu مع الأشخاص والمؤسسات (zu meinem Arzt).
**2. bei:** عند شخص أو في مكان عمل (bei IKEA arbeiten).
**3. seit + لحظة من الماضي:** seit gestern, seit drei Tagen.`,examples:[{de:`Ich fahre nach Hamburg.`,ar:`أسافر إلى هامبورغ.`},{de:`Ich gehe zu meinem Freund.`,ar:`أذهب إلى صديقي.`},{de:`Ich arbeite bei Lidl.`,ar:`أعمل في ليدل.`},{de:`Seit einem Jahr wohne ich hier.`,ar:`أسكن هنا منذ سنة.`}]}]},{id:`n-deklination`,titleAr:`الأسماء التي تأخذ -n في كل الحالات (N-Deklination)`,titleDe:`N-Deklination`,summaryAr:`مجموعة من الأسماء **المذكّرة فقط** تأخذ -n أو -en في كل الحالات ما عدا Nominativ المفرد. خطأ شائع جداً.`,rules:[{title:`القاعدة`,contentAr:`أسماء مذكرة تنتهي بـ **-e** أو تدلّ على شخص (مهنة/جنسية/حيوان). تأخذ **-n** في Akk./Dat./Gen.`,table:{headers:[`الاسم`,`Nominativ`,`Akkusativ / Dativ`,`مثال`],rows:[[`الجار`,`der Nachbar`,`den/dem Nachbarn`,`Ich frage den Nachbarn.`],[`الزبون`,`der Kunde`,`den/dem Kunden`,`Wir helfen dem Kunden.`],[`الطالب`,`der Student`,`den/dem Studenten`,`Ich kenne den Studenten.`],[`الفتى`,`der Junge`,`den/dem Jungen`,`Sieh den Jungen!`],[`السيد`,`der Herr`,`den/dem Herrn`,`Fragen Sie den Herrn.`],[`الإنسان`,`der Mensch`,`den/dem Menschen`,`Ich liebe den Menschen.`],[`الكلب`,`der Hund (لا!)`,`— (شاذ، عادي)`,`der Hund / den Hund`],[`التركي`,`der Türke`,`den/dem Türken`,`Ich spreche mit dem Türken.`]]}},{title:`كلمات مهمة من هذا النوع`,contentAr:`der Junge, der Kunde, der Kollege, der Türke, der Pole, der Russe, der Franzose, der Grieche, der Ungar, der Bulgare, der Däne, der Schwede, der Held (البطل), der Affe (القرد), der Bär (الدب), der Löwe (الأسد), der Hase (الأرنب), der Architekt, der Polizist, der Tourist, der Pianist, der Demokrat.`,examples:[{de:`Ich treffe meinen Kollegen.`,ar:`سألتقي بزميلي.`},{de:`Hilfst du dem Touristen?`,ar:`هل تساعد السائح؟`},{de:`Wir sehen den Affen im Zoo.`,ar:`نرى القرد في الحديقة.`},{de:`Sie spricht mit ihrem Nachbarn.`,ar:`هي تتحدث مع جارها.`}]}]},{id:`adverbien`,titleAr:`الظروف وترتيبها (TeKaMoLo)`,titleDe:`Adverbien & TeKaMoLo-Regel`,summaryAr:`إذا كان في الجملة عدة ظروف، يكون ترتيبها: **Te-Ka-Mo-Lo** = زمن - سبب - طريقة - مكان.`,rules:[{title:`القاعدة الذهبية: TeKaMoLo`,contentAr:`**Te** = Temporal (متى؟)
**Ka** = Kausal (لماذا؟)
**Mo** = Modal (كيف؟)
**Lo** = Lokal (أين/إلى أين؟)`,table:{headers:[`الظرف`,`يجيب على`,`أمثلة شائعة`],rows:[[`Temporal (Te)`,`wann? wie lange? wie oft?`,`heute, morgen, gestern, oft, nie, um 8 Uhr, jeden Tag`],[`Kausal (Ka)`,`warum?`,`wegen der Krankheit, deswegen, aus Versehen`],[`Modal (Mo)`,`wie?`,`gern, schnell, mit dem Bus, allein, vorsichtig`],[`Lokal (Lo)`,`wo? wohin? woher?`,`hier, dort, nach Hause, in die Schule`]]}},{title:`أمثلة على الترتيب`,contentAr:`لاحظ كيف يتغيّر ترتيب الظروف:`,examples:[{de:`Ich gehe morgen wegen meiner Mutter mit dem Bus zum Arzt.`,ar:`أذهب غداً (Te) بسبب أمي (Ka) بالباص (Mo) للطبيب (Lo).`},{de:`Wir fahren heute schnell nach Hause.`,ar:`نذهب اليوم (Te) بسرعة (Mo) للبيت (Lo).`},{de:`Sie lernt jeden Tag fleißig in der Bibliothek.`,ar:`تدرس كل يوم (Te) باجتهاد (Mo) في المكتبة (Lo).`}]},{title:`ظروف مفيدة جداً`,contentAr:`احفظ هذه الظروف:`,examples:[{de:`eigentlich (في الحقيقة)`,ar:`Eigentlich wollte ich heute kommen.`},{de:`unbedingt (بالتأكيد / لا بدّ)`,ar:`Du musst unbedingt das Schloss sehen!`},{de:`wahrscheinlich (على الأرجح)`,ar:`Er kommt wahrscheinlich später.`},{de:`vielleicht (ربما)`,ar:`Vielleicht regnet es morgen.`},{de:`leider (للأسف)`,ar:`Leider habe ich keine Zeit.`},{de:`natürlich (بالطبع)`,ar:`Natürlich helfe ich dir!`},{de:`plötzlich (فجأة)`,ar:`Plötzlich klingelte das Telefon.`}]}]},{id:`da-wo-komposita`,titleAr:`مركّبات Da- و Wo- (damit, worauf...)`,titleDe:`Da- und Wo-Komposita`,summaryAr:`بدلاً من تكرار الاسم نستعمل da+حرف الجر، وللسؤال wo+حرف الجر. مع حروف العلة نضيف -r-.`,rules:[{title:`مركّبات Da- (للإشارة لشيء سبق ذكره)`,contentAr:`**da + حرف الجر** = "بهذا/معه/له/منه...". مع حروف العلّة (a/e/i/o/u): **dar + حرف الجر**.`,table:{headers:[`حرف الجر`,`مع da-`,`مثال`],rows:[[`mit`,`damit`,`Ich fahre mit dem Bus. → Damit fahre ich.`],[`von`,`davon`,`Ich erzähle davon.`],[`für`,`dafür`,`Ich bin dafür.`],[`gegen`,`dagegen`,`Ich bin dagegen.`],[`über`,`darüber`,`Wir sprechen darüber.`],[`auf`,`darauf`,`Ich freue mich darauf.`],[`an`,`daran`,`Ich denke daran.`],[`in`,`darin`,`Es ist nichts darin.`],[`aus`,`daraus`,`Was machst du daraus?`]]}},{title:`مركّبات Wo- (للأسئلة)`,contentAr:`**wo + حرف الجر** = "بماذا / مع ماذا...". تستخدم للأشياء فقط، أما الأشخاص فتسأل بـ "Mit wem?".`,table:{headers:[`الحرف`,`الكلمة`,`مثال`],rows:[[`mit`,`womit?`,`Womit fährst du? — Mit dem Bus.`],[`über`,`worüber?`,`Worüber sprecht ihr?`],[`von`,`wovon?`,`Wovon träumst du?`],[`für`,`wofür?`,`Wofür ist das Geld?`],[`auf`,`worauf?`,`Worauf wartest du?`],[`an`,`woran?`,`Woran denkst du?`],[`in`,`worin?`,`Worin liegt das Problem?`]]}},{title:`متى نستخدم؟`,contentAr:`**للأشياء/الأفكار** نستخدم Da-/Wo-Komposita.
**للأشخاص** نستخدم حرف الجر + ضمير عادي:`,examples:[{de:`Ich denke an mein Auto. → Ich denke daran.`,ar:`لشيء → daran`},{de:`Ich denke an meinen Vater. → Ich denke an ihn.`,ar:`لشخص → an ihn`},{de:`Worauf wartest du? — Auf den Bus.`,ar:`لشيء → worauf`},{de:`Auf wen wartest du? — Auf meinen Bruder.`,ar:`لشخص → auf wen`}]}]},{id:`verben-praepositionen`,titleAr:`الأفعال مع حروف جر ثابتة (Verben mit festen Präpositionen)`,titleDe:`Verben mit festen Präpositionen`,summaryAr:`بعض الأفعال الألمانية تأتي دائماً مع حرف جر معيّن وحالة معيّنة (Akkusativ أو Dativ). يجب حفظها كوحدة واحدة لأنّ ترجمتها العربية لا تساعد دائماً.`,arabicContrast:`في العربية: "أفكر **بـ** أمي" (حرف جر ثابت). في الألمانية أيضاً: "Ich denke **an** meine Mutter" — لكنّ الحرف الألماني (an) لا يطابق العربي دائماً. مثلاً "أعتمد على" → بالألمانية sich verlassen **auf**.`,whenToUseAr:`عند تعلّم فعل جديد، تعلّم معه دائماً حرف الجر والحالة. هذه الأفعال تكثُر في امتحانات Telc B1 و DTZ — خاصّة في Sprachbausteine.`,rules:[{title:`أفعال شائعة + حرف جر + Akkusativ`,contentAr:`هذه الأفعال تأخذ Akkusativ بعد حرف الجر:`,table:{headers:[`الفعل + الحرف`,`الترجمة`,`مثال`],rows:[[`warten auf (+Akk)`,`ينتظر`,`Ich warte auf den Bus.`],[`sich freuen auf (+Akk)`,`يفرح بشيء قادم`,`Ich freue mich auf den Urlaub.`],[`sich freuen über (+Akk)`,`يفرح بشيء حصل`,`Ich freue mich über das Geschenk.`],[`denken an (+Akk)`,`يفكر في`,`Ich denke an dich.`],[`sich erinnern an (+Akk)`,`يتذكر`,`Erinnerst du dich an mich?`],[`sich interessieren für (+Akk)`,`يهتم بـ`,`Ich interessiere mich für Musik.`],[`bitten um (+Akk)`,`يطلب من`,`Ich bitte um Hilfe.`],[`danken für (+Akk)`,`يشكر على`,`Danke für deine Hilfe!`],[`sich kümmern um (+Akk)`,`يعتني بـ`,`Sie kümmert sich um die Kinder.`],[`sich verlieben in (+Akk)`,`يقع في حب`,`Ich habe mich in sie verliebt.`],[`sprechen über (+Akk)`,`يتحدّث عن`,`Wir sprechen über die Politik.`],[`sich beschweren über (+Akk)`,`يشتكي من`,`Er beschwert sich über das Wetter.`],[`nachdenken über (+Akk)`,`يتأمل في`,`Ich denke über mein Leben nach.`],[`glauben an (+Akk)`,`يؤمن بـ`,`Ich glaube an Gott.`],[`ankommen auf (+Akk) — es kommt darauf an`,`يعتمد على`,`Es kommt auf dich an.`]]}},{title:`أفعال شائعة + حرف جر + Dativ`,contentAr:`هذه الأفعال تأخذ Dativ بعد حرف الجر:`,table:{headers:[`الفعل + الحرف`,`الترجمة`,`مثال`],rows:[[`arbeiten bei (+Dat)`,`يعمل لدى`,`Ich arbeite bei BMW.`],[`anfangen mit (+Dat)`,`يبدأ بـ`,`Ich fange mit dem Deutschkurs an.`],[`aufhören mit (+Dat)`,`يتوقف عن`,`Hör auf mit dem Lärm!`],[`sich beschäftigen mit (+Dat)`,`ينشغل بـ`,`Sie beschäftigt sich mit Kunst.`],[`sich treffen mit (+Dat)`,`يلتقي بـ`,`Ich treffe mich mit Maria.`],[`sich verabreden mit (+Dat)`,`يحدّد موعداً مع`,`Ich verabrede mich mit ihm.`],[`sich erkundigen nach (+Dat)`,`يستفسر عن`,`Ich erkundige mich nach dem Termin.`],[`fragen nach (+Dat)`,`يسأل عن`,`Er fragt nach dem Weg.`],[`suchen nach (+Dat)`,`يبحث عن`,`Sie sucht nach einer Wohnung.`],[`Angst haben vor (+Dat)`,`يخاف من`,`Ich habe Angst vor Hunden.`],[`sich fürchten vor (+Dat)`,`يخاف من`,`Er fürchtet sich vor Spinnen.`],[`gehören zu (+Dat)`,`ينتمي إلى`,`Das gehört zu meinen Hobbys.`],[`einladen zu (+Dat)`,`يدعو إلى`,`Ich lade euch zur Party ein.`],[`gratulieren zu (+Dat)`,`يهنّئ بـ`,`Ich gratuliere dir zum Geburtstag!`],[`rechnen mit (+Dat)`,`يتوقع`,`Damit habe ich nicht gerechnet.`]]}}],commonMistakes:[{wrong:`Ich warte für den Bus.`,right:`Ich warte auf den Bus.`,explanationAr:`warten يأخذ حرف auf (وليس für كما في الإنجليزية).`},{wrong:`Ich denke an meiner Mutter.`,right:`Ich denke an meine Mutter.`,explanationAr:`denken an + Akkusativ (وليس Dativ).`},{wrong:`Ich freue mich für den Urlaub.`,right:`Ich freue mich auf den Urlaub.`,explanationAr:`freuen auf لشيء قادم في المستقبل / freuen über لشيء حصل بالماضي. لا تستخدم für هنا.`}],tipsAr:[`احفظ الفعل دائماً مع حرف الجر والحالة (Akkusativ/Dativ).`,`auf و an و über مع المستقبل/الذكريات/المواضيع غالباً مع Akkusativ.`,`mit و bei و nach و von و zu دائماً مع Dativ.`]},{id:`partizip-als-adjektiv`,titleAr:`Partizip I و Partizip II كصفات`,titleDe:`Partizip I und II als Adjektive`,summaryAr:`يمكن تحويل الأفعال إلى صفات باستخدام Partizip I (للفعل النشط الذي يحدث الآن) أو Partizip II (للفعل المكتمل أو المبني للمجهول).`,arabicContrast:`العربية: "الطفل الباكي" (اسم فاعل من بكى) و"الكتاب المقروء" (اسم مفعول من قرأ). الألمانية: "das weinende Kind" (Partizip I) و"das gelesene Buch" (Partizip II).`,rules:[{title:`تكوين Partizip I`,contentAr:`**Partizip I** = جذر الفعل + **end** + نهاية الصفة (-er/-e/-es). يدل على فعل **نشط ومستمر** الآن.`,examples:[{de:`das **schlafende** Baby`,ar:`الطفل النائم (وهو ينام الآن)`},{de:`die **lachenden** Kinder`,ar:`الأطفال الضاحكون`},{de:`der **fahrende** Zug`,ar:`القطار الماشي`},{de:`spielende Hunde`,ar:`كلاب تلعب`}]},{title:`تكوين Partizip II كصفة`,contentAr:`**Partizip II** = نفس صيغة Perfekt (gemacht, gelesen, gegangen). يدل إمّا على شيء **مكتمل** أو **مبني للمجهول**.`,examples:[{de:`das **gekochte** Essen`,ar:`الطعام المطبوخ (تم طبخه)`},{de:`der **geöffnete** Brief`,ar:`الرسالة المفتوحة`},{de:`die **gewaschenen** Hände`,ar:`الأيدي المغسولة`},{de:`eine **gut bezahlte** Stelle`,ar:`وظيفة جيدة الأجر`}]},{title:`الفرق بين Partizip I و II`,contentAr:`Partizip I = نشط (الفاعل يفعل): "der lesende Mann" (الرجل القارئ).
Partizip II = منفعل أو مكتمل: "das gelesene Buch" (الكتاب المقروء).`,table:{headers:[`Partizip I`,`Partizip II`],rows:[[`die schreibende Frau (المرأة الكاتبة)`,`der geschriebene Brief (الرسالة المكتوبة)`],[`ein laufender Hund (كلب يجري)`,`das gelaufene Rennen (السباق المنتهي)`],[`die kochende Mutter (الأم الطابخة)`,`das gekochte Essen (الطعام المطبوخ)`]]}}],commonMistakes:[{wrong:`das schlafendes Kind`,right:`das schlafende Kind`,explanationAr:`لا تنسَ تصريف الصفة حسب الجنس والحالة (das + ende = das schlafende).`}],tipsAr:[`Partizip I = حدث **يجري** الآن (مثل "صفة من الفعل المضارع").`,`Partizip II = حدث **انتهى** أو شيء **مفعول به** (passive).`,`تتصرّف هذه الصيغ كصفات عاديّة (تأخذ نهايات حسب الجنس/الحالة).`]},{id:`modalpartikeln`,titleAr:`كلمات النبرة (Modalpartikeln) — doch, mal, eben, halt, ja`,titleDe:`Modalpartikeln`,summaryAr:`كلمات صغيرة تستخدم في المحادثة اليومية لإضافة نكهة أو لون عاطفي للجملة. لا يمكن ترجمتها حرفياً، لكنّها مهمّة جداً للنطق الطبيعي.`,arabicContrast:`العربية تستخدم كلمات مشابهة مثل "يَلَا، هلَّا، ها، طبعاً، لا تشيل هَمّ، أكيد". مثال: "يلَا تعال!" = "Komm doch!". الألمانية تركّب هذه النكهة بكلمة قصيرة في وسط الجملة.`,whenToUseAr:`استخدمها فقط في الكلام اليومي والرسائل غير الرسمية. لا تستخدمها في الكتابة الرسمية. تأتي عادة بعد الفعل المصرّف.`,rules:[{title:`doch — للتأكيد أو الردّ على نفي`,contentAr:`تستخدم لـ: (1) تأكيد طلب أو دعوة. (2) الردّ على سؤال منفي. (3) تذكير بشيء يعرفه السامع.`,examples:[{de:`Komm **doch** mit!`,ar:`تعال معنا! (دعوة لطيفة)`},{de:`— Hast du keine Zeit? — **Doch**, ich habe Zeit.`,ar:`— أليس عندك وقت؟ — بل عندي وقت!`},{de:`Du weißt **doch**, dass ich krank bin.`,ar:`أنت تعرف أنّي مريض! (تذكير)`}]},{title:`mal — للتلطيف`,contentAr:`تخفّف من قوة الأمر أو الطلب وتجعله ودوداً. مثل "شوية" أو "للحظة" بالعربية.`,examples:[{de:`Komm **mal** her!`,ar:`تعال للحظة!`},{de:`Schau **mal**!`,ar:`انظر لشوية!`},{de:`Hör **mal** zu!`,ar:`اسمع شوية!`}]},{title:`eben / halt — للقبول والاستسلام`,contentAr:`تستخدم عند قبول واقع لا يمكن تغييره. "eben" أكثر شمالية، "halt" أكثر جنوبية. تترجم تقريباً بـ "هيك هي" أو "ما باليد حيلة".`,examples:[{de:`Das ist **eben** so.`,ar:`هكذا هي الأمور.`},{de:`Dann musst du **halt** warten.`,ar:`إذاً يجب أن تنتظر، ما في حلّ.`}]},{title:`ja — للإشارة لشيء معروف`,contentAr:`تستخدم للإشارة إلى أنّ المعلومة معروفة للجميع أو واضحة. مثل "كما تعلم" أو "طبعاً".`,examples:[{de:`Du bist **ja** schon da!`,ar:`أنت موجود فعلاً! (دهشة لطيفة)`},{de:`Das ist **ja** klar.`,ar:`هذا واضح طبعاً.`}]},{title:`denn — في الأسئلة لإضافة لطف`,contentAr:`تستخدم في الأسئلة فقط لجعلها أكثر ودوداً وأقلّ مباشرة.`,examples:[{de:`Was machst du **denn** hier?`,ar:`ماذا تفعل هنا (يا ترى)؟`},{de:`Wie heißt du **denn**?`,ar:`ما اسمك (لو سمحت)؟`}]}],tipsAr:[`لا تترجم Modalpartikel حرفياً — تعلّم متى ��ستخدمها بالشعور.`,`تأتي دائماً بعد الفعل المصرّف وقبل المفعول به.`,`الإكثار منها قد يبدو مزعجاً — اكتفِ بواحدة أو اثنتين في الجملة.`]},{id:`temporalsaetze`,titleAr:`الجمل الزمنية (während, bevor, nachdem, sobald, solange, seit)`,titleDe:`Temporalsätze`,summaryAr:`جمل ثانوية تربط حدثين زمنياً (قبل/بعد/أثناء/منذ/بمجرد). كلّ حرف يحدّد علاقة زمنية مختلفة ويتطلّب أحياناً زمناً معيّناً للفعل.`,rules:[{title:`wenn / als — متى يُستخدم أيّ منهما؟`,contentAr:`**als** = حدث ماضٍ مرّة واحدة. **wenn** = حدث متكرّر في الماضي أو حاضر/مستقبل.`,examples:[{de:`**Als** ich klein war, lebte ich in Damaskus.`,ar:`حين كنت صغيراً، عشت في دمشق. (مرّة واحدة)`},{de:`**Wenn** ich Zeit habe, lese ich.`,ar:`حين يكون عندي وقت، أقرأ. (متكرّر)`},{de:`Immer **wenn** es regnete, blieb ich zu Hause.`,ar:`كلّما كان يمطر بالماضي، بقيت في البيت.`}]},{title:`während — أثناء`,contentAr:`**während** = "في نفس الوقت الذي". يستخدم زمن مماثل في الجملتين.`,examples:[{de:`**Während** ich koche, hört er Musik.`,ar:`بينما أطبخ، هو يستمع للموسيقى.`},{de:`**Während** sie lernte, schlief er.`,ar:`بينما كانت تدرس، كان نائماً.`}]},{title:`bevor — قبل أن`,contentAr:`**bevor** = الحدث في الجملة الفرعية يأتي **بعد** الحدث في الجملة الأساسية.`,examples:[{de:`Ich putze die Zähne, **bevor** ich schlafe.`,ar:`أنظف أسناني قبل أن أنام.`},{de:`**Bevor** du gehst, schließ bitte das Fenster.`,ar:`قبل أن تذهب، أغلق النافذة من فضلك.`}]},{title:`nachdem — بعدما (مع Plusquamperfekt)`,contentAr:`**nachdem** يحتاج زمنين مختلفين: الجملة الفرعية في زمن **سابق** (Plusquamperfekt مع Präteritum، أو Perfekt مع Präsens).`,examples:[{de:`**Nachdem** ich gefrühstückt **hatte**, ging ich zur Arbeit.`,ar:`بعدما تناولت الفطور، ذهبت إلى العمل.`},{de:`**Nachdem** ich gegessen **habe**, gehe ich spazieren.`,ar:`بعدما آكل، أذهب أتمشى.`}]},{title:`sobald — بمجرد أن`,contentAr:`**sobald** = "حالما / بمجرّد أن". الحدث الثاني يحدث **مباشرة** بعد الأوّل.`,examples:[{de:`**Sobald** ich nach Hause komme, rufe ich dich an.`,ar:`بمجرّد أن أصل إلى البيت، سأتصل بك.`},{de:`Sag mir Bescheid, **sobald** du fertig bist.`,ar:`أخبرني حالما تنتهي.`}]},{title:`solange — طالما / ما دام`,contentAr:`**solange** = طالما هذا الشرط مستمر.`,examples:[{de:`**Solange** ich Geld habe, helfe ich dir.`,ar:`طالما عندي مال، سأساعدك.`},{de:`Du darfst hier wohnen, **solange** du willst.`,ar:`يحقّ لك السكن هنا ما دمت تريد.`}]},{title:`seit / seitdem — منذ`,contentAr:`**seit + Dativ** (حرف جر) أو **seitdem** (رابط جملة). تشير إلى نقطة بداية في الماضي مستمرة حتى الآن. تستخدم Präsens أو Perfekt.`,examples:[{de:`Ich lerne Deutsch, **seit** ich in Deutschland bin.`,ar:`أتعلم الألمانية منذ أن أتيت إلى ألمانيا.`},{de:`**Seitdem** ich studiere, habe ich keine Zeit.`,ar:`منذ أن بدأت الدراسة، ليس عندي وقت.`}]}],commonMistakes:[{wrong:`Wenn ich klein war, lebte ich in Damaskus.`,right:`Als ich klein war, lebte ich in Damaskus.`,explanationAr:`حدث ماضٍ مرّة واحدة → als (وليس wenn).`},{wrong:`Nachdem ich frühstücke, gehe ich zur Arbeit.`,right:`Nachdem ich gefrühstückt habe, gehe ich zur Arbeit.`,explanationAr:`nachdem يحتاج Perfekt (أو Plusquamperfekt) في الجملة الفرعية.`}]},{id:`kausalsaetze`,titleAr:`الجمل السببية (weil, da, denn, deshalb, deswegen)`,titleDe:`Kausalsätze`,summaryAr:`كلّها تعني "لأنّ / لذلك" لكن تختلف في تركيب الجملة. weil/da = جملة فرعية (الفعل في النهاية). denn = رابط جمل (الفعل في الموضع 2). deshalb/deswegen = ظرف (الفعل في الموضع 2 لكن الترتيب مقلوب).`,rules:[{title:`weil — السبب الأكثر شيوعاً`,contentAr:`**weil** = "لأنّ". جملة فرعية → الفعل في النهاية. تستخدم في 90% من المحادثات.`,examples:[{de:`Ich bleibe zu Hause, **weil** ich krank **bin**.`,ar:`أبقى في البيت لأنّي مريض.`},{de:`Sie lernt Deutsch, **weil** sie hier arbeiten **möchte**.`,ar:`تتعلم الألمانية لأنّها تريد العمل هنا.`}]},{title:`da — مثل weil لكن أرسم`,contentAr:`**da** = "بما أنّ". مثل weil لكن أكثر رسميّة وتأتي عادة في **بداية** الجملة.`,examples:[{de:`**Da** es regnet, bleibe ich zu Hause.`,ar:`بما أنّها تمطر، أبقى في البيت.`},{de:`**Da** ich keine Zeit habe, kann ich nicht kommen.`,ar:`بما أنّ ليس عندي وقت، لا أستطيع الحضور.`}]},{title:`denn — رابط بدون تغيير ترتيب`,contentAr:`**denn** = "لأنّ". ليست جملة فرعية! تربط جملتين رئيسيتين والفعل في الموضع 2 (لا يتغيّر الترتيب).`,examples:[{de:`Ich bleibe zu Hause, **denn** ich **bin** krank.`,ar:`أبقى في البيت، فأنا مريض.`},{de:`Er kommt nicht, **denn** er **hat** keine Zeit.`,ar:`لن يأتي، إذ ليس عنده وقت.`}]},{title:`deshalb / deswegen / darum / daher — لذلك`,contentAr:`هذه ظروف (Adverbien) تأتي في **بداية** الجملة الثانية. الفعل يأتي مباشرة بعدها (Position 2).`,examples:[{de:`Ich bin krank. **Deshalb** **bleibe** ich zu Hause.`,ar:`أنا مريض. لذلك أبقى في البيت.`},{de:`Es regnet. **Deswegen** **nehme** ich den Schirm.`,ar:`إنّها تمطر. لذلك آخذ المظلّة.`}]},{title:`مقارنة شاملة`,contentAr:`انتبه لمكان الفعل في كلّ صيغة:`,table:{headers:[`الكلمة`,`النوع`,`مكان الفعل`],rows:[[`weil / da`,`Subjunktion`,`في **النهاية** (Nebensatz)`],[`denn`,`Konjunktion`,`في **الموضع 2** (Hauptsatz)`],[`deshalb / deswegen / darum / daher`,`Adverb`,`في **الموضع 2** بعد الظرف`]]}}],commonMistakes:[{wrong:`Ich bleibe zu Hause, weil ich bin krank.`,right:`Ich bleibe zu Hause, weil ich krank bin.`,explanationAr:`بعد weil → الفعل في النهاية (Nebensatz).`},{wrong:`Es regnet, deshalb ich bleibe zu Hause.`,right:`Es regnet, deshalb bleibe ich zu Hause.`,explanationAr:`بعد deshalb → الفعل في الموضع 2 (قبل الفاعل).`}]},{id:`finalsaetze`,titleAr:`الجمل الغائية (damit / um ... zu) — لكي / من أجل`,titleDe:`Finalsätze (damit / um zu)`,summaryAr:`تستخدم للتعبير عن **الهدف** أو **الغاية**. القاعدة الذهبية: إذا كان الفاعل واحداً في الجملتين → استخدم **um ... zu**. إذا كان الفاعل مختلفاً → استخدم **damit**.`,arabicContrast:`العربية: "أدرس **لكي** أنجح" / "أعطيك المال **لكي** تشتري الكتاب". الألمانية تميّز بين الحالتين.`,rules:[{title:`um ... zu (نفس الفاعل)`,contentAr:`الفاعل في الجملتين **نفسه**. الفعل في النهاية بصيغة المصدر مع zu.`,examples:[{de:`Ich lerne, **um** die Prüfung **zu** **bestehen**.`,ar:`أدرس لكي أنجح في الامتحان. (نفس الفاعل)`},{de:`Sie geht zur Bank, **um** Geld **abzuheben**.`,ar:`تذهب إلى البنك لتسحب نقوداً.`},{de:`Wir essen Obst, **um** gesund **zu** **bleiben**.`,ar:`نأكل الفواكه لكي نبقى أصحّاء.`}]},{title:`damit (فاعل مختلف)`,contentAr:`الفاعل في الجملتين **مختلف**. الفعل في النهاية بصيغة عاديّة (مصرّف).`,examples:[{de:`Ich gebe dir Geld, **damit** du das Buch **kaufst**.`,ar:`أعطيك مالاً لكي تشتري الكتاب. (فاعلان)`},{de:`Die Mutter kocht, **damit** die Kinder essen **können**.`,ar:`الأم تطبخ لكي يأكل الأولاد.`},{de:`Ich helfe dir, **damit** du schneller **fertig** **bist**.`,ar:`أساعدك لكي تنتهي أسرع.`}]},{title:`متى لا أستطيع استخدام um ... zu؟`,contentAr:`حتّى لو كان الفاعل واحداً، إذا كان الفعل **modal** (können, müssen...) لا تستخدم um zu — استخدم damit.`,examples:[{de:`✗ Ich gehe, um schlafen zu können.`,ar:`(غير سليم نحوياً)`},{de:`✓ Ich gehe, **damit** ich schlafen **kann**.`,ar:`أذهب لأستطيع النوم.`}]}],commonMistakes:[{wrong:`Ich gebe dir Geld, um du das Buch kaufst.`,right:`Ich gebe dir Geld, damit du das Buch kaufst.`,explanationAr:`فاعلان مختلفان (Ich vs du) → damit وليس um zu.`},{wrong:`Ich lerne, damit ich die Prüfung bestehe.`,right:`Ich lerne, um die Prüfung zu bestehen.`,explanationAr:`صحيح أيضاً! لكن مع نفس الفاعل، um zu أفضل وأبلغ.`}],tipsAr:[`سؤال سحري: هل الفاعل **نفسه**؟ نعم → um zu. لا → damit.`,`um zu يحتاج zu قبل الفعل في النهاية (kommen → zu kommen).`,`مع أفعال قابلة للفصل: um einzukaufen (zu يدخل بين البادئة والجذر).`]},{id:`konzessivsaetze`,titleAr:`الجمل التنازلية (obwohl, trotzdem, trotz, dennoch)`,titleDe:`Konzessivsätze`,summaryAr:`تستخدم للتعبير عن **تناقض غير متوقّع** بين شيئين (مع أنّ X، إلّا أنّ Y).`,rules:[{title:`obwohl — مع أنّ (جملة فرعية)`,contentAr:`**obwohl** = "مع أنّ / رغم أنّ". جملة فرعية → الفعل في النهاية.`,examples:[{de:`Ich gehe spazieren, **obwohl** es **regnet**.`,ar:`أتمشّى رغم أنّها تمطر.`},{de:`**Obwohl** ich krank bin, gehe ich zur Arbeit.`,ar:`رغم أنّي مريض، أذهب إلى العمل.`}]},{title:`trotzdem — رغم ذلك (ظرف)`,contentAr:`**trotzdem** = "رغم ذلك / مع ذلك". ظرف يأتي في **الموضع 1** أو 3 من الجملة الرئيسية.`,examples:[{de:`Es regnet. **Trotzdem** **gehe** ich spazieren.`,ar:`إنّها تمطر. رغم ذلك أتمشّى.`},{de:`Ich bin krank. Ich **gehe trotzdem** zur Arbeit.`,ar:`أنا مريض. أذهب رغم ذلك إلى العمل.`}]},{title:`trotz — رغم (حرف جر + Genitiv)`,contentAr:`**trotz + Genitiv** (أو Dativ في الكلام اليومي). يأتي قبل اسم.`,examples:[{de:`**Trotz des Regens** gehe ich spazieren.`,ar:`رغم المطر أتمشّى.`},{de:`**Trotz seiner Krankheit** arbeitet er.`,ar:`رغم مرضه يعمل.`}]},{title:`dennoch / jedoch — لكن (رسمي)`,contentAr:`مرادفات لـ trotzdem لكن أكثر رسميّة. تستخدم في الكتابة.`,examples:[{de:`Es ist schwer. **Dennoch** **versuche** ich es.`,ar:`إنّه صعب. ومع ذلك أحاول.`},{de:`Er ist klug, **jedoch** sehr schüchtern.`,ar:`هو ذكي، لكنّه خجول جداً.`}]}],commonMistakes:[{wrong:`Obwohl es regnet, trotzdem gehe ich spazieren.`,right:`Obwohl es regnet, gehe ich spazieren. ✓ (أو) Es regnet. Trotzdem gehe ich spazieren. ✓`,explanationAr:`لا تجمع obwohl + trotzdem في نفس الجملة — استخدم واحدة فقط.`},{wrong:`Trotzdem es regnet, gehe ich spazieren.`,right:`Obwohl es regnet, gehe ich spazieren.`,explanationAr:`trotzdem ظرف، لا يبدأ به جملة فرعية. استخدم obwohl.`}]},{id:`nicht-vs-kein`,titleAr:`النفي (nicht vs kein) — متى نستخدم كلّ منهما؟`,titleDe:`Verneinung: nicht oder kein?`,summaryAr:`القاعدة الذهبيّة: **kein** ينفي الأسماء **النكرة** والأسماء **بلا أداة** (المفرد النكرة + الجمع بلا أداة + غير المعدود). **nicht** ينفي كلّ شيء آخر (الأفعال، الصفات، الأسماء المعرّفة، الظروف).`,arabicContrast:`العربية تستخدم "لا/ما/ليس" بشكل عام. الألمانية تفرّق بين nicht (لا/ليس) وkein (لا يوجد، ليس عندي... قبل اسم نكرة).`,rules:[{title:`kein — قبل اسم نكرة`,contentAr:`يستخدم **kein** قبل: (1) اسم مع ein/eine. (2) اسم جمع بلا أداة. (3) اسم غير معدود بلا أداة. يصرّف مثل ein.`,examples:[{de:`Ich habe **kein** Auto.`,ar:`ليس عندي سيّارة. (نكرة)`},{de:`Ich habe **keine** Zeit.`,ar:`ليس عندي وقت. (غير معدود)`},{de:`Ich kenne **keine** Deutschen.`,ar:`لا أعرف ألماناً. (جمع بلا أداة)`},{de:`Es gibt **keinen** Zucker.`,ar:`لا يوجد سكّر.`}]},{title:`nicht — لكلّ شيء آخر`,contentAr:`استخدم **nicht** عندما تنفي: (1) فعلاً. (2) صفةً. (3) ظرفاً. (4) اسماً معرّفاً (بـ der/die/das/mein...).`,examples:[{de:`Ich gehe **nicht**.`,ar:`لا أذهب. (نفي فعل)`},{de:`Das ist **nicht** schön.`,ar:`هذا ليس جميلاً. (نفي صفة)`},{de:`Er kommt **nicht** heute.`,ar:`لن يأتي اليوم. (نفي ظرف)`},{de:`Ich kenne **das Buch nicht**.`,ar:`لا أعرف الكتاب. (نفي اسم معرّف)`}]},{title:`موقع nicht في الجملة`,contentAr:`القواعد الأساسيّة: (1) قبل الكلمة المنفيّة مباشرة لو نفيت كلمة معيّنة. (2) في النهاية لو نفيت الجملة كاملة. (3) قبل Partizip II / المصدر / الصفة الخبرية.`,examples:[{de:`Ich rauche **nicht**.`,ar:`لا أدخّن. (نفي شامل)`},{de:`Ich habe **nicht** geraucht.`,ar:`لم أدخّن. (قبل Partizip II)`},{de:`Ich gehe **nicht** mit dir.`,ar:`لا أذهب معك. (قبل المنفي)`}]}],commonMistakes:[{wrong:`Ich habe nicht Auto.`,right:`Ich habe kein Auto.`,explanationAr:`Auto نكرة (بلا أداة) → kein (وليس nicht).`},{wrong:`Ich kenne kein das Buch.`,right:`Ich kenne das Buch nicht.`,explanationAr:`das Buch معرّف → nicht (وليس kein).`}]},{id:`plusquamperfekt`,titleAr:`الماضي البعيد (Plusquamperfekt)`,titleDe:`Plusquamperfekt`,summaryAr:`زمن "ماضي الماضي" — يستخدم لوصف حدث وقع **قبل** حدث ماضٍ آخر. يتكوّن من **hatte/war + Partizip II**.`,arabicContrast:`العربية: "كنتُ قد أكلتُ" (ماضي الماضي). الألمانية: "Ich hatte gegessen". يستخدم خاصّة مع nachdem.`,whenToUseAr:`استخدمه: (1) مع nachdem (إجباري). (2) لتوضيح أنّ شيئاً حصل قبل شيء آخر في الماضي. (3) في القصص والروايات.`,rules:[{title:`تكوين Plusquamperfekt`,contentAr:`**hatte** أو **war** (في Präteritum) + Partizip II في النهاية. اختيار haben/sein بنفس قواعد Perfekt.`,examples:[{de:`Ich **hatte** schon **gegessen**.`,ar:`كنت قد أكلت.`},{de:`Sie **war** nach Berlin **gefahren**.`,ar:`كانت قد سافرت إلى برلين.`},{de:`Wir **hatten** den Film schon **gesehen**.`,ar:`كنّا قد شاهدنا الفيلم.`}]},{title:`مع nachdem — الاستعمال الكلاسيكي`,contentAr:`الجملة الفرعية مع nachdem في **Plusquamperfekt**، الجملة الرئيسية في **Präteritum**.`,examples:[{de:`**Nachdem** ich **gefrühstückt hatte**, **ging** ich zur Arbeit.`,ar:`بعدما تناولت الفطور، ذهبت للعمل.`},{de:`**Nachdem** er **gekommen war**, **begann** das Treffen.`,ar:`بعدما وصل، بدأ الاجتماع.`}]},{title:`تصريف hatte / war`,contentAr:`تصريف الفعل المساعد في Präteritum:`,table:{headers:[`الضمير`,`haben`,`sein`],rows:[[`ich`,`hatte`,`war`],[`du`,`hattest`,`warst`],[`er/sie/es`,`hatte`,`war`],[`wir`,`hatten`,`waren`],[`ihr`,`hattet`,`wart`],[`sie/Sie`,`hatten`,`waren`]]}}],commonMistakes:[{wrong:`Nachdem ich gefrühstückt habe, ging ich zur Arbeit.`,right:`Nachdem ich gefrühstückt hatte, ging ich zur Arbeit.`,explanationAr:`مع nachdem والجملة الرئيسية في Präteritum، يجب استخدام Plusquamperfekt (hatte/war).`}]},{id:`zahlen-uhrzeit`,titleAr:`الأرقام والوقت والتاريخ`,titleDe:`Zahlen, Uhrzeit und Datum`,summaryAr:`الأرقام في الألمانية لها قواعد خاصّة: تُقرأ من اليمين أبتداء من 21، الوقت له صيغ رسميّة وكلاميّة، والتاريخ يُكتب بترتيب يوم/شهر/سنة.`,rules:[{title:`الأرقام من 21 إلى 99 — تُقرأ من اليمين!`,contentAr:`الترتيب: **آحاد + und + عشرات**. هذا عكس الإنجليزية (twenty-one) ومثل بعض اللهجات العربية ("إحدى وعشرون").`,examples:[{de:`**einundzwanzig** = 21`,ar:`واحد وعشرون`},{de:`**dreiundvierzig** = 43`,ar:`ثلاثة وأربعون`},{de:`**siebenundachtzig** = 87`,ar:`سبعة وثمانون`},{de:`**neunundneunzig** = 99`,ar:`تسعة وتسعون`}]},{title:`الأرقام الكبيرة`,contentAr:`مئة = **hundert** / ألف = **tausend** / مليون = **eine Million**. الترتيب: **مئة + آحاد + und + عشرات**.`,examples:[{de:`**hundertdreiundfünfzig** = 153`,ar:`مئة وثلاثة وخمسون`},{de:`**zweitausendvierundzwanzig** = 2024`,ar:`ألفان وأربعة وعشرون`},{de:`**eine Million** = 1.000.000`,ar:`مليون (لاحظ: ألمانياً النقطة فاصلة آلاف!)`}]},{title:`الوقت الرسمي (24 ساعة)`,contentAr:`يستخدم في القطارات والمواعيد الرسميّة. الصيغة: **رقم الساعة + Uhr + الدقائق**.`,examples:[{de:`**14:30** = vierzehn Uhr dreißig`,ar:`2:30 ظهراً`},{de:`**09:15** = neun Uhr fünfzehn`,ar:`9:15 صباحاً`},{de:`**00:00** = null Uhr / Mitternacht`,ar:`منتصف الليل`}]},{title:`الوقت الكلامي (12 ساعة)`,contentAr:`يستخدم في المحادثة. فيه قواعد خاصّة لـربع/نصف/ثلاثة أرباع.`,table:{headers:[`الوقت`,`الكلامي`,`المعنى`],rows:[[`7:00`,`sieben Uhr`,`الساعة سبعة`],[`7:15`,`Viertel nach sieben`,`سبعة وربع`],[`7:30`,`halb acht`,`سبعة ونصف (انتبه: نصف الثامنة!)`],[`7:45`,`Viertel vor acht / Dreiviertel acht`,`ثمانية إلّا ربع`],[`7:05`,`fünf nach sieben`,`سبعة وخمسة`],[`7:55`,`fünf vor acht`,`ثمانية إلّا خمسة`]]}},{title:`التاريخ`,contentAr:`الصيغة: **am + رقم الترتيب + الشهر**. الأشهر مذكّرة (der Januar, der Februar...). تستخدم Akkusativ مع am.`,examples:[{de:`Heute ist der **15. Mai**.`,ar:`اليوم هو 15 أيار.`},{de:`Mein Geburtstag ist **am 3. Juli**.`,ar:`عيد ميلادي في 3 تموز.`},{de:`Ich komme **am 1. September**.`,ar:`سأصل في 1 أيلول.`},{de:`**1.5.2025** = der erste Mai zweitausendfünfundzwanzig`,ar:`1 أيار 2025`}]},{title:`الأرقام الترتيبيّة`,contentAr:`الترتيبي = الرقم + **te** (لـ 1-19) أو + **ste** (لـ 20+). ich bin der **erste** (الأوّل).`,examples:[{de:`der **erste** (1.) — der **zweite** (2.) — der **dritte** (3.)`,ar:`الأوّل، الثاني، الثالث`},{de:`der **siebte** (7.) — der **achte** (8.)`,ar:`السابع، الثامن`},{de:`der **zwanzigste** (20.) — der **einundzwanzigste** (21.)`,ar:`العشرون، الحادي والعشرون`},{de:`der **hundertste** (100.)`,ar:`المئة`}]}],tipsAr:[`انتبه: halb acht = 7:30 (وليس 8:30) — "نصف الثامنة" تعني نصف الطريق إلى الثامنة!`,`في الكتابة: 1.234,56 (نقطة آلاف، فاصلة عشرية) — عكس الإنجليزية والعربية.`,`أيام الأسبوع كلّها مذكّرة: der Montag, der Dienstag... → am Montag.`]}],t={perfekt:{arabPitfalls:[`الخلط بين haben وsein: نقول "Ich bin gefahren" (لأنّ fahren حركة)، وليس "habe gefahren".`,`نسيان وضع Partizip II في آخر الجملة. "Ich habe gestern Pizza gegessen" — gegessen في الآخر دائماً.`,`إضافة ge- إلى الأفعال المنتهية بـ -ieren مثل studieren → خطأ: gestudiert / صح: studiert.`,`كتابة Partizip II بصورة منتظمة لفعل غير منتظم: gegessen ≠ gegessst / gegesst.`],examTip:`في Sprechen Teil 1 (Erfahrung berichten) استخدم Perfekt دائماً: "Ich habe in Syrien Deutsch gelernt." — أكثر طبيعيّة من Präteritum.`},praeteritum:{arabPitfalls:[`استخدام Präteritum في المحادثة العاديّة بدل Perfekt — يبدو الكلام كقصّة كتاب.`,`الخلط بين war (sein) وhatte (haben) في الماضي.`,`استعمال Präteritum للأفعال العاديّة في الكلام الشفهي بدل ما هو طبيعي مثل haben/sein/Modalverben فقط.`],examTip:`في الكتابة (Schreiben) للسيرة الذاتية أو التقارير: استخدم Präteritum (war, hatte, ging, machte). في الكلام: التزم بـ Perfekt.`},"akk-dat":{arabPitfalls:[`نسيان أن der → den في Akkusativ. "Ich sehe der Mann" خطأ، الصحّ "den Mann".`,`الخلط بين mit + Dativ (mit dem Bus) وohne + Akkusativ (ohne den Bus).`,`النسيان أنّ Personalpronomen يتغيّر: ich → mich (Akk) / mir (Dat). "Er hilft ich" خطأ، الصحّ "Er hilft mir".`,`حرف الجرّ in: مع حركة (Akk) "in die Schule"، مع مكان ثابت (Dat) "in der Schule".`],examTip:`في Schreiben (رسالة شكوى/طلب) استعمل tan-Konstruktionen مع Dativ: "Mit Ihrem Mitarbeiter habe ich gesprochen." — تبدو رسميّة.`},nebensatz:{arabPitfalls:[`وضع الفعل في موقعه العادي بعد weil/dass/obwohl. خطأ: "weil ich bin müde" — الصحّ "weil ich müde bin" (الفعل بآخر الجملة).`,`نسيان الفاصلة قبل أداة الربط (weil, dass, obwohl, wenn).`,`الخلط بين wenn وals: wenn للحالات المتكرّرة/المستقبل، als مرّة واحدة في الماضي.`,`الخلط بين dass (أنّ — حرف ربط) وdas (الذي — ضمير).`],examTip:`في Sprechen Teil 2 (Diskussion) استخدم weil + obwohl لإعطاء سبب وضدّه: "Ich finde das gut, weil … Aber andererseits, obwohl … bin ich nicht ganz sicher."`},"konjunktiv-2":{arabPitfalls:[`استخدام würde مع الأفعال الناقصة وhaben/sein: خطأ "ich würde haben" / صحّ "ich hätte".`,`النسيان أنّ würde + Infinitiv هو الشكل الشائع للأفعال العاديّة في الكلام.`,`الخلط بين Konjunktiv II للحاضر/المستقبل (hätte, würde) والماضي (hätte gemacht, wäre gegangen).`],examTip:`في Sprechen Teil 3 (التخطيط مع الشريك) استخدم Konjunktiv II ليبدو طلبك أدباً: "Könntest du …? Wäre es möglich, dass …?"`},passiv:{arabPitfalls:[`نسيان werden + Partizip II — "Das Auto ist gewaschen" (Zustandspassiv) ≠ "Das Auto wird gewaschen" (المبني للمجهول الفعلي).`,`استخدام sein بدل werden في صياغة المبني للمجهول.`,`الخلط بين Aktiv وPassiv في الجمل الطويلة مع Modalverb: "Das muss gemacht werden" — werden في النهاية.`],examTip:`في Schreiben (تعليمات/قواعد) استعمل Passiv: "Hier wird nicht geraucht. Die Tür wird abgeschlossen." — أسلوب رسمي ألماني.`},adjektive:{arabPitfalls:[`حفظ نهايات الصفات صعب جداً للعرب. تذكّر: لمّا تكون der/die/das/die قبل الصفة → نهاية ضعيفة (-e أو -en). لو كانت ein/eine → نهاية قويّة.`,`نسيان اختلاف Genitiv: "des großen Mannes" مع s إضافيّة على Mannes.`,`مع الصفات بدون أداة (Wein, Bier) النهايات تتبع der/die/das (kalter Wein, kaltes Bier).`],examTip:`في الكتابة لا تخف من تقليل صفات. صفة واحدة صحيحة أفضل من ثلاث صفات فيها أخطاء. ركّز على der/die/das + -e للأسهل.`},trennbare:{arabPitfalls:[`نسيان فصل البادئة في الزمن المضارع: "Ich rufe dich morgen an" — an في النهاية (لا "anrufe dich").`,`في Perfekt: ge- يدخل بين البادئة والفعل: aufstehen → aufgestanden (لا aufstanden).`,`في Nebensatz: الفعل يبقى متّصلاً: "weil ich dich morgen anrufe" — anrufe كاملاً في النهاية.`],examTip:`احفظ ٢٠ فعلاً منفصلاً شائعاً في B1 (anrufen, aufstehen, einkaufen, abholen, mitkommen…) — ستحتاجها في كل جزء من الامتحان.`},relativsatz:{arabPitfalls:[`الخلط بين der/die/das/den/dem/dessen — يطابق الكلمة المرجعيّة (Genus) وموقع الفعل (Kasus) داخل الجملة.`,`نسيان أنّ Relativsatz هو Nebensatz → الفعل لآخر الجملة الفرعيّة دائماً.`,`استخدام wer/was بدل der/die/das لأشياء محدّدة. wer/was تستخدم لأشياء عامّة (alles, was…).`],examTip:`في Sprechen استخدم Relativsätze لتعريف نفسك بدقّة: "Ich bin jemand, der gerne reist und neue Sprachen lernt." — يُظهر مستوى B1 بسرعة.`},modalverben:{arabPitfalls:[`الخلط بين müssen (لا بدّ من) وsollen (يجب — توصية): "Ich muss arbeiten" (إجبار) ≠ "Du sollst nicht lügen" (نصيحة/أمر).`,`الخلط بين dürfen (مسموح) وkönnen (قادر): "Darf ich rauchen?" (هل مسموح) ≠ "Kann ich rauchen?" (هل قادر).`,`وضع المصدر في غير آخر الجملة: خطأ "Ich kann sprechen Deutsch" / صحّ "Ich kann Deutsch sprechen".`],examTip:`في Sprechen Teil 3 (التفاوض) استخدم Modalverben مهذّبة: "Wir könnten… Wir sollten… Möchtest du…?" — تجعل الكلام أنعم.`},wechselpraepositionen:{arabPitfalls:[`الخلط بين wo? (ثابت — Dativ) وwohin? (حركة — Akkusativ): "Ich bin in der Schule" ≠ "Ich gehe in die Schule".`,`نسيان أنّ هناك ٩ حروف: an, auf, in, hinter, vor, neben, zwischen, über, unter — كلها تأخذ Akk أو Dat.`,`استعمال an مع المدن خطأ: نقول in Berlin، nach Berlin (وجهة) — ليس an Berlin.`],examTip:`تذكّر القاعدة الذهبيّة: لو سأل المعلّم "wohin?" استخدم Akk. لو سأل "wo?" استخدم Dat. تدرّب على الفرق فقط هذا.`},konnektoren:{arabPitfalls:[`الخلط بين aber (لكن — يربط جملتين كاملتين) وsondern (بل — يربط بعد نفي): "Nicht heute, sondern morgen" ≠ "Nicht heute, aber morgen".`,`denn (لأنّ — Hauptsatz) ≠ weil (لأنّ — Nebensatz): denn لا يغيّر ترتيب الفعل، weil يضع الفعل بآخر الجملة.`,`الخلط بين wenn (إذا/متى) وals (لمّا — مرّة واحدة في الماضي).`],examTip:`احفظ ٤ روابط للسبب والنتيجة: weil, deshalb, denn, deswegen. استعملهم في كل Schreiben — يرفع نقاطك في "Kohärenz" بسرعة.`},reflexive:{arabPitfalls:[`نسيان الضمير العائد: خطأ "Ich freue auf das Wochenende" / صحّ "Ich freue mich auf …".`,`الخلط بين Akkusativ وDativ في reflexives: "Ich wasche mich" (Akk) vs "Ich wasche mir die Hände" (Dat).`,`بعض الأفعال reflexive في الألمانية وليست في العربية: sich erinnern, sich beschweren, sich freuen — احفظها كوحدة كاملة.`],examTip:`احفظ ١٠ أفعال reflexive شائعة في B1 (sich freuen auf, sich interessieren für, sich beschäftigen mit, sich beschweren über…) — ستحتاجها في Sprechen Teil 2 لإبداء الرأي.`},imperativ:{arabPitfalls:[`الخلط بين du-Form (geh!) وSie-Form (Gehen Sie!) — du بدون -st، Sie بصيغة كاملة + Sie بعدها.`,`نسيان أنّ ihr-Form = نفس Präsens (geht!).`,`استخدام صيغة الأمر مع غير المخاطب — في الألمانية الأمر للمخاطب فقط.`],examTip:`في Schreiben (تعليمات لطلب) استخدم Sie-Form دائماً: "Bitte teilen Sie mir mit… Senden Sie mir bitte…" — يبدو رسمياً ومهذّباً.`}};function n(e){return t[e]}var r=[{topicId:`perfekt`,greeting:`Hallo, willkommen zur Stunde!`,storyAr:`تخيّل الـPerfekt مثل **تلفزيون قديم**: لا يعمل بزرّ واحد، يحتاج زرّين — زرّ "haben أو sein" قرب القابس، وزرّ "Partizip II" في النهاية. كلاهما لازمان حتّى تعمل الجملة. لو نسيت أحدهما، الجملة "تنطفئ".`,mnemonicAr:`**"الحركة تأخذ sein، وكلّ ما عداها haben."** خمس أفعال شاذّة لازم تحفظها بالـsein: sein, bleiben, werden, passieren, geschehen.`,mnemonicDe:`Bewegung nimmt SEIN, der Rest nimmt HABEN.`,steps:[{titleAr:`1️⃣ اختر الفعل المساعد`,de:`haben? oder sein?`,ar:`إذا حركة من مكان إلى مكان (gehen, fahren, fliegen, laufen) → sein. إذا تحوّل أو تغيير حالة (werden, einschlafen, aufwachen) → sein. غير ذلك → haben.`},{titleAr:`2️⃣ صرّف الفعل المساعد`,de:`ich habe / du hast / er hat ...   ich bin / du bist / er ist ...`,ar:`الفعل المساعد يأخذ مكان الفعل العاديّ في الموقع الثاني من الجملة.`},{titleAr:`3️⃣ ضع Partizip II في النهاية`,de:`... in den Park gegangen.`,ar:`القاعدة الذهبيّة: الفعل المساعد رقم 2، والـPartizip II في النهاية. هذا يُسمّى "Satzklammer" — قوس الجملة.`},{titleAr:`4️⃣ تشكيل Partizip II`,de:`machen → ge-mach-t   ·   gehen → ge-gang-en   ·   studieren → studiert`,ar:`الفعل الضعيف: ge + جذر + t. الفعل القوي: ge + جذر متغيّر + en. الأفعال على -ieren لا تأخذ ge-. الأفعال غير القابلة للفصل (be-, ent-, er-, ge-, ver-, zer-) لا تأخذ ge-.`}],advancedPatterns:[{title:`Doppel-Perfekt (نادر لكن مهمّ)`,de:`Ich habe das schon gemacht gehabt.`,ar:`الـDoppel-Perfekt يُستخدم في اللهجات الجنوبيّة بدل Plusquamperfekt — دلالة على الإكمال قبل لحظة ماضية.`},{title:`الأفعال الشكليّة (Modalverben) في الـPerfekt`,de:`Ich habe arbeiten müssen. (NICHT: gemusst)`,ar:`إذا جاء الفعل الشكلي مع فعل آخر، يُستعمل Infinitiv للفعلين معاً (Ersatzinfinitiv). أمّا لو وحده: "Ich habe das gemusst."`},{title:`فرق دقيق بين stehen/liegen/sitzen في Perfekt`,de:`Ich habe gestanden. (وقفت)   ·   Ich bin gestanden. (في الجنوب)`,ar:`في ألمانيا الشماليّة haben، في ألمانيا الجنوبيّة والنمسا sein. القاعدة الرسميّة الـDuden: haben.`},{title:`أفعال haben وsein في الـPerfekt نفسها`,de:`Ich habe Glück gehabt. · Ich bin müde gewesen.`,ar:`لاحظ: gehabt مع haben (أنا أملك → ملكت)، gewesen مع sein (أنا كائن → كنت).`}],examWisdom:`في امتحان telc/Goethe B1، 30% من أخطاء الـSchreiben بسبب اختيار خاطئ بين haben/sein. قاعدة طوارئ: لو نسيت، اسأل نفسك "هل تحرّك من مكان إلى مكان؟". لو نعم → sein.`,advancedExercises:[{id:`t-pf-1`,promptDe:`Gestern ____ ich um 7 Uhr aufgewacht.`,options:[{id:`a`,de:`habe`},{id:`b`,de:`bin`},{id:`c`,de:`war`}],correct:`b`,explanationAr:`aufwachen تغيّر حالة (نوم → استيقاظ) → sein.`},{id:`t-pf-2`,promptDe:`Er ____ sein Auto in die Garage ____.`,options:[{id:`a`,de:`hat / gefahren`},{id:`b`,de:`ist / gefahren`},{id:`c`,de:`hat / gefahrt`}],correct:`a`,explanationAr:`fahren هنا transitiv (له مفعول مباشر "Auto") → haben. لو "Er ist nach Berlin gefahren" → sein بلا مفعول.`},{id:`t-pf-3`,promptDe:`Sie ____ den ganzen Tag ____.`,options:[{id:`a`,de:`hat / studiert`},{id:`b`,de:`ist / gestudiert`},{id:`c`,de:`hat / gestudiert`}],correct:`a`,explanationAr:`الأفعال على -ieren لا تأخذ ge- → studiert فقط.`},{id:`t-pf-4`,promptDe:`Wir ____ schon ____ ____.`,options:[{id:`a`,de:`haben / essen / müssen`},{id:`b`,de:`haben / gegessen / gemusst`},{id:`c`,de:`haben / essen / gemusst`}],correct:`a`,explanationAr:`Modalverben مع فعل ثاني تستعمل Ersatzinfinitiv (Infinitiv بدلاً من Partizip): haben + Vollverb + Modalverb.`}]},{topicId:`akk-dat`,greeting:`Heute zwei wichtige Fälle: Akkusativ und Dativ!`,storyAr:`تخيّل الجملة كلعبة رمي كرة. **الفاعل** يرمي الكرة. **Akkusativ** هو الكرة نفسها (الذي يُفعَل به الفعل مباشرة). **Dativ** هو الشخص الذي تُرمى إليه الكرة (المستلِم). مثال: "Ich gebe **dem Kind** (Dat) **den Ball** (Akk)." → أرمي الكرة (Akk) إلى الطفل (Dat).`,mnemonicAr:`**Akkusativ يجيب: من / ماذا (Wen / Was؟)** · **Dativ يجيب: لمن (Wem؟).**`,mnemonicDe:`Akk = Wen/Was?  ·  Dativ = Wem?`,steps:[{titleAr:`1️⃣ تعرّف على الأدوات في كلّ حالة`,de:`Akk: den / die / das / die  ·  Dat: dem / der / dem / den (+n على الجمع)`,ar:`فقط أداة المذكّر der تتغيّر إلى den في Akkusativ. die/das لا تتغيّران في Akk. أمّا في Dativ، كلّها تتغيّر: der→dem, die→der, das→dem, die(pl)→den.`},{titleAr:`2️⃣ احفظ أفعال الـDativ القاتلة`,de:`helfen, danken, gehören, gefallen, antworten, glauben, schmecken, gratulieren, folgen, passen`,ar:`10 أفعال "خبيثة" لا تأخذ Akk بل Dativ. مثال خادع: "أنا أساعدك" ليست "Ich helfe dich" بل "Ich helfe **dir**."`},{titleAr:`3️⃣ احفظ حروف الجرّ الثابتة`,de:`Akk: durch, für, gegen, ohne, um  (DOGFU)  ·  Dat: aus, bei, mit, nach, seit, von, zu  (ABMNSVZ)`,ar:`حروف ABMNSVZ دائماً Dativ. حروف DOGFU دائماً Akkusativ. الـ"Wechselpräpositionen" (an, auf, in, ...) تأخذ Akk للحركة وDat للموقع — درس منفصل.`},{titleAr:`4️⃣ لمّا يجتمع Akk + Dat في جملة واحدة`,de:`Ich gebe dem Mann (Dat) das Buch (Akk).`,ar:`القاعدة الذهبيّة: Dativ قبل Akkusativ — إلّا إذا كان Akkusativ ضميراً�� يأتي أوّلاً: "Ich gebe es dem Mann."`}],advancedPatterns:[{title:`Personalpronomen في الحالتين`,de:`Akk: mich, dich, ihn, sie, es, uns, euch, sie/Sie  ·  Dat: mir, dir, ihm, ihr, ihm, uns, euch, ihnen/Ihnen`,ar:`احفظ هذا الجدول كرقم هاتف — تكراره يوميّاً ضروري.`},{title:`الأفعال "المخادعة" التي تشبه أفعال Akk لكنّها Dativ`,de:`antworten + Dativ (NICHT: jemanden antworten) → "Ich antworte dir."`,ar:`الترجمة العربيّة "أجيبك" توحي Akk، لكنّ الألمانيّة تستخدم Dativ.`},{title:`أفعال تأخذ مفعولين في حالتين مختلفتين`,de:`Ich beschuldige ihn (Akk) eines Verbrechens (Gen).`,ar:`أفعال نادرة تستخدم Akk + Genitiv: anklagen, beschuldigen, bezichtigen, würdigen.`}],examWisdom:`في امتحان Schreiben، 60% من الأخطاء النحويّة سببها خلط Akk/Dat. خدعة الامتحان: قبل أيّ اسم، اسأل: "Wem أم Wen؟" واكتب الـCase فوقها بقلم رصاص في المسوّدة قبل النسخ.`,advancedExercises:[{id:`t-ad-1`,promptDe:`Kannst du ____ mit ____ helfen?`,options:[{id:`a`,de:`mich / die Aufgabe`},{id:`b`,de:`mir / der Aufgabe`},{id:`c`,de:`mich / der Aufgabe`}],correct:`b`,explanationAr:`helfen يأخذ Dativ (mir)، وmit يأخذ Dativ (der Aufgabe).`},{id:`t-ad-2`,promptDe:`Das Auto gehört ____ Bruder.`,options:[{id:`a`,de:`meinen`},{id:`b`,de:`meinem`},{id:`c`,de:`mein`}],correct:`b`,explanationAr:`gehören = Dativ → meinem (مذكّر Dat).`},{id:`t-ad-3`,promptDe:`Ich gebe ____ ____.`,options:[{id:`a`,de:`dir es`},{id:`b`,de:`es dir`},{id:`c`,de:`dich es`}],correct:`b`,explanationAr:`لمّا الـAkkusativ ضمير (es)، يأتي قبل الـDativ: es dir.`},{id:`t-ad-4`,promptDe:`Ich gehe durch ____ Park.`,options:[{id:`a`,de:`dem`},{id:`b`,de:`den`},{id:`c`,de:`der`}],correct:`b`,explanationAr:`durch دائماً Akkusativ → den.`}]},{topicId:`modalverben`,greeting:`Modalverben — die kleinen Helfer der Sprache!`,storyAr:`الأفعال الشكليّة (können, müssen, dürfen, sollen, wollen, mögen) مثل **مفاتيح الإيموجي** على لوحة المفاتيح: لا تكتب جملة كاملة بمفردها، لكنّها تغيّر معنى أيّ جملة. اعتبرها "ألوان" تضعها على الفعل الأساسيّ.`,mnemonicAr:`القاعدة الذهبيّة: **الفعل الشكلي مُصرَّف في الموقع 2، والفعل الأصلي في النهاية بصيغة Infinitiv.** "Ich **kann** sehr gut Deutsch **sprechen**."`,mnemonicDe:`Modalverb auf Position 2 — Hauptverb am Ende im Infinitiv.`,steps:[{titleAr:`1️⃣ معاني الأفعال الستّة`,de:`können (يستطيع) · müssen (يجب) · dürfen (مسموح) · sollen (يُفترض/يُقال) · wollen (يريد بقوّة) · mögen (يحبّ)`,ar:`لكلّ فعل شكلي معنيان: معنى الإمكانيّة + معنى التخمين (Vermutung). مثال: "Er **kann** krank sein" قد تعني "هو قادر على المرض" أو "ربّما هو مريض".`},{titleAr:`2️⃣ التصريف غير المنتظم`,de:`ich kann/muss/darf/will/soll/mag — er kann/muss/darf/will/soll/mag (نفس صيغة ich!)`,ar:`الأفعال الشكليّة لا تأخذ -t في er/sie/es. وحدها تنفذ من القاعدة. + تغيّر حرف العلّة في المفرد (a→a/u، ö→ö، …).`},{titleAr:`3️⃣ Negation: nicht أم kein؟`,de:`Ich darf hier nicht parken. (لا يُسمح)  ·  Ich muss nicht arbeiten. (غير مُلزَم)`,ar:`انتبه! "muss nicht" لا تعني "ممنوع"، تعني "غير ملزَم". لتقول "ممنوع" استخدم "darf nicht".`},{titleAr:`4️⃣ في الـPerfekt: Ersatzinfinitiv`,de:`Ich habe arbeiten müssen.  (NICHT: gemusst)`,ar:`بدلاً من Partizip II، نستعمل Infinitiv ثانياً (هذا "البديل"). إذا كان الفعل الشكلي وحده: gemusst, gedurft, gekonnt, gewollt, gesollt, gemocht.`}],advancedPatterns:[{title:`Subjektive Bedeutung — معنى التخمين`,de:`Er muss krank sein. (= مؤكّد أنه مريض)  ·  Er kann krank sein. (= ربّما)  ·  Er soll reich sein. (= يُقال إنّه)`,ar:`هذا فرق دقيق امتحاني — كلّ فعل شكلي له درجة احتمال. müssen = مؤكّد، dürfen (Konj II) = مُحتمَل، mögen (Konj II) = ممكن، können = ممكن، sollen = إشاعة، wollen = ادّعاء.`},{title:`Brauchen + zu (بديل غير رسمي لـmüssen nicht)`,de:`Du brauchst nicht zu kommen. = Du musst nicht kommen.`,ar:`في الكلام اليومي، "brauchen + zu + Infinitiv" يستبدل "müssen nicht". لكنّه يُستعمل فقط في النفي والاستفهام.`},{title:`lassen — الفعل الشكلي السابع غير الرسميّ`,de:`Ich lasse mein Auto reparieren. (= أُصلِّحه عند ميكانيكي)`,ar:`lassen يُصرَّف مثل modalverb (Infinitiv في النهاية). معنيان: "يدع/يترك" أو "يُكلّف بفعل شيء".`}],examWisdom:`في الـSprechen B1، الممتحنون يحبّون رؤية تنوّع: ليس فقط "ich kann"، بل أيضاً "ich möchte"، "man könnte"، "es wäre schön, wenn …". استخدم Konjunktiv II من الأفعال الشكليّة (könnte, müsste, sollte) لزيادة درجة في "Wortschatz".`,advancedExercises:[{id:`t-mv-1`,promptDe:`Du ____ jetzt schlafen — es ist schon spät.`,options:[{id:`a`,de:`sollst`},{id:`b`,de:`darfst`},{id:`c`,de:`magst`}],correct:`a`,explanationAr:`sollst = "يُفترض بك / يُنصح" — مناسب للنصيحة.`},{id:`t-mv-2`,promptDe:`Ich ____ leider gestern nicht ____.`,options:[{id:`a`,de:`habe / kommen können`},{id:`b`,de:`habe / gekonnt kommen`},{id:`c`,de:`bin / kommen können`}],correct:`a`,explanationAr:`Ersatzinfinitiv: haben + Infinitiv + Modalverb (Infinitiv).`},{id:`t-mv-3`,promptDe:`Hier ____ man nicht rauchen — es ist verboten.`,options:[{id:`a`,de:`muss`},{id:`b`,de:`darf`},{id:`c`,de:`kann`}],correct:`b`,explanationAr:`"darf nicht" = ممنوع. "muss nicht" = غير مُلزَم (لكنّه مسموح).`}]},{topicId:`konjunktiv-2`,greeting:`Konjunktiv II — die Sprache der Träume und Wünsche!`,storyAr:`Konjunktiv II هو "صيغة الأحلام والأمنيات". تُستخدم لمّا تتكلّم عن شيء **غير حقيقي** — أمنية، فرضيّة، نصيحة مؤدّبة. مثل العربيّة "لو كنتُ غنيّاً لاشتريتُ بيتاً" — بالألمانيّة: "Wenn ich reich wäre, würde ich ein Haus kaufen."`,mnemonicAr:`**القاعدة العمليّة: würde + Infinitiv لمعظم الأفعال.** الاستثناءات الستّة المهمّة (لا تأخذ würde): hätte, wäre, würde نفسه، könnte, müsste, sollte، wüsste.`,mnemonicDe:`würde + Infinitiv  →  außer:  hätte, wäre, könnte, müsste, sollte, wüsste`,steps:[{titleAr:`1️⃣ Konjunktiv II للحاضر`,de:`Wenn ich Zeit hätte, würde ich dich besuchen.`,ar:`الجزء الأوّل (wenn-Satz) يحوي صيغة Konjunktiv II. الجزء الثاني (Hauptsatz) يحوي würde + Infinitiv (أو Konjunktiv II مباشرة لو من الستّة).`},{titleAr:`2️⃣ Konjunktiv II للماضي`,de:`Wenn ich Zeit gehabt hätte, hätte ich dich besucht.`,ar:`صيغة الماضي: hätte/wäre + Partizip II. تستخدم للنّدم على الماضي ("لو كنتُ فعلت كذا، لكان كذا").`},{titleAr:`3️⃣ الطلبات المؤدّبة (مهارة بليغة في الامتحان)`,de:`Könnten Sie mir bitte helfen? · Ich hätte gerne einen Kaffee. · Wäre es möglich, …?`,ar:`في المطعم، البنك، المحلّ — استخدم دائماً Konjunktiv II. هذا فرق "Tourist" و"شخص يعيش هنا".`},{titleAr:`4️⃣ الندم على الماضي (Schreiben/Sprechen B2)`,de:`Ich hätte besser lernen sollen. · An deiner Stelle hätte ich das nicht gemacht.`,ar:`الجمل التي تحوي "hätte/wäre + Partizip II + Modalverb" تُظهر مستوى لغوي عالٍ. احفظ 5 جمل جاهزة من هذا النوع.`}],advancedPatterns:[{title:`Konjunktiv II بدون wenn`,de:`Hätte ich Zeit, würde ich dich besuchen. (= Wenn ich Zeit hätte, …)`,ar:`بقلب الفعل إلى الموقع الأوّل، تستغني عن wenn. هذا يجعل الجملة تبدو "أدبيّة" أكثر.`},{title:`als ob / als wenn (كأنّ)`,de:`Er tut, als ob er nichts wüsste. = Er tut, als wüsste er nichts.`,ar:`بعد "als ob" نستخدم Konjunktiv II. حذف "ob" يعني انقلاب الفعل إلى الموقع 2 من الجملة الفرعيّة.`},{title:`beinahe / fast hätte (كاد أن)`,de:`Beinahe wäre ich gefallen. (كدتُ أقع.)`,ar:`تركيب نموذجي للسرد عن لحظات حرجة في الماضي. مفيد جدّاً في Sprechen.`},{title:`sollten بمعنى "في حال" (نادر لكن مهمّ)`,de:`Sollten Sie Fragen haben, rufen Sie mich an.`,ar:`بدل "Wenn Sie Fragen haben sollten" — Inversion + sollten = صيغة شرطيّة رسميّة.`}],examWisdom:`الجملة "Wenn ich an deiner Stelle wäre, würde ich …" هي السلاح السرّي في Sprechen Teil 3. تُظهر تعاطفاً + قواعد متقدّمة. احفظها واستعملها في كلّ "تخطيط مشترك".`,advancedExercises:[{id:`t-k2-1`,promptDe:`Wenn ich gewusst ____, ____ ich dich angerufen.`,options:[{id:`a`,de:`hätte / hätte`},{id:`b`,de:`würde / hätte`},{id:`c`,de:`hätte / wäre`}],correct:`a`,explanationAr:`Konj II ماضي = hätte + Partizip II مرّتين.`},{id:`t-k2-2`,promptDe:`____ Sie mir bitte den Weg zeigen?`,options:[{id:`a`,de:`Können`},{id:`b`,de:`Könnten`},{id:`c`,de:`Kannst`}],correct:`b`,explanationAr:`Könnten = Konjunktiv II مؤدّب — أرقى من Können في الطلبات.`},{id:`t-k2-3`,promptDe:`Er tut so, ____ er ein Experte ____.`,options:[{id:`a`,de:`als ob / wäre`},{id:`b`,de:`als / ist`},{id:`c`,de:`wenn / wäre`}],correct:`a`,explanationAr:`als ob + Konjunktiv II — قاعدة "كأنّ".`}]},{topicId:`passiv`,greeting:`Passiv — wenn die Handlung wichtiger ist als der Täter!`,storyAr:`Passiv (المبني للمجهول) مثل **خبر تلفزيوني** بدون تركيز على الشخص الفاعل: "Das Haus wurde gebaut" (تمّ بناء البيت) — لا أحد يهتمّ من بناه. تستخدمه لمّا الفعل أهمّ من الفاعل، أو لمّا تريد بدوء البيروقراطيّة.`,mnemonicAr:`**werden + Partizip II.** الأمر بهذه البساطة. صرّف werden حسب الزمن، وضع Partizip II في النهاية.`,mnemonicDe:`werden + Partizip II  =  Passiv`,steps:[{titleAr:`1️⃣ Passiv حاضر`,de:`Das Auto wird repariert.`,ar:`wird (mein/dein/sein...) + Partizip II في النهاية. الفاعل يختفي.`},{titleAr:`2️⃣ Passiv ماضٍ (Präteritum)`,de:`Das Auto wurde gestern repariert.`,ar:`wurde + Partizip II. هذا الزمن الأكثر استعمالاً في النصوص الإخباريّة والتقارير.`},{titleAr:`3️⃣ Passiv مع Modalverb`,de:`Das Auto muss repariert werden.`,ar:`الـModalverb يأخذ مكان werden المُصرَّف، وwerden يصبح Infinitiv في النهاية. قاعدة بليغة جدّاً.`},{titleAr:`4️⃣ Passiv ماضي تامّ (Perfekt)`,de:`Das Auto ist repariert worden.  (NICHT: geworden!)`,ar:`هنا الحيلة: في الـPassiv Perfekt، Partizip II من werden ليس "geworden" بل **"worden"** (بدون ge-). هذا فرق دقيق يُكشَف به مستواك.`}],advancedPatterns:[{title:`Zustandspassiv (passive of state)`,de:`Die Tür ist geöffnet. (= مفتوحة، حالة)  ≠  Die Tür wird geöffnet. (= يتمّ فتحها، فعل)`,ar:`sein + Partizip II = حالة. werden + Partizip II = حدث/فعل.`},{title:`إضافة "von" أو "durch" لذكر الفاعل`,de:`Das Haus wurde von Architekten gebaut.  ·  Das Auto wurde durch einen Unfall zerstört.`,ar:`von = الفاعل المباشر (شخص). durch = السبب الوسيط (حدث، أداة).`},{title:`Passiv بدلاً من "man"`,de:`Hier wird Deutsch gesprochen. = Man spricht hier Deutsch.`,ar:`في النصوص الرسميّة، Passiv أنيق أكثر من "man".`},{title:`sein + zu + Infinitiv (passive replacement)`,de:`Das Problem ist zu lösen. (= Das Problem kann/muss gelöst werden.)`,ar:`صيغة بديلة عن "können/müssen + Passiv" — تظهر في الكتابات الرسميّة.`}],examWisdom:`في امتحان telc B1 Schreiben (الرسالة)، استخدام Passiv مرّة واحدة على الأقلّ يرفع علامتك. مثال: "Ich hoffe, dass mein Anliegen schnell bearbeitet wird." — جملة بليغة جاهزة.`},{topicId:`wechselpraepositionen`,greeting:`Wechselpräpositionen — die zweideutigen Helfer!`,storyAr:`الـWechselpräpositionen (an, auf, hinter, in, neben, über, unter, vor, zwischen) هي حروف "ذات وجهين": أحياناً Akk، أحياناً Dat. القاعدة: **Akk للحركة (Wohin؟)، Dat للموقع (Wo؟).**`,mnemonicAr:`**Wohin → Akkusativ  ·  Wo → Dativ.** خدعة الذاكرة: "Wo + Dativ" (حرفان حرفان) — "Wohin + Akkusativ" (أكثر حروفاً = حركة أطول).`,mnemonicDe:`Wohin? → Akkusativ  ·  Wo? → Dativ`,steps:[{titleAr:`1️⃣ القائمة الرسميّة (9 حروف)`,de:`an, auf, hinter, in, neben, über, unter, vor, zwischen`,ar:`احفظها بهذا الترتيب — مثل قافية. حرفان مكانيّان (an, in)، خمسة موقعيّة (hinter, neben, über, unter, vor)، اثنان خاصّان (auf, zwischen).`},{titleAr:`2️⃣ التمييز السريع: حركة أم موقع؟`,de:`Ich gehe in die Stadt.  (Wohin → Akk)   ·   Ich bin in der Stadt.  (Wo → Dat)`,ar:`فعل الحركة (gehen, fahren, stellen, legen, hängen, setzen) → Akk. فعل الموقع (sein, stehen, liegen, hängen, sitzen) → Dat.`},{titleAr:`3️⃣ الزوج الخادع: stellen/stehen, legen/liegen`,de:`Ich stelle die Tasse auf den Tisch. (Akk)  ·  Die Tasse steht auf dem Tisch. (Dat)`,ar:`"stellen" أضع، "stehen" يقف. "legen" أضع أفقيّاً، "liegen" يستلقي. كلّ زوج: الأوّل حركة (Akk)، الثاني موقع (Dat).`},{titleAr:`4️⃣ التركيبات الجاهزة (Akk أو Dat بدون منطق)`,de:`Ich denke an dich. (Akk)  ·  Ich freue mich auf dich. (Akk)  ·  Ich nehme an … teil. (Dat)`,ar:`بعض الأفعال تتطلّب Akk أو Dat بشكل ثابت. احفظها كقطعة واحدة (Verb + Präposition + Case).`}],advancedPatterns:[{title:`Verbalstil vs. Nominalstil (لمستوى B2)`,de:`Akk: bei der Ankunft in Berlin / Dat: nach der Ankunft in Berlin (location)`,ar:`في الـNominalisierung، تظهر Wechselpräpositionen بكثرة. المعنى يحدّد الحالة.`},{title:`Kontraktionen (ins, im, am, ans, aufs, …)`,de:`in das = ins (Akk)  ·  in dem = im (Dat)  ·  an das = ans  ·  an dem = am  ·  auf das = aufs`,ar:`في اللغة المنطوقة، الأدوات تندمج مع حروف الجرّ. في الكتابة الرسميّة استخدم الصيغة الكاملة.`},{title:`Doppeldeutigkeit (الغموض المتعمَّد)`,de:`Sie hängt das Bild an die Wand. (تعليقه — Akk)  ·  Das Bild hängt an der Wand. (مُعلَّق — Dat)`,ar:`يستخدم الكتّاب هذا الفرق لإثارة لحظات تسل��ل في القصّة.`}],examWisdom:`القاعدة الذهبيّة لامتحان B1: قبل أيّ Wechselpräposition، اسأل نفسك "Wohin أم Wo؟". إن لم تستطع الإجابة، استخدم سياقاً أبسط (zu بدلاً من an).`},{topicId:`relativsatz`,greeting:`Relativsätze — die Brückenbauer der Sprache!`,storyAr:`الـRelativsatz (الجملة الموصولة) هي **جملة فرعيّة تعطي معلومة إضافيّة عن اسم في الجملة الرئيسيّة**. مثل "الرجل **الذي** رأيته أمس" — "der Mann, **den** ich gestern gesehen habe."`,mnemonicAr:`**اسم الموصول = أداة + (n) + جنس + حالة.** der/die/das/die هي نفس أدوات التعريف، لكن في الـDativ: dem/der/dem/**denen** (لاحظ -en في الجمع).`,mnemonicDe:`Relativpronomen wie Artikel — aber im Dativ Plural: denen!`,steps:[{titleAr:`1️⃣ جدول اسم الموصول (Relativpronomen)`,de:`Nom: der/die/das/die  ·  Akk: den/die/das/die  ·  Dat: dem/der/dem/denen  ·  Gen: dessen/deren/dessen/deren`,ar:`فقط Dativ Plural (denen) وGenitiv (dessen/deren) مختلفة عن أدوات التعريف.`},{titleAr:`2️⃣ تحديد الحالة`,de:`Der Mann, der hier wohnt. (Nom — هو الفاعل في الجملة الفرعيّة)`,ar:`الحالة تتحدّد بدور الموصول في **الجملة الفرعيّة**، لا الرئيسيّة. استبدل الموصول بضمير وجرّب: لو "er" → Nom، "ihn" → Akk، "ihm" → Dat.`},{titleAr:`3️⃣ مع حروف الجرّ`,de:`Der Tisch, auf dem das Buch liegt.`,ar:`الجرّ يبقى قبل الموصول. لو الجرّ يأخذ Dat → الموصول Dat. لو Akk → Akk.`},{titleAr:`4️⃣ Relativpronomen "was"`,de:`Das ist alles, was ich weiß.  ·  Etwas, was du nicht kennst.`,ar:`بعد "alles, etwas, nichts, vieles, das" نستخدم "was" بدل "das".`}],advancedPatterns:[{title:`Genitiv (dessen/deren) — مستوى راقٍ`,de:`Der Mann, dessen Auto rot ist.  ·  Die Frau, deren Sohn studiert.`,ar:`dessen = للمذكّر/المحايد، deren = للمؤنّث/الجمع. هذه الأشكال نادرة لكنّها رفيعة المستوى — استعمالها في الـSchreiben يُظهر تمكّناً.`},{title:`wo / woher / wohin (لمكان)`,de:`Die Stadt, wo ich wohne.  =  Die Stadt, in der ich wohne.`,ar:`بدلاً من "in dem/der" يمكن استعمال "wo" للأماكن الجغرافيّة. أبسط لكن أقلّ رسميّة.`},{title:`wofür / wovon / womit (مع غير العاقل)`,de:`Das ist das Buch, wovon ich gesprochen habe.`,ar:`بدلاً من "von dem" مع شيء غير عاقل، استخدم "wovon". هذا مع كلّ Präposition: über → worüber, an → woran, …`},{title:`Reduzierter Relativsatz (Partizipialkonstruktion — B2)`,de:`Das von ihm gekaufte Auto. = Das Auto, das von ihm gekauft wurde.`,ar:`صيغة مكثّفة: Partizip II يُوضع بين الأداة والاسم. تختصر جملة كاملة. شائعة في النصوص الرسميّة.`}],examWisdom:`في Schreiben B1، إدخال جملة موصولة مرّة واحدة يرفع علامة "Wortschatz und Strukturen". مثال آمن: "Ich habe einen Kollegen, der Arabisch spricht."`},{topicId:`genitiv`,greeting:`Genitiv — der edle, manchmal vergessene Fall!`,storyAr:`الـGenitiv (المضاف إليه) هو الحالة الرابعة، وهي **حالة الملكيّة والانتماء**. مثل "كتاب الطالب" — "das Buch **des Schülers**". في الكلام اليومي يحلّ Dativ + von محلّها، لكن في الكتابة الرسميّة Genitiv تجعلك تبدو متمكّناً.`,mnemonicAr:`**Genitiv: des/der/des/der.** الأسماء المذكّرة والمحايدة المفردة تأخذ -s/-es في النهاية. (des Mannes, des Buches)`,mnemonicDe:`Genitiv: des/der/des/der  +  -s/-es bei Maskulinum/Neutrum`,steps:[{titleAr:`1️⃣ صيغة Genitiv`,de:`der → des (+s)   ·   die → der    ·   das → des (+s)   ·   die (Pl) → der`,ar:`الأسماء المذكّرة والمحايدة المفردة + s (أو es لو من حرف واحد): des Mannes, des Buches، des Vaters.`},{titleAr:`2️⃣ حروف الجرّ بـGenitiv`,de:`während (خلال), wegen (بسبب), trotz (رغم), statt (بدلاً), innerhalb/außerhalb, anstelle`,ar:`هذه الحروف رسميّة. في الكلام اليومي: wegen + Dat (شائع لكن غير رسميّ). في الكتابة احرص على Genitiv.`},{titleAr:`3️⃣ الأفعال التي تأخذ Genitiv (نادرة لكن قويّة)`,de:`sich erinnern + Gen (أقدم) → الآن: sich erinnern an + Akk`,ar:`معظم أفعال Genitiv انقرضت. الباقي رسميّ جدّاً: bedürfen, gedenken, sich rühmen, sich enthalten.`},{titleAr:`4️⃣ في الكلام: Dativ + von`,de:`das Auto meines Vaters (Gen)  =  das Auto von meinem Vater (Dat — أكثر شيوعاً)`,ar:`في الـSprechen، استعمال Genitiv قد يبدو متكلّفاً. في الـSchreiben، استعمل Genitiv لتُظهر مستوى عالٍ.`}],advancedPatterns:[{title:`Genitivobjekt (نادر، رسميّ)`,de:`Er beschuldigt mich des Diebstahls.`,ar:`بعض الأفعال القانونيّة/الرسميّة تأخذ Akk + Gen: beschuldigen, anklagen, bezichtigen, verdächtigen.`},{title:`Adjektivendung في Genitiv`,de:`des großen Mannes  ·  des großen Hauses  ·  der großen Frau  ·  der großen Kinder`,ar:`مع der/des/dem... الصفة تأخذ -en في كلّ الحالات والجموع (Genitiv بلا استثناء).`},{title:`Possessivpronomen في Genitiv`,de:`meines Bruders, meines Buches, meiner Schwester, meiner Eltern`,ar:`meines (m/n) — meiner (f/Pl). كلّ ضمير ملكيّة يأخذ النهايات نفسها.`}],examWisdom:`لإثبات مستوى B1+ في كتابة الـtelc، استخدم "trotz + Gen" أو "wegen + Gen" مرّة واحدة في الرسالة. مثال جاهز: "Trotz des schlechten Wetters bin ich gekommen."`},{topicId:`praeteritum`,greeting:`Präteritum — die Sprache der Bücher und Zeitungen!`,storyAr:`الـPräteritum (الماضي البسيط) هو "ماضي الكتب". لا يُستعمل في الكلام اليومي إلّا مع 6 أفعال شائعة (sein, haben, الأفعال الشكليّة). للقصص والصحف والتقارير، Präteritum أنيق وسريع — كلمة واحدة بدل اثنين في الـPerfekt.`,mnemonicAr:`**في الكلام: Perfekt. في الكتابة: Präteritum.** الاستثناءات الـ6 المكلَّمة: war, hatte, konnte, musste, wollte, sollte.`,mnemonicDe:`Sprich Perfekt — schreib Präteritum!`,steps:[{titleAr:`1️⃣ الأفعال الضعيفة (-te)`,de:`machen → ich machte / du machtest / er machte / wir machten`,ar:`الجذر + -te- + النهاية الشخصيّة. ich/er ينتهيان فقط بـ-te (لا -e ولا -t إضافيّة).`},{titleAr:`2️⃣ الأفعال القوية (تغيّر حرف العلّة)`,de:`gehen → ging   ·   sehen → sah   ·   kommen → kam   ·   trinken → trank`,ar:`لا تأخذ -te. ich/er لا يأخذان أيّ نهاية. باقي الضمائر النهايات العاديّة.`},{titleAr:`3️⃣ الأفعال المختلطة (تغيير + -te)`,de:`denken → dachte   ·   bringen → brachte   ·   wissen → wusste   ·   kennen → kannte`,ar:`7 أفعال "هجينة" تغيّر الجذر + تأخذ -te-. احفظها كقائمة.`},{titleAr:`4️⃣ الأفعال الستّة المكلَّمة`,de:`war (sein) · hatte (haben) · konnte · musste · wollte · sollte · durfte · mochte`,ar:`فقط هذه الأفعال تُسمَع في المحادثة اليوميّة بـPräteritum. الباقي يُفضَّل بـPerfekt.`}],advancedPatterns:[{title:`Plusquamperfekt (الماضي الأبعد)`,de:`Ich hatte schon gegessen, als er kam.`,ar:`hatte/war + Partizip II — يدلّ على ماضٍ قبل ماضٍ. شائع مع "als" و"nachdem".`},{title:`كتابة قصّة (Erzählzeit)`,de:`Es war einmal ein König, der drei Töchter hatte ...`,ar:`كلّ الحكايات والقصص تُكتَب بـPräteritum. هذا يُشعر القارئ بالغوص في عالم آخر.`},{title:`Lebenslauf (السيرة الذاتيّة)`,de:`2018 begann ich mein Studium. 2022 schloss ich es ab.`,ar:`الـLebenslauf الرسمي (للوظيفة، الإقامة) يُكتَب دائماً بـPräteritum — أرقى من Perfekt.`}],examWisdom:`في امتحان telc B1 Schreiben (الرسالة)، استخدم Perfekt. لكن في امتحانات B2+، خصوصاً في "Stellungnahme" أو سرد قصّة، استخدم Präteritum — يرفع علامة "Wortschatz" بشكل ملحوظ.`,advancedExercises:[{id:`t-pr-1`,promptDe:`Als Kind ____ ich oft ins Schwimmbad.`,options:[{id:`a`,de:`gehte`},{id:`b`,de:`ging`},{id:`c`,de:`gegangen`}],correct:`b`,explanationAr:`gehen فعل قوي → ging (لا -te). gegangen هو Partizip II وليس Präteritum.`},{id:`t-pr-2`,promptDe:`Sie ____, dass es regnen würde.`,options:[{id:`a`,de:`wusste`},{id:`b`,de:`wisste`},{id:`c`,de:`wisst`}],correct:`a`,explanationAr:`wissen فعل مختلط → wusste (تغيير الجذر + -te).`},{id:`t-pr-3`,promptDe:`Bevor er kam, ____ ich schon ____.`,options:[{id:`a`,de:`habe / gegessen`},{id:`b`,de:`hatte / gegessen`},{id:`c`,de:`war / gegessen`}],correct:`b`,explanationAr:`Plusquamperfekt: hatte + Partizip II — لحدث وقع قبل حدث ماضٍ آخر.`}]},{topicId:`nebensatz`,greeting:`Nebensätze — die Geschwister-Sätze!`,storyAr:`الـNebensatz (الجملة الجانبيّة) مثل **توأم** يلتصق بالجملة الرئيسيّة. خصوصيّته: الفعل المُصرَّف "يهرب" دائماً إلى نهاية الجملة. أداة الربط (weil, dass, wenn, obwohl, …) تكون البوّابة التي تحوّل الجملة من رئيسيّة إلى جانبيّة.`,mnemonicAr:`**Konjunktion → Verb am Ende!** القاعدة لا تتغيّر. الفاصلة قبل الـNebensatz إجباريّة.`,mnemonicDe:`Nach der Konjunktion: Verb am Ende!`,steps:[{titleAr:`1️⃣ أدوات الربط الـ6 الذهبيّة`,de:`weil (لأنّ) · dass (أنّ) · wenn (لو/متى) · obwohl (رغم أنّ) · ob (هل) · damit (لكي)`,ar:`كلّها ترسل الفعل إلى النهاية. weil = سبب، dass = اقتباس، wenn = شرط/تكرار، obwohl = تناقض، ob = سؤال غير مباشر، damit = هدف.`},{titleAr:`2️⃣ موقع الفعل`,de:`Ich gehe nicht, weil ich krank bin.   (NICHT: weil bin ich krank)`,ar:`الفعل المُصرَّف يأتي **دائماً** في آخر الـNebensatz. الفاعل يأتي مباشرة بعد أداة الربط.`},{titleAr:`3️⃣ Inversion (لمّا الـNebensatz في البداية)`,de:`Weil ich krank bin, gehe ich nicht.`,ar:`إذا بدأت بالـNebensatz، الجملة الرئيسيّة تبدأ بفعلها (Inversion): Weil … bin, **gehe** ich. هذا "قاعدة V2" البليغة.`},{titleAr:`4️⃣ مع الأفعال الشكليّة`,de:`Ich glaube, dass er nicht kommen kann.`,ar:`الترتيب في النهاية: Vollverb (Infinitiv) + Modalverb (المُصرَّف). نفس الترتيب للأفعال القابلة للفصل: dass er an-kommen kann.`}],advancedPatterns:[{title:`دmm وdass-Satz vs. Infinitiv mit zu`,de:`Ich hoffe, dass du kommst.   ·   Ich hoffe zu kommen.`,ar:`لو الفاعلان نفس الشخص → Infinitiv mit zu أنيق. لو مختلفان → dass-Satz إجباريّ.`},{title:`wenn vs. als`,de:`als = حدث ماضٍ مرّة واحدة   ·   wenn = حاضر/مستقبل/تكرار في الماضي`,ar:`فخّ امتحاني! "als ich klein war" (مرّة في الماضي). "immer wenn ich klein war" (تكرار). "wenn ich Zeit habe" (حاضر/مستقبل).`},{title:`Nebensatz بدون أداة (Asyndetisch)`,de:`Ich glaube, er kommt morgen. (= Ich glaube, dass er morgen kommt.)`,ar:`بعد أفعال الإدراك (glauben, denken, hoffen, …) يمكن حذف dass — لكنّ الفعل يعود للموقع 2!`},{title:`Schachtelsatz (الجمل المتداخلة)`,de:`Ich weiß, dass er glaubt, dass sie kommt.`,ar:`كلّ Nebensatz داخل آخر يحتفظ بقاعدة "verb am Ende". قمّة المهارة في B2.`}],examWisdom:`في Schreiben B1، اس��عمال "weil + Nebensatz" مرّة واحدة + "obwohl + Nebensatz" مرّة + "wenn + Nebensatz" مرّة = ثلاث جمل بليغة ترفع علامتك. وأهمّ شيء: **الفاصلة قبل الـNebensatz إجباريّة!**`,advancedExercises:[{id:`t-nb-1`,promptDe:`Ich komme nicht, ____ ich krank bin.`,options:[{id:`a`,de:`denn`},{id:`b`,de:`weil`},{id:`c`,de:`aber`}],correct:`b`,explanationAr:`weil = سبب يرسل الفعل للنهاية. denn سبب لكنّه Konjunktion يبقي الفعل في موقعه.`},{id:`t-nb-2`,promptDe:`Obwohl es regnet, ____ wir spazieren.`,options:[{id:`a`,de:`wir gehen`},{id:`b`,de:`gehen`},{id:`c`,de:`gehen wir`}],correct:`c`,explanationAr:`بعد Nebensatz في البداية، الجملة الرئيسيّة تبدأ بالفعل (V2): gehen wir.`},{id:`t-nb-3`,promptDe:`____ ich klein war, wohnte ich in Damaskus.`,options:[{id:`a`,de:`Wenn`},{id:`b`,de:`Als`},{id:`c`,de:`Ob`}],correct:`b`,explanationAr:`حدث في الماضي مرّة واحدة → als. wenn للحاضر/تكرار.`}]},{topicId:`adjektive`,greeting:`Adjektivdeklination — der Albtraum vieler Lerner!`,storyAr:`تصريف الصفات هو الفخّ الأكبر للناطقين بالعربية. الصفة في الألمانيّة تتغيّر نهايتها حسب: **(1) جنس الاسم، (2) حالة الاسم، (3) الأداة المُستعمَلة قبلها**. لكن لا تخف — في الواقع، 90% من الحالات تنتهي بـ-en!`,mnemonicAr:`**القاعدة الذهبيّة: إذا الأداة "تشتغل" (تظهر الجنس + الحالة) → الصفة تأخذ -e أو -en. إذا الأداة "ضعيفة" أو غائبة → الصفة تأخذ النهاية القويّة.**`,mnemonicDe:`Sieht der Artikel die Endung — Adjektiv schwach (-e/-en).`,steps:[{titleAr:`1️⃣ مع der/die/das (تصريف ضعيف)`,de:`der gute Mann (Nom) · die gute Frau · das gute Kind · die guten Kinder`,ar:`بعد der/die/das (وكلّ مشتقّاتها dieser, jener, …)، الصفة تأخذ -e في Nominativ مفرد، -en في كلّ شيء آخر.`},{titleAr:`2️⃣ مع ein/kein/mein (تصريف مختلط)`,de:`ein guter Mann · eine gute Frau · ein gutes Kind · meine guten Kinder`,ar:`ein لا تظهر الجنس في النوم/الأكك → الصفة تأخذ النهاية القويّة (-er, -es). الباقي: -e أو -en.`},{titleAr:`3️⃣ بدون أداة (تصريف قوي)`,de:`guter Wein · gute Suppe · gutes Bier · gute Bücher`,ar:`لمّا لا توجد أداة (Plural بدون أداة)، الصفة تأخذ نهايات الأداة نفسها (er/e/es/e). شائع في الإعلانات والقوائم.`},{titleAr:`4️⃣ القاعدة المُختصَرة (90% من الحالات)`,de:`Wenn unsicher → -en   (außer Nom Sg + Akk Sg neutrum/feminin)`,ar:`في الشكّ، اكتب -en. في 9 من 16 حالة تكون -en. الاستثناءات الذهبيّة: Nom Sg (-e/er/es) و Akk Sg مؤنّث/محايد (-e/es).`}],advancedPatterns:[{title:`بعد Possessivpronomen + Indefinit`,de:`meine guten Freunde · keine guten Beispiele · einige gute Bücher`,ar:`mein/dein/sein/... + einige/wenige/viele/andere → جميعاً تتبع نفس قاعدة der.`},{title:`Steigerung (مع المقارنة)`,de:`der bessere Mann · ein schönerer Garten · die schönsten Blumen`,ar:`الصفة في صيغة المقارنة (besser, schöner) أو التفضيل (best-, schönst-) تأخذ نفس النهايات + er/st-.`},{title:`Adjektive auf -el/-er`,de:`dunkel → ein dunkler Raum   ·   teuer → ein teures Auto`,ar:`الصفات المنتهية بـ-el أو -er تحذف الـ-e عند التصريف: dunkel + er = dunkler (لا dunkeler).`},{title:`Substantivierte Adjektive (الصفة كاسم)`,de:`der Deutsche · ein Deutscher · die Reiche · ein Reicher`,ar:`الصفة لمّا تصبح اسماً تحتفظ بقواعد التصريف. تُكتَب بحرف كبير. شائع في الجنسيّات والمعاني المجرّدة.`}],examWisdom:`في Schreiben، استعمال 3-4 صفات مُصرَّفة صحيحاً = نقطة كاملة في "Wortschatz und Strukturen". قاعدة الطوارئ في الامتحان: لو شككت، اكتب -en. أنت ستكون صحيحاً 60% من الوقت.`,advancedExercises:[{id:`t-aj-1`,promptDe:`Ich kaufe ein____ neu____ Auto.`,options:[{id:`a`,de:`einen / neuen`},{id:`b`,de:`ein / neues`},{id:`c`,de:`einen / neues`}],correct:`b`,explanationAr:`Auto محايد (das Auto). Akk محايد = ein (لا تتغيّر) → الصفة قويّة: neues.`},{id:`t-aj-2`,promptDe:`Mit ____ alt____ Auto kann man nicht weit fahren.`,options:[{id:`a`,de:`dem / alten`},{id:`b`,de:`einem / alten`},{id:`c`,de:`einer / altem`}],correct:`b`,explanationAr:`mit + Dat. einem (محايد) → الصفة -en (alten). الخيار a صحيح أيضاً لكن لا يطابق "ein".`},{id:`t-aj-3`,promptDe:`____ Wein ist gesund.`,options:[{id:`a`,de:`Roter`},{id:`b`,de:`Rote`},{id:`c`,de:`Rotes`}],correct:`a`,explanationAr:`بدون أداة → تصريف قوي. Wein مذكّر Nom → Roter.`}]},{topicId:`trennbare`,greeting:`Trennbare Verben — die Verben mit Mantel und Hut!`,storyAr:`الـTrennbare Verben (الأفعال القابلة للفصل) مثل **شخص يلبس قبّعة**: في حالة الراحة (Infinitiv) القبّعة على رأسه. في الحركة (الجملة الرئيسيّة)، القبّعة تطير وتقع في **آخر الجملة**. مثال: aufstehen → "Ich **stehe** um 7 Uhr **auf**."`,mnemonicAr:`**البادئة (auf, an, ein, aus, mit, vor, zu, …) تُلقَى إلى نهاية الجملة في الـHauptsatz.** في الـNebensatz والـInfinitiv تبقى ملتصقة بالفعل.`,mnemonicDe:`Hauptsatz: Präfix ans Ende!  ·  Nebensatz/Infinitiv: zusammen.`,steps:[{titleAr:`1️⃣ البادئات الـ12 الذهبيّة`,de:`ab-, an-, auf-, aus-, ein-, mit-, nach-, vor-, weg-, zu-, zurück-, zusammen-`,ar:`هذه البادئات قابلة للفصل (مع نبر صوتي عليها). لها معنى مكاني واضح.`},{titleAr:`2️⃣ في الـHauptsatz: البادئة في النهاية`,de:`aufstehen → Ich stehe um 7 Uhr auf.   ·   einkaufen → Wir kaufen heute ein.`,ar:`الفعل المُصرَّف في الموقع 2، البادئة في الموقع الأخير. هذا "Satzklammer" (قوس الجملة).`},{titleAr:`3️⃣ في Perfekt: البادئة + ge + جذر + en/t`,de:`aufstehen → aufgestanden   ·   einkaufen → eingekauft`,ar:`الـge- يُحشَر **بين** البادئة والجذر. البادئة لا تنفصل في Partizip II.`},{titleAr:`4️⃣ في الـNebensatz / Infinitiv: ملتصقة`,de:`Ich glaube, dass er um 7 Uhr aufsteht.   ·   Ich versuche, früh aufzustehen.`,ar:`في Nebensatz (verb am Ende): aufsteht كاملاً. في Infinitiv mit zu: auf-zu-stehen (zu بين البادئة والجذر).`}],advancedPatterns:[{title:`Untrennbare Verben (غير القابلة)`,de:`be-, ent-, er-, ge-, ver-, zer-, miss-`,ar:`هذه البادئات لا تنفصل أبداً. لا تأخذ ge- في Partizip II: besucht (NICHT: gebesucht), verstanden, zerstört.`},{title:`البادئات الثنائيّة (durch-, über-, um-, unter-, wider-, wieder-)`,de:`durchgehen (يعبر — قابلة) ≠ durchschauen (يفهم — غير قابلة)`,ar:`هذه البادئات قابلة للفصل لمّا لها معنى مكاني، وغير قابلة لمّا لها معنى مجازي. النبر الصوتي يحدّد!`},{title:`تغيير المعنى الكامل بسبب البادئة`,de:`kommen (يأتي) → ankommen (يصل) → mitkommen (يرافق) → vorkommen (يحدث) → bekommen (ينال)`,ar:`البادئة تغيّر معنى الفعل تماماً. كلّ بادئة + جذر = كلمة جديدة.`}],examWisdom:`الخطأ الأشيع في Sprechen B1: نسيان وضع البادئة في النهاية. تمرين: قبل كلّ جملة فيها فعل قابل للفصل، خذ ثانية لتقرّر "أين البادئة الآن؟". هذه الثانية ترفعك من A2 إلى B1.`,advancedExercises:[{id:`t-tv-1`,promptDe:`Ich ____ jeden Morgen um 6 Uhr ____.`,options:[{id:`a`,de:`aufstehe`},{id:`b`,de:`stehe / auf`},{id:`c`,de:`aufstehe / auf`}],correct:`b`,explanationAr:`aufstehen قابل للفصل في Hauptsatz: stehe في الموقع 2، auf في النهاية.`},{id:`t-tv-2`,promptDe:`Er hat das Geschenk schon ____.`,options:[{id:`a`,de:`gebekommen`},{id:`b`,de:`bekommen`},{id:`c`,de:`bekamen`}],correct:`b`,explanationAr:`be- بادئة غير قابلة للفصل → لا تأخذ ge- في Partizip II.`},{id:`t-tv-3`,promptDe:`Ich versuche, früh ____.`,options:[{id:`a`,de:`aufzustehen`},{id:`b`,de:`zu aufstehen`},{id:`c`,de:`aufstehen zu`}],correct:`a`,explanationAr:`في Infinitiv mit zu، الـzu يُحشَر بين البادئة والجذر: auf-zu-stehen.`}]},{topicId:`komparativ`,greeting:`Komparativ und Superlativ — die Welt vergleichen!`,storyAr:`لكلّ صفة **3 درجات**: العادي (groß)، المقارنة (größer = أكبر)، التفضيل (am größten = الأكبر). في الألمانيّة، نضيف -er للمقارنة و-st للتفضيل، مع تغيير حرف العلّة في كثير من الأحيان (a→ä, o→ö, u→ü).`,mnemonicAr:`**عادي + er = مقارنة. عادي + (e)st = تفضيل.** + Umlaut للأحرف القصيرة a/o/u. + "als" للمقارنة، "am ___sten" للتفضيل.`,mnemonicDe:`klein → kleiner → am kleinsten   ·   groß → größer → am größten`,steps:[{titleAr:`1️⃣ المقارنة (Komparativ): -er + als`,de:`klein → kleiner   ·   schnell → schneller   ·   alt → älter (Umlaut!)`,ar:`صفة + er. الأحرف القصيرة a/o/u تأخذ Umlaut عادة (alt→älter). + "als" للمقارنة: "Er ist größer **als** ich."`},{titleAr:`2️⃣ التفضيل (Superlativ): am ___sten`,de:`klein → am kleinsten   ·   alt → am ältesten   ·   schnell → am schnellsten`,ar:`am + صفة + (e)sten. الـ-e- تُضاف بعد d/t/s/z لتسهيل النطق (alt-est-en).`},{titleAr:`3️⃣ الأشكال الشاذّة (احفظها)`,de:`gut → besser → am besten   ·   viel → mehr → am meisten   ·   gern → lieber → am liebsten   ·   hoch → höher → am höchsten   ·   nah → näher → am nächsten`,ar:`هذه الـ5 صفات لا تتبع القاعدة. شائعة جدّاً في الكلام اليومي والامتحان.`},{titleAr:`4️⃣ التفضيل قبل الاسم: der/die/das + -ste`,de:`der schnellste Läufer · die schönste Stadt · das größte Problem`,ar:`لمّا التفضيل وصف لاسم، يُصرَّف مع أداة der/die/das + -ste-en حسب الجنس والحالة.`}],advancedPatterns:[{title:`مقارنة المساواة (genauso ... wie)`,de:`Sie ist (genau)so groß wie ich. (≠ als)`,ar:`لتعبير "مثل/بنفس القدر" نستخدم "(genau)so + adjektiv + wie". اللحظة "wie" — لا "als"! خلطها خطأ شائع.`},{title:`immer + Komparativ (يزداد فأكثر)`,de:`Es wird immer kälter. · Sie wird immer schöner.`,ar:`تركيب جميل لتعبير "أكثر فأكثر / يزداد ...". مفيد جدّاً في Sprechen.`},{title:`je ... desto (كلّما ... كلّما)`,de:`Je mehr du lernst, desto besser sprichst du.`,ar:`تركيب بليغ — يربط مقارنتين. ينقل الجملة إلى مستوى B2. desto يُتبع بالفعل المُصرَّف (Inversion).`},{title:`Komparativ بدون als (للتعبير المُطلَق)`,de:`Eine ältere Dame (سيّدة كبيرة في السنّ، نسبيّاً)   ·   Ein längerer Aufenthalt (إقامة طويلة نسبيّاً)`,ar:`الـKomparativ بدون "als" يعني "أكبر من المتوسّط" بدون مقارنة محدّدة. شائع في ال��تابة الرسميّة.`}],examWisdom:`استعمل "je ... desto" مرّة في Schreiben → علامة عالية. مثال جاهز: "Je mehr Deutsch ich lerne, desto leichter wird das Leben in Deutschland."`,advancedExercises:[{id:`t-km-1`,promptDe:`Mein Bruder ist größer ____ ich.`,options:[{id:`a`,de:`wie`},{id:`b`,de:`als`},{id:`c`,de:`denn`}],correct:`b`,explanationAr:`في المقارنة (Komparativ) نستخدم "als". "wie" للمساواة فقط.`},{id:`t-km-2`,promptDe:`Was ist das ____ Tier?`,options:[{id:`a`,de:`größer`},{id:`b`,de:`größte`},{id:`c`,de:`am größten`}],correct:`b`,explanationAr:`التفضيل قبل الاسم: das größte (مع der/die/das + -te). "am größten" يُستعمل بعد الفعل.`},{id:`t-km-3`,promptDe:`____ er sich anstrengt, ____ Erfolg hat er.`,options:[{id:`a`,de:`Wenn / dann`},{id:`b`,de:`Je / desto`},{id:`c`,de:`Wie / so`}],correct:`b`,explanationAr:`Je + Komparativ ... desto + Komparativ — قاعدة الترابط.`}]},{topicId:`imperativ`,greeting:`Imperativ — die Sprache der Befehle und Bitten!`,storyAr:`الـImperativ (الأمر) في الألمانيّة له **3 صيغ**: للـdu (الصديق)، للـihr (مجموعة أصدقاء)، للـSie (الرسمي). الفرق بين "تعال!" لصديق و"تفضّل!" لغريب يحدّد إن كنتَ مهذّباً أم لا.`,mnemonicAr:`**du: جذر الفعل (بدون -st)  ·  ihr: جذر + t  ·  Sie: Sie + جذر + en (مقلوب).** الفعل دائماً في الموقع 1.`,mnemonicDe:`du: komm!  ·  ihr: kommt!  ·  Sie: Kommen Sie!`,steps:[{titleAr:`1️⃣ صيغة du (الأكثر شيوعاً مع الأصدقاء)`,de:`du kommst → Komm!   ·   du gibst → Gib!   ·   du fährst → Fahr!`,ar:`احذف الـ-st النهاية. الأفعال القوية التي تغيّر e→ie/i تحتفظ بالتغيير (gibst → Gib!). لكن الأفعال التي تأخذ Umlaut a→ä **لا** تحتفظ به (fährst → Fahr!).`},{titleAr:`2️⃣ صيغة ihr`,de:`ihr kommt → Kommt!   ·   ihr gebt → Gebt!`,ar:`بسيطة: نفس صيغة ihr في المضارع، لكن بدون "ihr". الفعل وحده.`},{titleAr:`3️⃣ صيغة Sie (الرسمي + الجمع المهذّب)`,de:`Sie kommen → Kommen Sie!   ·   Sie geben → Geben Sie!`,ar:`Inversion: الفعل في الموقع 1 + Sie في الموقع 2. "Sie" لا تُحذَف. هذه الصيغة للغرباء، الموظّفين، الأطبّاء.`},{titleAr:`4️⃣ صيغة wir (دعوة)`,de:`Gehen wir!   (= هيّا نذهب)   ·   Trinken wir Kaffee!`,ar:`الفعل في Inversion + wir = "هيّا" (Let's ...). صيغة لطيفة لاقتراح جماعي.`}],advancedPatterns:[{title:`sein → الشاذّ`,de:`du: Sei!   ·   ihr: Seid!   ·   Sie: Seien Sie!`,ar:`sein لا يتبع القاعدة. صيغ Imperativ تُحفَظ.`},{title:`تخفيف الأمر بـbitte / mal / doch`,de:`Komm bitte mal!   ·   Setz dich doch!   ·   Hilf mir mal!`,ar:`هذه الكلمات الصغيرة (Modalpartikel) تُحوّل الأمر إلى طلب لطيف. ضروريّة جدّاً في الكلام.`},{title:`الأفعال القابلة للفصل في Imperativ`,de:`aufstehen → Steh auf!   ·   einkaufen → Kauf ein!`,ar:`البادئة تنفصل وتذهب للنهاية، تماماً كأيّ Hauptsatz.`},{title:`Imperativ المهذّب البديل: Konjunktiv II`,de:`Könnten Sie mir bitte helfen? (= Helfen Sie mir bitte!)`,ar:`في المواقف الرسميّة جدّاً، نستخدم Konjunktiv II بدل Imperativ. أرقى وأكثر تأدّباً.`}],examWisdom:`في Sprechen Teil 3 (التخطيط المشترك)، استخدم "Lass uns ..." أو "Wir könnten ..." بدل Imperativ المباشر. يُظهر تعاوناً واحتراماً للشريك.`,advancedExercises:[{id:`t-im-1`,promptDe:`____ mir bitte das Salz! (du)`,options:[{id:`a`,de:`Gibst`},{id:`b`,de:`Gib`},{id:`c`,de:`Gebe`}],correct:`b`,explanationAr:`du gibst → Imperativ Gib! (مع تغيير e→i، بدون -st).`},{id:`t-im-2`,promptDe:`____ Sie bitte hier! (warten)`,options:[{id:`a`,de:`Wartet`},{id:`b`,de:`Warten`},{id:`c`,de:`Wart`}],correct:`b`,explanationAr:`صيغة Sie: Warten Sie! (Inversion).`},{id:`t-im-3`,promptDe:`____ ____, bitte! (du, aufstehen)`,options:[{id:`a`,de:`Aufsteh`},{id:`b`,de:`Steh auf`},{id:`c`,de:`Aufstehe`}],correct:`b`,explanationAr:`الفعل القابل للفصل: البادئة تنفصل في الـImperativ.`}]},{topicId:`reflexive`,greeting:`Reflexive Verben — wenn der Täter sich selbst trifft!`,storyAr:`الفعل الانعكاسي مثل **مرآة**: الفاعل يفعل شيئاً في نفسه. "Ich wasche **mich**" (أغسل **نفسي**). في الألمانيّة، يجب وضع ضمير انعكاسي (mich/dich/sich/uns/euch/sich) — لا يُحذَف كما في العربيّة.`,mnemonicAr:`**ضمائر Akkusativ الانعكاسيّة: mich, dich, sich, uns, euch, sich.** ضمائر Dativ: mir, dir, sich, uns, euch, sich.`,mnemonicDe:`sich (3. Person, Sg+Pl) ist die einzige eigene Form!`,steps:[{titleAr:`1️⃣ Akkusativ-reflexiv (الأكثر شيوعاً)`,de:`sich freuen, sich ärgern, sich erinnern, sich beeilen, sich entspannen`,ar:`الضمير الانعكاسي = مفعول مباشر. "Ich freue mich auf den Urlaub."`},{titleAr:`2️⃣ Dativ-reflexiv (مع جزء من الجسم/شيء يخصّ الفاعل)`,de:`sich die Hände waschen → Ich wasche mir die Hände.`,ar:`لمّا الفعل له مفعول مباشر آخر (Akk)، الضمير الانعكاسي ينقلب إلى Dativ. "Ich kaufe **mir** ein Auto."`},{titleAr:`3️⃣ موقع الضمير في الجملة`,de:`Ich freue mich.   ·   Hauptsatz: nach dem Verb.   ·   Nebensatz: dass ich mich freue.`,ar:`الضمير الانعكاسي يأتي مباشرة بعد الفعل المُصرَّف في الـHauptsatz، وبعد الفاعل في الـNebensatz.`},{titleAr:`4️⃣ مع حروف الجرّ الثابتة`,de:`sich freuen auf + Akk (سعيد بالمستقبل)   ·   sich freuen über + Akk (سعيد بشيء حدث)`,ar:`كلّ فعل انعكاسي يأتي مع حرف جرّ محدّد. احفظ الفعل + حرف الجرّ كقطعة واحدة.`}],advancedPatterns:[{title:`الفرق بين sich freuen auf و sich freuen über`,de:`auf = حدث مستقبليّ   ·   über = حدث ماضٍ/حالي`,ar:`Ich freue mich **auf** den Urlaub (لم يبدأ). Ich freue mich **über** das Geschenk (حصلت عليه).`},{title:`reziproke Bedeutung (متبادَلة)`,de:`Wir treffen uns. (= نلتقي معاً)   ·   Sie kennen sich. (= يعرفان بعضهما)`,ar:`مع الجمع، الضمير الانعكاسي قد يعني "بعضهم بعضاً" (= einander).`},{title:`الفعل الانعكاسي vs غير الانعكاسي`,de:`erinnern: jdn an etw → Ich erinnere ihn an den Termin.   ·   sich erinnern an etw → Ich erinnere mich an den Termin.`,ar:`بعض الأفعال لها صيغتان. "أُذكِّره" = erinnern + Akk. "أتذكّر" = sich erinnern + an.`},{title:`في Perfekt: ضمير الانعكاس يبقى`,de:`Ich habe mich gefreut.   ·   Wir haben uns getroffen.`,ar:`لا يضيع الضمير الانعكاسي في Partizip II. يأتي بين الفعل المساعد والـPartizip.`}],examWisdom:`في رسالة الامتحان، استعمل فعلاً انعكاسيّاً واحداً على الأقلّ في الافتتاح: "Ich freue mich, von Ihnen zu hören." أو "Ich entschuldige mich für die Verspätung." — جمل بليغة جاهزة.`,advancedExercises:[{id:`t-rf-1`,promptDe:`Ich freue ____ ____ den Urlaub.`,options:[{id:`a`,de:`mich / über`},{id:`b`,de:`mich / auf`},{id:`c`,de:`mir / auf`}],correct:`b`,explanationAr:`sich freuen auf + Akk (للمستقبل). الإجازة لم تبدأ.`},{id:`t-rf-2`,promptDe:`Wir treffen ____ um 18 Uhr.`,options:[{id:`a`,de:`sich`},{id:`b`,de:`uns`},{id:`c`,de:`euch`}],correct:`b`,explanationAr:`wir → uns. هنا معنى متبادَل: "نلتقي معاً".`},{id:`t-rf-3`,promptDe:`Ich kaufe ____ ein neues Hemd.`,options:[{id:`a`,de:`mich`},{id:`b`,de:`mir`},{id:`c`,de:`sich`}],correct:`b`,explanationAr:`الفعل له مفعول مباشر (Hemd, Akk) → الضمير الانعكاسي Dativ: mir.`}]},{topicId:`futur`,greeting:`Futur I — die Zukunft auf Deutsch!`,storyAr:`الـFutur I (المستقبل) في الألمانيّة **أقلّ استعمالاً** ممّا تظنّ. في الكلام اليومي، الألمان يستخدمون **المضارع + ظرف زمن** للمستقبل: "Morgen gehe ich ins Kino." (سأذهب غداً للسينما — حرفيّاً: "غداً أذهب للسينما"). الـFutur I محجوز لـ(1) التنبّؤات (2) التخمين (3) الوعود.`,mnemonicAr:`**werden + Infinitiv (في النهاية).** للأحداث المخطّط لها، استخدم المضارع. للتنبّؤ والوعد، استخدم Futur I.`,mnemonicDe:`Plan = Präsens + Zeitangabe.   Vorhersage / Versprechen = werden + Infinitiv.`,steps:[{titleAr:`1️⃣ تشكيل Futur I`,de:`Ich werde morgen kommen.   ·   Sie wird Erfolg haben.`,ar:`werden مُصرَّف في الموقع 2 + Infinitiv في النهاية. مثل "Satzklammer" (قوس الجملة).`},{titleAr:`2️⃣ المضارع للمستقبل المُؤكَّد`,de:`Morgen fahre ich nach Berlin.   (NICHT: Morgen werde ich nach Berlin fahren.)`,ar:`لمّا تخطّط لشيء مؤكّد + ظرف زمن واضح → المضارع كافٍ. الألمان يفضّلون هذه الصيغة في الكلام.`},{titleAr:`3️⃣ Futur I للتنبّؤ والتخمين`,de:`Es wird morgen regnen.   ·   Er wird wohl krank sein.`,ar:`"wohl" أو "wahrscheinlich" مع Futur I = تخمين قويّ ("أعتقد أنّه ...").`},{titleAr:`4️⃣ Futur I للوعد والقرار`,de:`Ich werde es nicht vergessen!   ·   Ich werde dich besuchen.`,ar:`لمّا تعد بشيء بقوّة → Futur I. أكثر إقناعاً من المضارع.`}],advancedPatterns:[{title:`Futur II (الماضي في المستقبل)`,de:`Bis Sonntag werde ich das Buch gelesen haben.`,ar:`werden + Partizip II + haben/sein. للحدث الذي سينتهي قبل وقت معيّن في المستقبل. نادر لكن أنيق.`},{title:`Futur I للتخمين عن الحاضر`,de:`Wo ist Anna? — Sie wird im Garten sein. (= ربّما هي في الحديقة الآن)`,ar:`استعمال خادع! Futur I + "wohl" يمكن أن يصف **الحاضر** كتخمين، لا المستقبل.`},{title:`in einem Monat / in zwei Jahren`,de:`In einem Monat werde ich umziehen.`,ar:`"in" + Akk = ظرف زمني للمستقبل. شائع جدّاً مع Futur I أو المضارع.`}],examWisdom:`في Sprechen B1، اخلط: استخدم المضارع للأحداث المؤكّدة، Futur I للوعود وللتعبير عن أهداف المستقبل البعيد. مثال: "Im nächsten Jahr werde ich versuchen, die telc-Prüfung zu bestehen."`,advancedExercises:[{id:`t-ft-1`,promptDe:`Morgen ____ ich nach Berlin ____.`,options:[{id:`a`,de:`fahre / —`},{id:`b`,de:`werde / fahren`},{id:`c`,de:`gehe / fahren`}],correct:`a`,explanationAr:`مضارع + ظرف زمن (morgen) كافٍ للمستقبل المؤكّد. أكثر طبيعيّة من Futur I هنا.`},{id:`t-ft-2`,promptDe:`Es ____ wahrscheinlich morgen ____.`,options:[{id:`a`,de:`regnet / —`},{id:`b`,de:`wird / regnen`},{id:`c`,de:`wirde / regnen`}],correct:`b`,explanationAr:`"wahrscheinlich" يدلّ على تخمين → Futur I أنسب من المضارع.`},{id:`t-ft-3`,promptDe:`Ich verspreche dir, dass ich dir ____ ____.`,options:[{id:`a`,de:`helfe / —`},{id:`b`,de:`werde / helfen`},{id:`c`,de:`helfen / werde`}],correct:`c`,explanationAr:`في Nebensatz (dass-Satz)، الفعل في النهاية → Infinitiv + werde. وعد قويّ.`}]},{topicId:`indirekte-rede`,greeting:`Indirekte Rede — wenn andere sprechen!`,storyAr:`الكلام غير المباشر هو **نقل قول شخص آخر**. مثل ساعي بريد ينقل رسالة. في الألمانيّة، تُستخدَم صيغة Konjunktiv I في الإعلام والكتب الرسميّة، لكن في الكلام اليومي يكفي dass-Satz بسيط.`,mnemonicAr:`**في الإعلام/الرسميّ: Konjunktiv I.** **في الكلام اليومي: "Er sagte, dass ..."** البساطة هي الأفضل في B1.`,mnemonicDe:`Schriftlich: Konjunktiv I.   Mündlich: dass-Satz im Indikativ.`,steps:[{titleAr:`1️⃣ الصيغة البسيطة (B1): dass + Indikativ`,de:`Direkt: "Ich bin krank."   →   Indirekt: Er sagt, dass er krank ist.`,ar:`الأبسط والأشيع. الفعل في النهاية. قاعدة Nebensatz.`},{titleAr:`2️⃣ Konjunktiv I (للكتابة الرسميّة + الإعلام)`,de:`Direkt: "Er ist krank."   →   Konjunktiv I: Er sei krank.`,ar:`sein → sei (الشكل الوحيد المنتظم). باقي الأفعال: جذر + e (er habe, er gehe). نادر في الكلام.`},{titleAr:`3️⃣ Konjunktiv II بديل (لمّا Konj I = Indikativ)`,de:`Direkt: "Sie kommen."   →   Konj I (kommen) = Indikativ → استخدم Konj II: Sie kämen.`,ar:`لمّا Konjunktiv I يساوي Indikativ شكلاً (الجمع غالباً)، نستخدم Konjunktiv II بدلاً منه. القاعدة الذهبيّة في الإعلام.`},{titleAr:`4️⃣ تغيير الضمائر والظروف`,de:`Er sagt: "Ich gehe heute."   →   Er sagt, dass er heute geht.   (ich → er, مع تغيير الفعل)`,ar:`الضمائر تتغيّر حسب من ينقل القول. "heute" يبقى لو ما زال اليوم نفسه. لو يوم مختلف → "an dem Tag".`}],advancedPatterns:[{title:`الأسئلة غير المباشرة`,de:`Direkt: "Kommst du?"   →   Er fragt, ob ich komme.   ·   "Wann kommst du?" → Er fragt, wann ich komme.`,ar:`سؤال نعم/لا → "ob". سؤال W- (wann/wo/wer) → نفس كلمة السؤال. الفعل في النهاية.`},{title:`الأمر غير المباشر`,de:`Direkt: "Komm!"   →   Indirekt: Er sagt, ich solle kommen.   (أو: Er sagt, dass ich kommen soll.)`,ar:`sollen + Infinitiv = الأمر غير المباشر. ينقل المعنى دون "أمر" مباشر.`},{title:`تغيير الزمن (Zeitenverschiebung)`,de:`Direkt: "Ich war krank."   →   Indirekt: Er sagte, er sei krank gewesen.`,ar:`الـPräteritum/Perfekt → Konjunktiv I + Partizip II. نادر، لكن مهمّ في الكتابة الرسميّة.`}],examWisdom:`في Schreiben B1 (الرسالة)، البساطة كافية: "Mein Freund hat gesagt, dass ..." — لا تتكلّف الـKonjunktiv I إلّا في B2 وما فوق.`,advancedExercises:[{id:`t-ir-1`,promptDe:`Sie sagt: "Ich komme heute."   →   Sie sagt, dass sie heute ____.`,options:[{id:`a`,de:`kommt`},{id:`b`,de:`käme`},{id:`c`,de:`kommen`}],correct:`a`,explanationAr:`في Nebensatz البسيط: المضارع + الفعل في النهاية. käme هو Konjunktiv II، أرقى لكن غير مطلوب في B1.`},{id:`t-ir-2`,promptDe:`Er fragt: "Wo wohnst du?"   →   Er fragt, ____ ich ____.`,options:[{id:`a`,de:`ob / wohne`},{id:`b`,de:`wo / wohne`},{id:`c`,de:`wo / wohnt`}],correct:`b`,explanationAr:`سؤال W- يحتفظ بكلمة السؤال. الفعل ينطبق مع الفاعل (ich → wohne) ويذهب للنهاية.`}]},{topicId:`plural`,greeting:`Plural — die Vielfalt der deutschen Endungen!`,storyAr:`في الألمانيّة، الجمع **لا يتبع قاعدة واحدة**. عربياً نقول "كتاب → كتب" بقاعدة. ألمانيّاً، 5 نهايات مختلفة (-e, -er, -en, -s, لا شيء) + Umlaut أحياناً. لكن: مع كلّ كلمة جديدة، **احفظ الأداة + الجمع** كقطعة واحدة.`,mnemonicAr:`**القاعدة الأهمّ: في Plural، كلّ الأدوات تصبح "die".** der Mann/die Frau/das Kind → die Männer/die Frauen/die Kinder.`,mnemonicDe:`Im Plural: alles wird DIE!`,steps:[{titleAr:`1️⃣ النهايات الخمس`,de:`-e: Tisch → Tische   ·   -er: Kind → Kinder   ·   -en: Frau → Frauen   ·   -s: Auto → Autos   ·   ∅: Lehrer → Lehrer`,ar:`كلّ نهاية لها نمط. -e للمذكّر القصير. -er للمحايد القصير + Umlaut. -en للمؤنّث. -s للكلمات الأجنبيّة. ∅ للمنتهية بـ-er/-el/-en/-chen/-lein.`},{titleAr:`2️⃣ Umlaut (a→ä, o→ö, u→ü, au→äu)`,de:`Mann → Männer   ·   Mutter → Mütter   ·   Buch → Bücher   ·   Haus → Häuser`,ar:`كثير من الأسماء تأخذ Umlaut في الجمع. ليس قاعدة صارمة، لكن شائع مع المذكّر والمحايد.`},{titleAr:`3️⃣ Dativ Plural: + n`,de:`mit den Kindern   ·   bei den Männern   ·   außer den Frauen`,ar:`في Dat Plural، نضيف -n إذا الجمع لا ينتهي بـ-n أو -s. هذه قاعدة "اختفاء سهلة" في الكلام.`},{titleAr:`4️⃣ كلمات بدون مفرد أو جمع`,de:`der Käse (لا جمع)   ·   die Eltern (لا مفرد)   ·   die Leute (لا مفرد)`,ar:`بعض الكلمات تُستخدَم فقط في صيغة واحدة. الـ"Singularetantum" (مفرد فقط) و"Pluraletantum" (جمع فقط).`}],advancedPatterns:[{title:`Plural مزدوج (للمعنى)`,de:`die Worte (الكلمات/الجملة)   ≠   die Wörter (المفردات في القاموس)`,ar:`بعض الكلمات لها جمعان بمعنيين مختلفين. Wort → Worte/Wörter, Bank → Banken/Bänke.`},{title:`كلمات أجنبيّة (-s vs -en)`,de:`das Auto → die Autos   ·   das Hotel → die Hotels   ·   das Thema → die Themen`,ar:`الكلمات اللاتينيّة (-um, -us, -a) تتبع قواعد لاتينيّة: Thema → Themen, Datum → Daten, Visum → Visa/Visen.`},{title:`Sammelnamen (أسماء جامعة)`,de:`das Obst (الفاكهة جميعها)   ·   das Gemüse (الخضار)   ·   die Polizei (الشرطة كمؤسّسة)`,ar:`هذه الكلمات تُستعمَل بصيغة المفرد لكن تشير إلى مجموعة. لا جمع لها عادة.`}],examWisdom:`حِيلة الامتحان: تعلَّم كلّ اسم جديد بصيغة "der/die/das + الاسم + الجمع". مثلاً: "der Tisch, die Tische". ثلاثة معلومات في "كلمة" واحدة.`,advancedExercises:[{id:`t-pl-1`,promptDe:`Ein Kind, zwei ____.`,options:[{id:`a`,de:`Kinde`},{id:`b`,de:`Kinder`},{id:`c`,de:`Kinden`}],correct:`b`,explanationAr:`das Kind → die Kinder (-er + Umlaut نظريّاً، لكن لا Umlaut هنا).`},{id:`t-pl-2`,promptDe:`Ich helfe den ____.`,options:[{id:`a`,de:`Kinder`},{id:`b`,de:`Kindern`},{id:`c`,de:`Kinders`}],correct:`b`,explanationAr:`helfen + Dativ. Plural Dativ → +n: Kindern.`},{id:`t-pl-3`,promptDe:`Im Café gibt es viele ____.`,options:[{id:`a`,de:`Kuchens`},{id:`b`,de:`Kuchen`},{id:`c`,de:`Kuchene`}],correct:`b`,explanationAr:`der Kuchen → die Kuchen (لا تغيير، لأنّه ينتهي بـ-en).`}]},{topicId:`konnektoren`,greeting:`Konnektoren — die Brücken zwischen Sätzen!`,storyAr:`الـKonnektoren (روابط الجمل) هي **الجسور** التي تربط الأفكار. كلّ Konnektor له **تأثير على ترتيب الكلمات**: بعضها يبقي الفعل في الموقع 2 (und, aber, denn)، بعضها يقلب الجملة (deshalb, trotzdem)، وبعضها يرسل الفعل للنهاية (weil, obwohl, dass).`,mnemonicAr:`**3 أنواع: ADUSO (لا تغيّر) + Konjunktionaladverbien (Inversion) + Subjunktionen (Verb am Ende).**`,mnemonicDe:`ADUSO: aber/denn/und/sondern/oder — Hauptsatz bleibt!`,steps:[{titleAr:`1️⃣ ADUSO (Konjunktionen — لا تغيير)`,de:`aber, denn, und, sondern, oder`,ar:`هذه الـ5 لا تغيّر ترتيب الجملة. الفعل يبقى في الموقع 2. مثل العربيّة "و، لكن، أو".`},{titleAr:`2️⃣ Konjunktionaladverbien (Inversion)`,de:`deshalb, trotzdem, dann, danach, außerdem, sonst`,ar:`هذه تأخذ الموقع 1 من الجملة الجديدة، فالفعل يأتي في الموقع 2 → Inversion: "Es regnet. Trotzdem **gehe** ich raus."`},{titleAr:`3️⃣ Subjunktionen (Verb am Ende)`,de:`weil, dass, wenn, als, ob, obwohl, damit, falls`,ar:`تبدأ Nebensatz. الفعل في النهاية. + فاصلة قبل الـNebensatz.`},{titleAr:`4️⃣ نمط لكلّ علاقة منطقيّة`,de:`سبب: weil/denn/deshalb   ·   تناقض: aber/obwohl/trotzdem   ·   هدف: damit/um...zu`,ar:`لكلّ علاقة 3 خيارات مختلفة في القواعد. اختر حسب أين تضع الجزء الأهمّ.`}],advancedPatterns:[{title:`um ... zu (هدف بنفس الفاعل)`,de:`Ich lerne Deutsch, um in Deutschland zu arbeiten.`,ar:`لو الفاعل واحد → um...zu أنيق. لو الفاعلان مختلفان → damit + Nebensatz.`},{title:`انتبه! "denn" vs "weil"`,de:`denn: Hauptsatz (Verb auf Pos 2)   ·   weil: Nebensatz (Verb am Ende)`,ar:`"Ich komme nicht, denn ich **bin** krank." vs "..., weil ich krank **bin**." — كلاهما "لأنّ" لكنّ القواعد مختلفة.`},{title:`"sondern" vs "aber"`,de:`sondern (بل) فقط بعد نفي + استبدال   ·   aber (لكن) للتباين العام`,ar:`"Nicht ich, **sondern** er." (ليس أنا، **بل** هو). "Er ist klein, **aber** stark."`},{title:`zweiteilige Konnektoren`,de:`sowohl ... als auch (كلاهما)   ·   weder ... noch (لا ... ولا)   ·   entweder ... oder (إمّا ... أو)   ·   nicht nur ... sondern auch`,ar:`هذه الروابط المُزدوَجة ترفع المستوى اللغوي. حفظ 4 منها يكفي للامتحان.`}],examWisdom:`في Schreiben B1، استخدم 4 Konnektoren مختلفة في رسالة قصيرة: weil, deshalb, aber, obwohl. هذا يُظهر تنوّعاً وفهماً للقواعد.`,advancedExercises:[{id:`t-kn-1`,promptDe:`Es regnet. ____ ich gehe spazieren.`,options:[{id:`a`,de:`Trotzdem`},{id:`b`,de:`Obwohl`},{id:`c`,de:`Aber`}],correct:`a`,explanationAr:`بداية الجملة الجديدة + الفعل في الموقع 2 → Trotzdem + Inversion.`},{id:`t-kn-2`,promptDe:`Er ist arm, ____ glücklich.`,options:[{id:`a`,de:`sondern`},{id:`b`,de:`aber`},{id:`c`,de:`denn`}],correct:`b`,explanationAr:`تباين عادي → aber. sondern تتطلّب نفي قبلها.`},{id:`t-kn-3`,promptDe:`Ich lerne Deutsch, ____ in Deutschland zu arbeiten.`,options:[{id:`a`,de:`damit`},{id:`b`,de:`um`},{id:`c`,de:`weil`}],correct:`b`,explanationAr:`الفاعل واحد (ich) → um...zu. damit يحتاج فاعلاً مختلفاً.`}]},{topicId:`praepositionen-liste`,greeting:`Präpositionen — die kleinen Wörter mit großer Wirkung!`,storyAr:`حروف الجرّ في الألمانيّة **تحدّد الحالة**. اعتبرها 3 مجموعات: **DOGFU = Akk دائماً، ABMNSVZ = Dat دائماً، Wechselpräpositionen = حسب المعنى.** حفظ هذين الاختصارين يحلّ 80% من مشكلاتك.`,mnemonicAr:`**DOGFU (Akk): durch, ohne, gegen, für, um.** **ABMNSVZ (Dat): aus, bei, mit, nach, seit, von, zu.** **Wechsel: an, auf, in, hinter, neben, über, unter, vor, zwischen.**`,mnemonicDe:`DOGFU = Akk   ·   ABMNSVZ = Dat   ·   Wechsel = beides`,steps:[{titleAr:`1️⃣ DOGFU (Akkusativ ثابت)`,de:`durch (عبر) · ohne (بدون) · gegen (ضدّ) · für (من أجل) · um (حول/في الساعة)`,ar:`هذه الـ5 تأخذ Akk في كلّ الحالات. مثال: "für meinen Bruder" (Akk).`},{titleAr:`2️⃣ ABMNSVZ (Dativ ثابت)`,de:`aus, bei, mit, nach, seit, von, zu  + außer + gegenüber`,ar:`الأشيع: aus (من — مكان أصلي)، mit (مع)، nach (إلى — للمدن/البلدان)، von (من — أقلّ من aus)، zu (إلى — أشخاص/أحداث).`},{titleAr:`3️⃣ Wechselpräpositionen (Akk أو Dat)`,de:`an, auf, hinter, in, neben, über, unter, vor, zwischen`,ar:`Wohin? → Akk. Wo? → Dat. هذه القاعدة الذهبيّة. درس منفصل.`},{titleAr:`4️⃣ Genitiv-Präpositionen (رسمي)`,de:`während, wegen, trotz, statt, innerhalb, außerhalb, anstelle, anhand`,ar:`هذه تأخذ Genitiv في الكتابة الرسميّة. في الكلام، وكثيراً wegen/trotz تأخذ Dativ (شائع لكن غير رسمي).`}],advancedPatterns:[{title:`nach vs zu vs in (إلى)`,de:`nach + بلد/مدينة بدون أداة (nach Berlin)   ·   zu + شخص/حدث (zum Arzt)   ·   in + بناء/بلد بأداة (in die Stadt, in die Schweiz)`,ar:`الأخطر! "إلى" تتغيّر حسب الوجهة. حفظ هذه الفروق ضروريّ.`},{title:`aus vs von`,de:`aus + بلد/مدينة (Ich komme aus Syrien.)   ·   von + شخص/حدث (Ich komme von der Arbeit.)`,ar:`aus = من مكان أصلي/جنسيّتي. von = من شخص أو موقع مؤقّت.`},{title:`Kontraktionen (zum, zur, im, am, ans, beim, ...)`,de:`zu dem = zum   ·   zu der = zur   ·   in dem = im   ·   in das = ins   ·   an dem = am   ·   bei dem = beim`,ar:`في الكلام، تُدمَج الأداة مع حرف الجرّ. في الكتابة الرسميّة استخدم الكاملة.`},{title:`الزمن مع حروف الجرّ`,de:`um 8 Uhr (الساعة)   ·   am Montag (يوم)   ·   im Januar (شهر)   ·   im Sommer (فصل)   ·   in 2 Stunden (مدّة)`,ar:`لكلّ نوع زمن حرف جرّ مختلف. um للساعة، am ليوم، im لشهر/فصل/سنة، in لمدّة مستقبليّة.`}],examWisdom:`احفظ DOGFU وABMNSVZ كقصيدتين. كرّرهما يوميّاً لأسبوع. ستوفّر 30% من أخطائك القواعديّة في الامتحان.`},{topicId:`n-deklination`,greeting:`N-Deklination — die schwachen Maskulina!`,storyAr:`الـN-Deklination (التصريف الضعيف) هو **سرّ صغير** يُكشَف به مستوى الـB1+. مجموعة من الأسماء المذكّرة تأخذ -n/-en في **كلّ** الحالات ما عدا Nominativ. مثل der Junge → den Jungen (Akk). مَن لا يعرف هذا، يخطئ في الامتحان.`,mnemonicAr:`**N-Deklination = أسماء مذكّرة تأخذ -n/-en في كلّ الحالات.** القائمة محدودة (~50 كلمة)، لكنّها شائعة جدّاً.`,mnemonicDe:`N-Maskulina: + n/-en außer Nominativ Singular!`,steps:[{titleAr:`1️⃣ القائمة الذهبيّة (الأكثر شيوعاً)`,de:`der Junge, der Herr, der Kollege, der Kunde, der Nachbar, der Polizist, der Tourist, der Student, der Mensch, der Held`,ar:`هذه ~10 أسماء. كلّ ما ينتهي بـ-e/-ist/-ent/-ant/-loge في المذكّر = N-Deklination.`},{titleAr:`2️⃣ التصريف`,de:`Nom: der Junge   ·   Akk: den Jungen   ·   Dat: dem Jungen   ·   Gen: des Jungen`,ar:`فقط Nom Sg لا تأخذ -n. كلّ شيء آخر -n. (الـ"Herr" استثناء: Akk/Dat: den Herrn، Gen: des Herrn — مع r واحد).`},{titleAr:`3️⃣ الحفظ بالنمط`,de:`Berufe: Jurist, Polizist, Tourist (-ist)   ·   Soziolog, Bilog, Geolog (-loge)   ·   Student, Praktikant, Patient (-ent/-ant)`,ar:`كثير من المهن تتبع N-Deklination. حفظ النهاية + جنس الاسم يكفي.`},{titleAr:`4️⃣ مع der "Name" (شاذّ)`,de:`der Name → den Namen (Akk) → des Namens (Gen — مع s إضافيّة)`,ar:`der Name مزدوج: -n في كلّ الحالات + s في Genitiv. أيضاً: der Buchstabe, der Frieden, der Glaube.`}],advancedPatterns:[{title:`الكلمات الأجنبيّة (Tourist, Polizist)`,de:`der Tourist → den Touristen, dem Touristen, des Touristen`,ar:`هذه قياس على القواعد العامّة لـN-Deklination. حفظ الجنس + النهاية يكفي.`},{title:`لا تخلط مع الأسماء الانثوية`,de:`die Sonne (مؤنّث -e) لا تتبع N-Deklination!`,ar:`القاعدة فقط للمذكّر! die Frage, die Sonne, die Liebe → جمع عادي.`}],examWisdom:`في Schreiben، إذا كتبت "Ich treffe den Polizist" بدل "den Polizisten" → خطأ يُقرأ على أنّك تجاوزت B1. تَعلَّم 10 كلمات N-Deklination الأكثر شيوعاً.`},{topicId:`adverbien`,greeting:`Adverbien und TeKaMoLo — die Reihenfolge im Mittelfeld!`,storyAr:`لمّا تكتب جملة فيها عدّة ظروف، **ترتيبها يتبع نمطاً ثابتاً: TeKaMoLo!** تَ + كَ + مو + لو = **Te**mporal (متى) + **Ka**usal (لماذا) + **Mo**dal (كيف) + **Lo**kal (أين).`,mnemonicAr:`**TeKaMoLo: متى → لماذا → كيف → أين.** هذا الترتيب القياسي في Mittelfeld (الوسط بين الفعل والمفعول).`,mnemonicDe:`TeKaMoLo:   Te-mporal → Ka-usal → Mo-dal → Lo-kal`,steps:[{titleAr:`1️⃣ Temporal (متى) — wann?`,de:`gestern, heute, morgen, jetzt, oft, manchmal, immer, nie`,ar:`الزمن دائماً يأتي **أوّلاً** في Mittelfeld. "Ich gehe **morgen** zur Arbeit."`},{titleAr:`2️⃣ Kausal (لماذا) — warum?`,de:`wegen des Wetters, deshalb, aus Liebe, vor Angst`,ar:`السبب يأتي ثانياً. أقلّ شيوعاً في Mittelfeld لأنّه عادة Nebensatz.`},{titleAr:`3️⃣ Modal (كيف) — wie?`,de:`gerne, schnell, mit dem Auto, allein, leise`,ar:`الكيف يأتي ثالثاً. يشمل "مع" (mit dem Auto = بالسيّارة)، الوسائل، الأسلوب.`},{titleAr:`4️⃣ Lokal (أين) — wo / wohin?`,de:`in Berlin, nach Hause, ins Kino, oben, hier`,ar:`المكان دائماً **آخر** ظرف في Mittelfeld. يأتي قبل المفعولات الفعليّة.`}],advancedPatterns:[{title:`الجملة الكاملة بـTeKaMoLo`,de:`Ich fahre morgen wegen der Arbeit mit dem Auto nach Berlin.`,ar:`4 ظروف بترتيب مثالي: Te(morgen) + Ka(wegen der Arbeit) + Mo(mit dem Auto) + Lo(nach Berlin).`},{title:`Inversion: ظرف في الموقع 1`,de:`Morgen fahre ich nach Berlin.   ·   Im Kino habe ich ihn getroffen.`,ar:`إذا بدأت بظرف، الفعل يأتي في الموقع 2 (Inversion). قاعدة V2 الحديديّة.`},{title:`الضمائر تأتي قبل TeKaMoLo`,de:`Ich gebe es ihm morgen.   (Pronomen → TeKaMoLo)`,ar:`الضمائر (es, ihm, mich) تأتي **قبل** كلّ الظروف. عكس الأسماء التي تتبع TeKaMoLo.`},{title:`الـMittelfeld المُكتمَل`,de:`Verb مُصرَّف + Pronomen + TeKaMoLo + Akk-Objekt + Verb غير مُصرَّف`,ar:`هذا "بناء" الجملة الألمانيّة الكامل. حفظه يضمن جمل صحيحة 100%.`}],examWisdom:`في Schreiben، اكتب جملة واحدة فيها 3 ظروف على الأقلّ بترتيب TeKaMoLo. مثال: "Wir fahren am Wochenende mit dem Zug nach München." — Te + Mo + Lo. علامة كاملة في "بناء الجملة".`},{topicId:`da-wo-komposita`,greeting:`Da- und Wo-Komposita — wenn Pronomen auf Präpositionen treffen!`,storyAr:`لمّا تريد قول "**عنه**" أو "**عليها**" لشيء غير عاقل في الألمانيّة، لا تستخدم "**für ihn**" — استخدم "**dafür**" (= له/عنه). نفس الفكرة للسؤال: "**على ماذا؟**" = "**worauf?**" بدل "auf was?". هذه قاعدة لا توجد في العربيّة.`,mnemonicAr:`**da + Präposition = إشارة لشيء غير عاقل.** **wo + Präposition = سؤال عن شيء غير عاقل.** + r إذا الحرف يبدأ بحرف علّة (darauf, woran).`,mnemonicDe:`da + Präp = "es" für Sachen   ·   wo + Präp = "was" für Sachen   (+r vor Vokal)`,steps:[{titleAr:`1️⃣ التشكيل الأساسي`,de:`für + es → dafür   ·   mit + ihm → damit   ·   über + es → darüber   ·   auf + es → darauf`,ar:`da + Präp. إذا الـPräp يبدأ بحرف علّة (auf, an, in, über, um, unter) → da**r**+Präp.`},{titleAr:`2️⃣ السؤال — Wo-Komposita`,de:`für was → wofür   ·   mit was → womit   ·   auf was → worauf   ·   über was → worüber`,ar:`wo + Präp بنفس القاعدة. تُستخدَم في الأسئلة عن غير العاقل.`},{titleAr:`3️⃣ الفرق بين العاقل وغير العاقل`,de:`Ich denke an meinen Bruder. → Ich denke an ihn.   ·   Ich denke an die Prüfung. → Ich denke daran.`,ar:`العاقل: ضمير عادي (ihn, sie). غير العاقل: da-Komposita (daran, davon, ...). فرق دقيق لكنّه أساسي.`},{titleAr:`4️⃣ في الـNebensatz بـdass`,de:`Ich freue mich darauf, dass du kommst.   ·   Ich denke daran, dass es regnet.`,ar:`الـda-Komposita تشير إلى dass-Satz كاملاً. كأنّها تقول "على هذا: أنّك تأتي". تركيب راقٍ جدّاً.`}],advancedPatterns:[{title:`الأفعال الانعكاسيّة + da-Komposita`,de:`sich freuen auf → Ich freue mich darauf.   ·   sich erinnern an → Ich erinnere mich daran.`,ar:`كلّ فعل انعكاسي + Präp يستخدم da-Komposita لو الإشارة لشيء غير عاقل أو لجملة كاملة.`},{title:`wo-Komposita في الـRelativsatz`,de:`Das Buch, wovon ich gesprochen habe ...   ·   Das Thema, worüber wir geredet haben ...`,ar:`بدل "über das/von dem" مع غير العاقل، نستخدم wo-Komposita. شائع في الكتابة الراقية.`},{title:`تركيبات شائعة كاملة`,de:`damit (لكي/معه/به)   ·   dazu (لذلك)   ·   davon (عنه)   ·   dafür (له/مقابله)   ·   dabei (مع ذلك)`,ar:`بعض da-Komposita لها معاني خاصّة كأدوات ربط: "damit" مثلاً = "لكي" (Subjunktion).`}],examWisdom:`في Schreiben B1، استخدم "Ich freue mich darauf, ..." في الفقرة الأخيرة من الرسالة. مثال جاهز: "Ich freue mich darauf, von Ihnen zu hören." علامة بليغة جاهزة.`,advancedExercises:[{id:`t-dw-1`,promptDe:`Ich denke oft an die Prüfung. = Ich denke oft ____.`,options:[{id:`a`,de:`an sie`},{id:`b`,de:`daran`},{id:`c`,de:`davon`}],correct:`b`,explanationAr:`die Prüfung غير عاقل + an → daran (مع r لأنّ an يبدأ بحرف علّة).`},{id:`t-dw-2`,promptDe:`____ sprichst du? — Über das Wetter.`,options:[{id:`a`,de:`Über was`},{id:`b`,de:`Worüber`},{id:`c`,de:`Was über`}],correct:`b`,explanationAr:`سؤال عن غير عاقل → wo+Präp = worüber (مع r).`},{id:`t-dw-3`,promptDe:`Ich freue mich ____, ____ du kommst.`,options:[{id:`a`,de:`auf / dass`},{id:`b`,de:`darauf / dass`},{id:`c`,de:`darauf / wenn`}],correct:`b`,explanationAr:`sich freuen auf + Sache (غير عاقل) → darauf. ثمّ dass-Satz للتفاصيل.`}]}];function i(e){return r.find(t=>t.topicId===e)}var a=[{id:`b2-konjunktiv2`,titleAr:`Konjunktiv II — للأمنيات والافتراضات غير الواقعيّة`,titleDe:`Konjunktiv II (Gegenwart & Vergangenheit)`,summaryAr:`Konjunktiv II صيغة الشرط والأمنيّة في الألمانيّة. تُستخدم للأمنيات، الافتراضات غير الواقعيّة، الطلبات المؤدّبة، والندم على الماضي.`,arabicContrast:`في العربيّة نستخدم "لو" + جواب الشرط: "لو كان عندي وقت لذهبت". في الألمانيّة نحوّل الفعل لصيغة Konjunktiv II: "Wenn ich Zeit hätte, würde ich gehen". الفرق: معظم الأفعال تستخدم "würde + Infinitiv" بدل صيغة Konjunktiv II الأصليّة (إلّا haben/sein/werden والأفعال المساعدة الشكليّة — تبقى بصيغتها الأصليّة).`,whenToUseAr:`استخدم Konjunktiv II في:
• الأمنيات غير الواقعيّة (Wünsche): "Ich wäre jetzt lieber am Strand."
• الافتراضات (Hypothesen): "Wenn ich reich wäre, würde ich eine Weltreise machen."
• النصائح: "An deiner Stelle würde ich das nicht machen."
• الطلبات المؤدّبة: "Könnten Sie mir helfen?"
• الندم على الماضي: "Ich hätte besser lernen sollen."`,rules:[{title:`صيغة Konjunktiv II للحاضر`,contentAr:`**القاعدة العامّة:** würde + Infinitiv في نهاية الجملة.
**الاستثناءات (لا نستخدم würde معها):** haben → hätte، sein → wäre، werden → würde (نفسه)، können → könnte، müssen → müsste، sollen → sollte، dürfen → dürfte، wollen → wollte (نادر)، wissen → wüsste.`,examples:[{de:`Wenn ich Zeit hätte, würde ich dich besuchen.`,ar:`لو كان عندي وقت، لزرتك.`},{de:`Wenn er reich wäre, würde er eine Villa kaufen.`,ar:`لو كان غنيّاً، لاشترى فيلا.`},{de:`Könnten Sie mir bitte helfen?`,ar:`هل يمكنك مساعدتي من فضلك؟`},{de:`Ich hätte gerne einen Kaffee.`,ar:`أودّ قهوة من فضلك.`}]},{title:`صيغة Konjunktiv II للماضي`,contentAr:`**القاعدة:** hätte/wäre + Partizip II في نهاية الجملة. نستخدمها للتعبير عن ندم أو افتراض عن الماضي.`,examples:[{de:`Wenn ich mehr gelernt hätte, hätte ich die Prüfung bestanden.`,ar:`لو درستُ أكثر، لنجحتُ في الامتحان.`},{de:`Ich wäre gestern gerne gekommen, aber ich war krank.`,ar:`كنتُ أودّ أن آتي أمس، لكنّني كنتُ مريضاً.`},{de:`Du hättest anrufen sollen.`,ar:`كان عليك أن تتّصل.`}]},{title:`Konjunktiv II مع الأفعال الشكليّة (Modalverben)`,contentAr:`الأفعال الشكليّة **لا** تستخدم würde — نستعمل صيغتها الأصليّة: könnte, müsste, sollte, dürfte. في الماضي: **hätte ... + Modalverb + Infinitiv** (ترتيب خاص: mehrteilige Infinitivkonstruktion).`,examples:[{de:`Du solltest mehr schlafen.`,ar:`يجب أن تنام أكثر.`},{de:`Er könnte uns helfen, aber er will nicht.`,ar:`يمكنه مساعدتنا، لكنّه لا يريد.`},{de:`Ich hätte das machen müssen.`,ar:`كان عليّ فعل ذلك.`},{de:`Sie hätte anrufen können.`,ar:`كان بإمكانها الاتّصال.`}]}],commonMistakes:[{wrong:`Wenn ich Zeit habe, würde ich kommen.`,right:`Wenn ich Zeit hätte, würde ich kommen.`,explanationAr:`الجملة افتراضيّة → يجب استخدام Konjunktiv II في الشرط أيضاً (hätte وليس habe).`},{wrong:`Ich würde gerne einen Kaffee haben.`,right:`Ich hätte gerne einen Kaffee.`,explanationAr:`haben لا تُستخدم مع würde — نقول hätte مباشرة.`},{wrong:`Wenn ich reich gewesen hätte...`,right:`Wenn ich reich gewesen wäre...`,explanationAr:`sein في الماضي يأخذ wäre وليس hätte.`},{wrong:`Du hättest mir helfen gekonnt.`,right:`Du hättest mir helfen können.`,explanationAr:`مع Modalverb في ماضي Konjunktiv II، الفعل الشكلي يبقى Infinitiv (können) ولا يتحوّل إلى Partizip II.`}],tipsAr:[`تذكّر الشكل السريع: haben→hätte, sein→wäre, werden→würde, können→könnte, müssen→müsste.`,`للأفعال العادية، استخدم würde + Infinitiv دائماً لتجنّب الحفظ.`,`الماضي = hätte/wäre + Partizip II. مع Modalverb الماضي: hätte + Infinitiv + Modalverb-Infinitiv.`,`للطلبات المؤدّبة في المطعم/الفندق/العمل، استعمل: Könnte ich...? / Hätte ich gerne...? / Würden Sie mir...?`],exercises:[{id:`b2-k2-1`,promptAr:`اختر الصيغة الصحيحة:`,promptDe:`Wenn ich mehr Zeit ____, würde ich dich besuchen.`,options:[{id:`a`,de:`habe`},{id:`b`,de:`hätte`},{id:`c`,de:`würde haben`}],correct:`b`,explanationAr:`في الشرط الافتراضي نستخدم hätte (صيغة Konjunktiv II لـhaben).`},{id:`b2-k2-2`,promptAr:`أيّ صيغة مؤدّبة هي الأصحّ؟`,promptDe:`____ Sie mir bitte helfen?`,options:[{id:`a`,de:`Können`},{id:`b`,de:`Könnten`},{id:`c`,de:`Konnten`}],correct:`b`,explanationAr:`Könnten = Konjunktiv II لـkönnen — يُستخدم للطلبات المؤدّبة.`},{id:`b2-k2-3`,promptAr:`اختر الصي��ة الصحيحة (ندم على الماضي):`,promptDe:`Ich ____ besser lernen sollen.`,options:[{id:`a`,de:`hätte`},{id:`b`,de:`wäre`},{id:`c`,de:`würde`}],correct:`a`,explanationAr:`مع sollen في الماضي → hätte ... sollen (Modalverb في Infinitiv).`},{id:`b2-k2-4`,promptAr:`اختر الصيغة الصحيحة:`,promptDe:`Wenn er gestern nicht krank ____, wäre er gekommen.`,options:[{id:`a`,de:`gewesen hätte`},{id:`b`,de:`gewesen wäre`},{id:`c`,de:`gewesen ist`}],correct:`b`,explanationAr:`sein في ماضي Konjunktiv II = wäre + gewesen.`},{id:`b2-k2-5`,promptAr:`أيّ جملة صحيحة؟`,promptDe:``,options:[{id:`a`,de:`Ich würde mehr Geld haben.`},{id:`b`,de:`Ich hätte mehr Geld.`},{id:`c`,de:`Ich haben würde mehr Geld.`}],correct:`b`,explanationAr:`haben يأخذ hätte مباشرة بدون würde.`},{id:`b2-k2-6`,promptAr:`ما الصيغة الصحيحة؟`,promptDe:`An deiner Stelle ____ ich zum Arzt gehen.`,options:[{id:`a`,de:`gehe`},{id:`b`,de:`würde`},{id:`c`,de:`könne`}],correct:`b`,explanationAr:`النصيحة مع "an deiner Stelle" تستخدم würde + Infinitiv (gehen).`},{id:`b2-k2-7`,promptAr:`ماذا ينقص؟`,promptDe:`Du ____ anrufen können.`,options:[{id:`a`,de:`hättest`},{id:`b`,de:`wärst`},{id:`c`,de:`würdest`}],correct:`a`,explanationAr:`مع Modalverb في الماضي نستخدم hätte(st) + Infinitiv + Modalverb.`},{id:`b2-k2-8`,promptAr:`صحّح هذه الجملة:`,promptDe:`Ich würde gerne einen Kaffee haben.`,options:[{id:`a`,de:`الجملة صحيحة`},{id:`b`,de:`Ich hätte gerne einen Kaffee.`},{id:`c`,de:`Ich haben würde gerne einen Kaffee.`}],correct:`b`,explanationAr:`في الطلب المؤدّب نستعمل hätte gerne (شائع جداً) بدل würde haben.`},{id:`b2-k2-9`,promptAr:`أيّ صيغة Konjunktiv II صحيحة لـwissen؟`,promptDe:`Wenn ich das nur ____!`,options:[{id:`a`,de:`wisse`},{id:`b`,de:`würde wissen`},{id:`c`,de:`wüsste`}],correct:`c`,explanationAr:`wissen يأخذ wüsste (صيغة Konjunktiv II الأصليّة).`},{id:`b2-k2-10`,promptAr:`اختر:`,promptDe:`Wenn wir das früher ____, wäre alles anders gewesen.`,options:[{id:`a`,de:`gewusst hätten`},{id:`b`,de:`gewusst wären`},{id:`c`,de:`wissen würden`}],correct:`a`,explanationAr:`wissen يأخذ haben → الماضي = hätten + gewusst.`}]},{id:`b2-konjunktiv1`,titleAr:`Konjunktiv I — الكلام المنقول (Indirekte Rede)`,titleDe:`Konjunktiv I (Indirekte Rede)`,summaryAr:`Konjunktiv I يُستخدم لنقل كلام الآخرين بشكل غير مباشر (مهمّ جداً في الأخبار، الصحف، والكتابة الأكاديميّة).`,arabicContrast:`في العربيّة نستخدم "قال إنّ" + الكلام كما هو: "قال إنّه مريض". في الألمانيّة نحوّل الفعل لـKonjunktiv I: "Er sagte, er sei krank". الهدف هو التأكيد على أنّ هذا كلام منقول وليس رأي المتكلّم.`,whenToUseAr:`استخدم Konjunktiv I:
• في الأخبار والصحف ("Der Politiker sagte, er sei unschuldig").
• في الكتابة الأكاديميّة والأبحاث.
• عند نقل كلام شخص آخر مع الحياد (بدون تأكيد صحّته).
⚠️ في الكلام اليوميّ، الألمان غالباً يستخدمون dass + Indikativ بدلاً من Konjunktiv I.`,rules:[{title:`تشكيل Konjunktiv I`,contentAr:`**القاعدة:** جذر الفعل + -e/-est/-e/-en/-et/-en.
**sein استثناء:** ich sei, du seiest, er sei, wir seien, ihr seiet, sie seien.
**haben:** habe/habest/habe/haben/habet/haben.
**werden:** werde/werdest/werde/werden/werdet/werden.`,examples:[{de:`Er sagt, er sei krank.`,ar:`يقول إنّه مريض.`},{de:`Sie behauptet, sie habe kein Geld.`,ar:`تدّعي أنّها لا تملك مالاً.`},{de:`Der Minister sagte, er werde zurücktreten.`,ar:`قال الوزير إنّه سيستقيل.`}]},{title:`متى نستبدل بـKonjunktiv II؟`,contentAr:`عندما تكون صيغة Konjunktiv I مطابقة لـIndikativ (المضارع العادي)، نستبدلها بـKonjunktiv II لتجنّب اللبس.
مثلاً: "sie haben" (مضارع) = "sie haben" (K1) → مربك → نستخدم "sie hätten" (K2).`,examples:[{de:`Sie sagen, sie hätten kein Geld.`,ar:`يقولون إنّهم لا يملكون مالاً. (بدل sie haben)`},{de:`Die Studenten behaupten, sie würden viel lernen.`,ar:`يدّعي الطلّاب أنّهم يدرسون كثيراً.`}]},{title:`الماضي في Konjunktiv I`,contentAr:`**الصيغة:** habe/sei + Partizip II (للماضي البسيط والمضارع التام معاً).`,examples:[{de:`Er sagte, er habe die Prüfung bestanden.`,ar:`قال إنّه نجح في الامتحان.`},{de:`Sie erzählte, sie sei nach Berlin gereist.`,ar:`روت أنّها سافرت إلى برلين.`}]}],commonMistakes:[{wrong:`Er sagt, dass er sei krank.`,right:`Er sagt, er sei krank. / Er sagt, dass er krank ist.`,explanationAr:`مع dass نستخدم Indikativ. Konjunktiv I يأتي **بدون** dass.`},{wrong:`Sie sagen, sie haben kein Geld.`,right:`Sie sagen, sie hätten kein Geld.`,explanationAr:`لأنّ sie haben (K1) = sie haben (Indikativ) → نستخدم Konjunktiv II (hätten).`}],tipsAr:[`الأسهل: احفظ فقط sei/habe/werde + إخراج dass. هذه كافية لمعظم السياقات.`,`في الصحف الألمانيّة (Spiegel, Zeit, FAZ) ترى Konjunktiv I باستمرار — اقرأها لتعتاد.`,`في الكلام اليومي، "Er hat gesagt, dass er krank ist" مقبول — لا تضغط نفسك على K1 شفهياً.`],exercises:[{id:`b2-k1-1`,promptAr:`حوّل للكلام المنقول:`,promptDe:`"Ich bin müde." - Er sagt, ...`,options:[{id:`a`,de:`er ist müde.`},{id:`b`,de:`er sei müde.`},{id:`c`,de:`er wäre müde.`}],correct:`b`,explanationAr:`sein → Konjunktiv I = sei.`},{id:`b2-k1-2`,promptAr:`حوّل:`,promptDe:`"Ich habe Zeit." - Er behauptet, ...`,options:[{id:`a`,de:`er habe Zeit.`},{id:`b`,de:`er hat Zeit.`},{id:`c`,de:`er hätte Zeit.`}],correct:`a`,explanationAr:`haben → K1 = habe (für 3. Person Singular).`},{id:`b2-k1-3`,promptAr:`حوّل:`,promptDe:`"Wir kommen morgen." - Sie sagen, ...`,options:[{id:`a`,de:`sie kommen morgen.`},{id:`b`,de:`sie kämen morgen.`},{id:`c`,de:`sie würden morgen kommen.`}],correct:`c`,explanationAr:`sie kommen (K1) = Indikativ → نستخدم Konjunktiv II (würden kommen).`},{id:`b2-k1-4`,promptAr:`اختر:`,promptDe:`"Ich war gestern im Kino." - Er erzählte, ...`,options:[{id:`a`,de:`er war gestern im Kino.`},{id:`b`,de:`er sei gestern im Kino gewesen.`},{id:`c`,de:`er ist gestern im Kino gewesen.`}],correct:`b`,explanationAr:`الماضي في K1 = sei + gewesen.`},{id:`b2-k1-5`,promptAr:`أيّ صيغة صحيحة في لغة الصحف؟`,promptDe:`Der Kanzler sagte, die Wirtschaft ____ sich erholt.`,options:[{id:`a`,de:`hat`},{id:`b`,de:`habe`},{id:`c`,de:`würde`}],correct:`b`,explanationAr:`habe = K1 لـhaben في 3. Person Singular.`}]},{id:`b2-passiv`,titleAr:`Passiv — المبنيّ للمجهول الكامل (Vorgangs- + Zustandspassiv)`,titleDe:`Passiv (Vorgang & Zustand)`,summaryAr:`المبنيّ للمجهول في الألمانيّة نوعان: Vorgangspassiv (يصف العمليّة) و Zustandspassiv (يصف الحالة النهائيّة). كلاهما مهمّ في B2.`,arabicContrast:`في العربيّة نقول "الباب مفتوح" و "فُتح الباب" بسهولة. في الألمانيّة، "Die Tür wird geöffnet" = تُفتح الآن، و "Die Tür ist geöffnet" = الباب مفتوح (حالة). التمييز بين werden + Partizip II و sein + Partizip II أساسيّ في B2.`,whenToUseAr:`**Vorgangspassiv** (werden + PII): للتركيز على العمليّة/الحركة. "Das Auto wird repariert" = تتمّ عمليّة الإصلاح الآن.
**Zustandspassiv** (sein + PII): للتركيز على النتيجة. "Das Auto ist repariert" = الحالة الآن: السيّارة مُصلَحة.`,rules:[{title:`تشكيل Vorgangspassiv`,contentAr:`**القاعدة:** werden (مُصرَّف) + Partizip II في نهاية الجملة.
أزمنة مختلفة:
• Präsens: Das Auto wird repariert.
• Präteritum: Das Auto wurde repariert.
• Perfekt: Das Auto ist repariert worden.
• Plusquamperfekt: Das Auto war repariert worden.
• Futur: Das Auto wird repariert werden.`,examples:[{de:`Der Brief wird geschrieben.`,ar:`تتمّ كتابة الرسالة.`},{de:`Das Haus wurde 1990 gebaut.`,ar:`بُني البيت عام 1990.`},{de:`Der Kuchen ist gebacken worden.`,ar:`تمّ خبز الكعكة.`}]},{title:`تشكيل Zustandspassiv`,contentAr:`**القاعدة:** sein (مُصرَّف) + Partizip II.
يصف الحالة النهائيّة بعد انتهاء العمليّة.`,examples:[{de:`Das Fenster ist geöffnet.`,ar:`النافذة مفتوحة.`},{de:`Der Brief ist geschrieben.`,ar:`الرسالة مكتوبة (جاهزة).`},{de:`Das Geschäft ist geschlossen.`,ar:`المحلّ مغلق.`}]},{title:`Passiv مع Modalverben`,contentAr:`**القاعدة:** Modalverb + Partizip II + werden (Infinitiv).`,examples:[{de:`Der Brief muss geschrieben werden.`,ar:`يجب أن تُكتب الرسالة.`},{de:`Das kann repariert werden.`,ar:`يمكن إصلاح ذلك.`},{de:`Die Arbeit soll bis morgen gemacht werden.`,ar:`يجب إنجاز العمل حتى الغد.`}]},{title:`بدائل Passiv (Passiv-Ersatzformen)`,contentAr:`**البدائل الشائعة:**
1. man + فعل نشط: "Man repariert das Auto."
2. sich lassen + Infinitiv: "Das lässt sich reparieren." (= يمكن إصلاحه)
3. sein + zu + Infinitiv: "Das Problem ist zu lösen." (= يمكن/يجب حلّ المشكلة)
4. -bar صفة: "reparierbar" (= قابل للإصلاح)`,examples:[{de:`Die Aufgabe ist leicht zu lösen.`,ar:`المهمّة سهلة الحلّ.`},{de:`Das lässt sich nicht ändern.`,ar:`هذا لا يمكن تغييره.`},{de:`Dieses Problem ist lösbar.`,ar:`هذه المشكلة قابلة للحلّ.`}]}],commonMistakes:[{wrong:`Das Auto ist repariert geworden.`,right:`Das Auto ist repariert worden.`,explanationAr:`في Perfekt Passiv، Partizip II لـwerden = worden (بدون ge-).`},{wrong:`Das Fenster wird geöffnet sein.`,right:`Das Fenster ist geöffnet. (Zustandspassiv)`,explanationAr:`لوصف الحالة نستعمل sein + PII مباشرة.`},{wrong:`Der Brief muss geschrieben sein.`,right:`Der Brief muss geschrieben werden.`,explanationAr:`مع Modalverb + Passiv نستخدم werden (Infinitiv) وليس sein.`}],tipsAr:[`تذكّر الفرق: wird + PII = يحدث الآن | ist + PII = النتيجة/الحالة.`,`Partizip II لـwerden = worden (في Passiv) أو geworden (في الماضي العادي).`,`البدائل (man/sich lassen) مفيدة جداً — استعملها لتقلّل Passiv في الكتابة الشفهيّة.`],exercises:[{id:`b2-pa-1`,promptAr:`حوّل للمبنيّ للمجهول:`,promptDe:`Der Chef schreibt den Brief. → Der Brief ____.`,options:[{id:`a`,de:`ist geschrieben`},{id:`b`,de:`wird geschrieben`},{id:`c`,de:`hat geschrieben`}],correct:`b`,explanationAr:`المضارع Vorgangspassiv = wird + Partizip II.`},{id:`b2-pa-2`,promptAr:`اختر:`,promptDe:`Die Suppe ____ gekocht. (Zustand)`,options:[{id:`a`,de:`wird`},{id:`b`,de:`ist`},{id:`c`,de:`hat`}],correct:`b`,explanationAr:`الحالة النهائيّة (جاهزة) = Zustandspassiv = ist + PII.`},{id:`b2-pa-3`,promptAr:`Passiv + Modalverb:`,promptDe:`Die Arbeit muss heute ____.`,options:[{id:`a`,de:`gemacht sein`},{id:`b`,de:`gemacht werden`},{id:`c`,de:`machen werden`}],correct:`b`,explanationAr:`Modal + PII + werden (Infinitiv).`},{id:`b2-pa-4`,promptAr:`Perfekt Passiv:`,promptDe:`Das Haus ____ 1990 gebaut ____.`,options:[{id:`a`,de:`ist / worden`},{id:`b`,de:`hat / geworden`},{id:`c`,de:`war / worden`}],correct:`a`,explanationAr:`Perfekt Passiv = ist/sind + PII + worden.`},{id:`b2-pa-5`,promptAr:`ابحث عن البديل:`,promptDe:`Das Problem kann gelöst werden. ≈ Das Problem ist ____.`,options:[{id:`a`,de:`zu lösen`},{id:`b`,de:`zu lösend`},{id:`c`,de:`gelöst`}],correct:`a`,explanationAr:`sein + zu + Infinitiv = بديل عن Passiv مع können/müssen.`}]},{id:`b2-nominalisierung`,titleAr:`Nominalisierung / Verbalisierung — التحويل بين الفعل والاسم`,titleDe:`Nominalisierung & Verbalisierung`,summaryAr:`في الألمانيّة الأكاديميّة ��الرسميّة، كثير من المعاني تُعبَّر بالأسماء بدل الأفعال. يجب إتقان التحويل في الاتّجاهين.`,arabicContrast:`في العربيّة نقول "عندما وصل المدير" (جملة فعليّة). الألمانيّة الأكاديميّة تُفضّل "Bei der Ankunft des Direktors" (اسم + مضاف إليه). هذا شائع جداً في النصوص المكتوبة والرسميّة.`,whenToUseAr:`استخدم Nominalisierung في:
• الكتابة الرسميّة/الأكاديميّة.
• العناوين والإعلانات.
• لتكثيف المعنى في جملة قصيرة.

استخدم Verbalisierung في:
• الكلام اليوميّ.
• النصوص السرديّة.
• عندما تريد جعل الجملة أوضح.`,rules:[{title:`تحويل الفعل إلى اسم`,contentAr:`**طرق شائعة:**
1. إضافة -ung: arbeiten → Arbeit/Arbeitung، entwickeln → Entwicklung، erklären → Erklärung.
2. مصدر الفعل كاسم (das + Infinitiv): das Lesen، das Schreiben.
3. اسم مستقلّ: schlafen → der Schlaf، gehen → der Gang.`,examples:[{de:`Wir sollten das Problem schnell lösen. → Die schnelle Lösung des Problems ist wichtig.`,ar:`يجب حلّ المشكلة سريعاً. → الحلّ السريع للمشكلة مهمّ.`},{de:`Nachdem er angekommen war... → Nach seiner Ankunft...`,ar:`بعد أن وصل... → بعد وصوله...`}]},{title:`تحويل الاسم إلى فعل`,contentAr:`نستبدل الاسم + حرف الجرّ بجملة فرعيّة (Nebensatz).`,examples:[{de:`Wegen des starken Regens fiel das Spiel aus. → Weil es stark regnete, fiel das Spiel aus.`,ar:`بسبب الأمطار الغزيرة أُلغيت المباراة. → لأنّ الأمطار كانت غزيرة، أُلغيت المباراة.`},{de:`Bei seiner Ankunft... → Als er ankam,...`,ar:`عند وصوله... → عندما وصل،...`}]},{title:`أدوات ربط مناسبة`,contentAr:`**Nominal → Verbal:**
• wegen → weil
• trotz → obwohl
• bei → wenn/als
• nach → nachdem
• vor → bevor
• durch → indem
• zu + Dat → um ... zu / damit
• bei + Inf → beim + Nomen`,examples:[{de:`Trotz seines Alters läuft er jeden Tag.`,ar:`رغم عمره يركض يوميّاً.`},{de:`Obwohl er alt ist, läuft er jeden Tag.`,ar:`رغم أنّه عجوز، يركض يوميّاً.`}]}],commonMistakes:[{wrong:`Die Lösen des Problems ist wichtig.`,right:`Die Lösung des Problems / Das Lösen des Problems ist wichtig.`,explanationAr:`إمّا اسم (Lösung) أو مصدر (das Lösen). لا يصحّ "die Lösen".`},{wrong:`Wegen er krank war, kam er nicht.`,right:`Weil er krank war, kam er nicht.`,explanationAr:`wegen يأخذ اسماً، وليس جملة. للجملة نستخدم weil.`}],tipsAr:[`احفظ اللواحق الشائعة للتحويل: -ung, -heit, -keit, -e, -schaft.`,`التحويل من Nominal إلى Verbal يُسهّل فهم النصوص الصعبة.`,`في Schreiben (كتابة)، استخدم Nominalisierung لرفع مستوى لغتك.`],exercises:[{id:`b2-nom-1`,promptAr:`حوّل لاسم:`,promptDe:`entwickeln → die ____`,options:[{id:`a`,de:`Entwicklung`},{id:`b`,de:`Entwickler`},{id:`c`,de:`Entwickelt`}],correct:`a`,explanationAr:`entwickeln → Entwicklung (لاحقة -ung).`},{id:`b2-nom-2`,promptAr:`حوّل الجملة لفعليّة:`,promptDe:`Wegen des Regens...`,options:[{id:`a`,de:`Weil es regnete,...`},{id:`b`,de:`Wegen es regnete,...`},{id:`c`,de:`Da der Regen,...`}],correct:`a`,explanationAr:`wegen (حرف جرّ) → weil (أداة ربط لجملة).`},{id:`b2-nom-3`,promptAr:`حوّل لاسم:`,promptDe:`Nachdem er angekommen war → Nach ____`,options:[{id:`a`,de:`seine Ankunft`},{id:`b`,de:`seiner Ankunft`},{id:`c`,de:`sein Ankommen`}],correct:`b`,explanationAr:`nach + Dativ → nach seiner Ankunft.`},{id:`b2-nom-4`,promptAr:`أيّ تحويل صحيح؟`,promptDe:`Trotz seines Alters (= "عمره الكبير") → Obwohl ____`,options:[{id:`a`,de:`er alt ist`},{id:`b`,de:`sein Alter`},{id:`c`,de:`trotz alt`}],correct:`a`,explanationAr:`trotz + Nomen → obwohl + Nebensatz.`}]},{id:`b2-partizip`,titleAr:`Partizipialkonstruktionen — Partizip I و II كصفات مُوسَّعة`,titleDe:`Partizip I & II (erweiterte Partizipien)`,summaryAr:`في B2 نتعلّم استخدام Partizip I (-end) و Partizip II كصفات يمكن توسيعها لتختصر جملاً فرعيّة كاملة — شائع جداً في الصحف.`,whenToUseAr:`استخدم Partizipialkonstruktionen في:
• النصوص المكتوبة (صحف، مقالات، تقارير).
• عندما تريد تكثيف المعنى.
• لرفع مستوى Schreiben.

⚠️ استخدمها باعتدال في الكلام اليوميّ.`,rules:[{title:`Partizip I (Präsenspartizip)`,contentAr:`**القاعدة:** Infinitiv + d (laufend, spielend, schlafend).
**الاستخدام:** يصف فعلاً يحدث في نفس الوقت (مثل "الذي ... الآن").`,examples:[{de:`Das schlafende Kind ist süß.`,ar:`الطفل النائم لطيف.`},{de:`Die lachenden Kinder spielen im Park.`,ar:`الأطفال الضاحكون يلعبون في الحديقة.`},{de:`Ein weinendes Baby war im Zimmer.`,ar:`كان هناك طفل يبكي في الغرفة.`}]},{title:`Partizip II كصفة`,contentAr:`**القاعدة:** يستخدم Partizip II نفسه (getan, gelesen, gesehen).
**الاستخدام:** يصف حالة ناتجة عن عمليّة (Passiv-Bedeutung).`,examples:[{de:`Die gekaufte Zeitung liegt auf dem Tisch.`,ar:`الصحيفة المُشتراة على الطاولة.`},{de:`Der geschriebene Brief ist fertig.`,ar:`الرسالة المكتوبة جاهزة.`},{de:`Die reparierten Autos stehen draußen.`,ar:`السيّارات المُصلَحة في الخارج.`}]},{title:`Partizipien موسّعة (Erweiterte Partizipien)`,contentAr:`نضيف مكمّلات (Adverbien, Objekte) قبل Partizip لإطالة الوصف.`,examples:[{de:`Die gestern von mir gekaufte Zeitung...`,ar:`الصحيفة التي اشتريتها أمس...`},{de:`Das im Jahr 1990 gebaute Haus...`,ar:`البيت المبني عام 1990...`},{de:`Ein auf dem Tisch liegendes Buch...`,ar:`كتاب يقع على الطاولة...`}]},{title:`تحويل Partizipialkonstruktion إلى Relativsatz`,contentAr:`Partizip I → der/die/das + verb + Präsens. Partizip II → der/die/das + Partizip II + werden/sein.`,examples:[{de:`Das schlafende Kind → Das Kind, das schläft.`,ar:`الطفل النائم → الطفل الذي ينام.`},{de:`Das reparierte Auto → Das Auto, das repariert wurde/ist.`,ar:`السيّارة المُصلَحة → السيّارة التي أُصلحت.`}]}],commonMistakes:[{wrong:`Das schlafendes Kind.`,right:`Das schlafende Kind.`,explanationAr:`مع das (محايد) + صفة نكرة = das ___e Kind. Partizip I يأخذ نفس نهايات الصفة.`},{wrong:`Die gelesenden Bücher.`,right:`Die gelesenen Bücher.`,explanationAr:`Partizip II = gelesen (وليس gelesend).`}],tipsAr:[`Partizip I يُعبّر عن فعل نشط يحدث الآن. Partizip II يُعبّر عن حالة ناتجة.`,`يأخذ نفس نهايات الصفات (-e, -en, -es, إلخ).`,`في Schreiben (B2), استخدم واحداً أو اثنين لرفع مستوى الكتابة.`],exercises:[{id:`b2-ptz-1`,promptAr:`أيّ Partizip I صحيح؟`,promptDe:`Das ____ Kind schläft im Bett.`,options:[{id:`a`,de:`schlafend`},{id:`b`,de:`schlafende`},{id:`c`,de:`geschlafene`}],correct:`b`,explanationAr:`Partizip I = schlafend + نهاية صفة (das + محايد = -e).`},{id:`b2-ptz-2`,promptAr:`أيّ Partizip II صحيح؟`,promptDe:`Die ____ Zeitung ist interessant.`,options:[{id:`a`,de:`gekaufend`},{id:`b`,de:`gekaufte`},{id:`c`,de:`kaufend`}],correct:`b`,explanationAr:`Partizip II من kaufen = gekauft → صفة مع die = gekaufte.`},{id:`b2-ptz-3`,promptAr:`حوّل لـRelativsatz:`,promptDe:`Das reparierte Auto steht draußen. → Das Auto, das ____`,options:[{id:`a`,de:`repariert ist`},{id:`b`,de:`repariert hat`},{id:`c`,de:`hat repariert`}],correct:`a`,explanationAr:`Zustandspassiv = sein + PII.`}]}];export{e as i,i as n,n as r,a as t};